window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0136", [{"word":"pastoralism","ipa_uk":"/ˈpɑːstərəlɪzəm/","ipa_us":"/ˈpæstərəlɪzəm/","definition_zh":"畜牧经济；随畜群迁移的生活方式；以草场放牧为基础的社会形态；文学中的田园牧歌传统","definition_en":"an economy and way of life built on raising livestock on open pasture, together with the tradition that idealizes it","core_image":"一片随季节移动的草场：毡房收起，羊群跟着水草走，人、畜、草绑在同一条路上。","scene":"天刚亮，毡房已经拆下捆好，羊群被赶向河边的新草场，牧人跟在后面。The family lives by pastoralism, moving its flocks to fresh grass with every season.","sceneCN":"这里 pastoralism 指「以在开阔草场上放牧牲畜为主要生计的经济与生活方式」（第 1 个义项：人、畜、草随季节整体移动的谋生体系）；句意为这家人靠畜牧为生，每个季节都把羊群赶往新的草地。可辨识物件：毡房、捆好的木杆、羊群、牧人、河岸。","pos":[{"tag":"n.","zh":"畜牧经济；游牧生活方式；田园牧歌传统"}],"collocations":[{"phrase":"nomadic pastoralism","zh":"游牧式畜牧"},{"phrase":"sedentary pastoralism","zh":"定居放牧"},{"phrase":"traditional pastoralism","zh":"传统畜牧"},{"phrase":"pastoralism and farming","zh":"畜牧与农耕（并存的生计）"},{"phrase":"the rise of pastoralism","zh":"畜牧业的兴起"},{"phrase":"commercial pastoralism","zh":"商业化畜牧"}],"forms":[{"label":"不可数名词（体系）","form":"pastoralism"},{"label":"形容词（牧人的；田园的）","form":"pastoral"},{"label":"名词（畜牧者）","form":"pastoralist"},{"label":"名词（畜牧者，复数）","form":"pastoralists"},{"label":"副词（田园地）","form":"pastorally"}],"derivatives":[{"word":"pastoral","pos":"adj./n.","zh":"pastor + -al（关系形容词后缀）→ 由「牧人」转为「牧人的、田园的」，并指田园诗"},{"word":"pastoralist","pos":"n.","zh":"pastoral + -ist（从事者后缀）→ 以畜牧为生的人，也指研究畜牧的学者"},{"word":"pastorally","pos":"adv.","zh":"pastoral + -ly（副词后缀）→ 以田园牧歌的方式"},{"word":"pastorale","pos":"n.","zh":"拉丁 pastoralis 经意大利语 → 田园曲，语义由牧人生活收窄为一种音乐体裁"},{"word":"agropastoral","pos":"adj.","zh":"agro-（田地）与 pastoral 复合 → 农牧结合的，语义落在耕作与放牧并行"}],"senses":[{"no":"01","title":"Raise livestock as the main livelihood","titleCN":"以放牧牲畜为主要生计","definition":"to make a living chiefly by raising animals on pasture rather than by growing crops","definitionCN":"主要靠在草场上饲养牲畜、而不是靠耕种来谋生","example":"Pastoralism shaped the economy of the steppe long before railways arrived.","exampleCN":"在铁路出现之前很久，畜牧经济就已经塑造了草原的经济形态。","why":"pastor is a feeder of flocks and -ism names a whole system, so the word first labels an economy built on that role.","whyCN":"pastor 是「喂养畜群的人」，-ism 表示一整套体系，因此这个词首先指建立在这一角色上的经济。"},{"no":"02","title":"Move with the herds each season","titleCN":"随季节带着畜群迁移","definition":"a way of life in which people move their animals from one pasture to another as grass and water change","definitionCN":"草与水发生变化时，人带着牲畜从一片草场迁到另一片草场的生活方式","example":"Pastoralism keeps the household on the move between winter and summer grazing.","exampleCN":"畜牧生活让这个家庭在冬夏两处草场之间不断迁移。","why":"grazing land is renewed unevenly, so the flock must follow the grass, and the household follows the flock.","whyCN":"草场的恢复并不均匀，畜群必须追着草走，而人家又必须跟着畜群走。"},{"no":"03","title":"Use grassland instead of ploughed fields","titleCN":"以草场而非耕地为土地基础","definition":"a land-use system that draws its yield from grazing land rather than from cultivated fields","definitionCN":"从草场而不是从耕地取得产出的土地利用方式","example":"Pastoralism suits the thin soils that would fail under repeated ploughing.","exampleCN":"薄土反复耕作会退化，却适合畜牧。","why":"where rain is scarce and soil shallow, grass feeds animals as well as crops would feed people, so herding becomes the land use.","whyCN":"在雨少土薄之处，草能养畜，其效率不亚于庄稼养人，于是放牧成了这片土地的用法。"},{"no":"04","title":"Share the customs of herder communities","titleCN":"共享牧人群体的习俗与认同","definition":"the body of customs, skills and identity that herding families pass on to their children","definitionCN":"放牧家庭传给下一代的习俗、技能与身份认同","example":"Their pastoralism includes a calendar of moves that no outsider learns in a single year.","exampleCN":"他们的畜牧生活包含一套迁移历法，外人一年之内学不会。","why":"a livelihood repeated for generations becomes a culture, so the same word covers the work and the way of living it.","whyCN":"一种生计重复数代就会成为文化，因此同一个词既指活计，也指过这种活计的方式。"},{"no":"05","title":"Idealize shepherd life in art","titleCN":"在文学艺术中美化牧人生活","definition":"a literary and artistic tradition that presents shepherd life as simple, peaceful and close to nature","definitionCN":"把牧人生活写得朴素、安宁、贴近自然的文学与艺术传统","example":"The pastoralism of the poem owes more to city taste than to any real flock.","exampleCN":"这首诗的田园情调更多来自城市口味，而不是真实的羊群。","why":"Latin pastoralis also named shepherd poems, and that poetic label survived as a term for idealized country life.","whyCN":"拉丁 pastoralis 也指牧人诗，这个诗学标签留存下来，用来指被理想化的乡野生活。"},{"no":"06","title":"Depend on wool, milk and meat","titleCN":"依赖毛、奶、肉等畜产品","definition":"an economy whose cash and food come from animal products rather than from grain sales","definitionCN":"现金与食物来自畜产品、而不是来自售粮的经济","example":"Pastoralism paid the family's taxes in wool and cheese rather than in coin.","exampleCN":"这家人的税是用羊毛和奶酪缴的，而不是用钱币。","why":"once the herd is the main capital, its products become the household's income, which is the economic face of the same system.","whyCN":"一旦畜群成为主要资本，畜产品就成了家庭收入，这是同一体系的经济面孔。"},{"no":"07","title":"Serve as a subsistence model in anthropology","titleCN":"人类学中的一种生计类型模型","definition":"an analytic category that compares herding societies with farming, fishing and hunting ones","definitionCN":"把畜牧社会与农耕、渔猎社会相互比较的分析类别","example":"In the textbook, pastoralism is paired with agriculture as the two dryland options.","exampleCN":"在教科书里，畜牧与农耕被并列为干旱地区的两种选择。","why":"researchers needed a neutral label for a whole livelihood, so they took the older word and turned it into a model.","whyCN":"研究者需要为整套生计找一个中性的标签，于是取来旧词，把它改造成分析模型。"},{"no":"08","title":"Live off a slowly renewed resource","titleCN":"抽象义：依赖缓慢再生的资源","definition":"any arrangement in which a community lives off a resource that renews itself slowly and must be allowed to recover","definitionCN":"任何依赖缓慢再生、且必须留出恢复时间的资源来维持群体的安排","example":"The same logic of pastoralism applies to a forest worked in long cycles.","exampleCN":"同样的畜牧逻辑也适用于按长周期采伐的森林。","why":"the abstract sense keeps only the shape of the old economy: take a little, let it grow back, move on.","whyCN":"抽象义只保留了旧经济的骨架：取一点，让它长回来，再挪到下一处。"}],"etymology":{"intro":{"en":"Pastoralism joins Latin pastor 'shepherd', from pascere 'to feed, graze', to the English suffix -ism. The pastoral adjective entered English in the sixteenth century; the system noun is modern.","cn":"pastoralism 由拉丁 pastor「牧人」（出自 pascere「吃草、放牧」）加英语后缀 -ism 构成。形容词 pastoral 在 16 世纪进入英语，指体系的名词则是近代产物。"},"items":[{"era":"LATIN PASCERE","en":"Pascere meant 'to feed, graze'. It is generally regarded as going back to a root meaning 'to feed, protect', but the Indo-European form given for it is a reconstruction, not a recorded word.","cn":"pascere 意为「吃草、放牧」。一般认为它可追溯到表示「喂养、保护」的词根，但为其给出的印欧形式属重构形式，并非有记录的词。"},{"era":"LATIN PASTOR","en":"Pastor, pastoris 'shepherd' is literally 'one who feeds', formed from the same verb; the religious sense of English pastor came later.","cn":"pastor、pastoris「牧人」字面就是「喂养者」，由同一动词构成；英语 pastor 的宗教义是后来的事。"},{"era":"LATIN PASTORALIS","en":"The adjective pastoralis 'of shepherds' covered both real herding and shepherd poetry, and that double scope passed into English.","cn":"形容词 pastoralis「牧人的」既指真实的放牧，也指牧人诗，这一双重范围一并传入英语。"},{"era":"ENGLISH PASTORAL","en":"From the sixteenth century English pastoral named shepherd verse first and rural scenery second; the noun pastoralism grew out of that adjective.","cn":"从 16 世纪起，英语 pastoral 先指牧人诗，后指乡村景色；名词 pastoralism 正是从这个形容词长出来的。"},{"era":"SUFFIX -ISM","en":"The suffix -ism marks a system, practice or doctrine. Added to pastoral, it produced a word for livestock economies and for the literary ideal built on them.","cn":"后缀 -ism 标记体系、实践或主张。加在 pastoral 上，就造出了指畜牧经济以及建立其上的文学理想的词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the system noun is recorded only from the nineteenth century, and no exact first citation is agreed; the pre-Latin shape of pascere remains a reconstruction.","cn":"来源不确定（首见年代）：指体系的名词只能追溯到 19 世纪，最早书证并无定说；pascere 在拉丁语之前的形式仍属重构。"}]},"similar":{"note":{"en":"Group one holds words from the same feeding root that are easily taken for synonyms; group two holds neighbouring livelihoods with a different centre of gravity.","cn":"第一组是同出「喂养」词根、容易被当成同义词的词；第二组是重心不同的邻近生计词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pastoral","ipa":"/ˈpɑːstərəl/","tag":"same root, adjective","definition":"The adjective of shepherds and of shepherd poetry; it describes a scene or a genre, while pastoralism names the economy or the tradition as a whole.","definitionCN":"牧人与牧人诗的形容词，描写景色或体裁；pastoralism 则指整套经济或整个传统。"},{"word":"pastor","ipa":"/ˈpɑːstə/","tag":"same root, person","definition":"The person who feeds a flock; in modern English its religious sense, a minister, is far more common than the herding one.","definitionCN":"喂养畜群的人；在现代英语里，它的宗教义「牧师」远比放牧义常用。"},{"word":"pasture","ipa":"/ˈpɑːstʃə/","tag":"same root, land","definition":"The ground the animals eat, and the act of putting them on it; it is the land, not the system.","definitionCN":"牲畜吃草的地面，也指把牲畜放上去的动作；它是土地，不是体系。"},{"word":"pastel","ipa":"/ˈpæstl/","tag":"different root","definition":"From Latin pastillus 'little loaf', through Italian, and unrelated to shepherds; only the opening sounds suggest a link.","definitionCN":"来自拉丁 pastillus「小面包」，经意大利语传入，与牧人无关，只是开头读音近似。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nomadism","ipa":"/ˈnəʊmədɪzəm/","tag":"movement, not animals","definition":"A way of life built on moving the whole community; nomads may hunt, trade or herd, so the term says nothing about livestock.","definitionCN":"以整个群体迁移为基础的生活方式；游牧者可以狩猎、贸易或放牧，因此这个词不涉及牲畜。"},{"word":"ranching","ipa":"/ˈrɑːntʃɪŋ/","tag":"owned land, commercial","definition":"Commercial raising of livestock on fenced or owned land; pastoralism usually implies open range and community rights.","definitionCN":"在围起或私有的土地上商业化养畜；pastoralism 通常意味着开阔草场与群体权利。"},{"word":"agropastoralism","ipa":"/ˌæɡrəʊˈpɑːstərəlɪzəm/","tag":"mixed system","definition":"A combined system in which a household both farms and herds; it is a hybrid, not pastoralism alone.","definitionCN":"家庭既耕种又放牧的混合体系，是杂交形态，而非单纯的畜牧。"},{"word":"herding","ipa":"/ˈhɜːdɪŋ/","tag":"the daily activity","definition":"The daily work of driving and watching animals; pastoralism is the whole economy that this work supports.","definitionCN":"每天驱赶与看管牲畜的劳动；pastoralism 是这项劳动所支撑的整套经济。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"pastor 'shepherd' + -ism 'system': the shepherd's work raised to a whole way of living.","cn":"pastor「牧人」+ -ism「体系」：把牧人的活计放大成一整套活法。"},{"en":"The family runs pastor, pastoral, pastoralist, pastoralism and pastorally.","cn":"同族词包括 pastor、pastoral、pastoralist、pastoralism、pastorally。"},{"en":"Fixed phrases mark the types: nomadic pastoralism, sedentary pastoralism, commercial pastoralism.","cn":"固定搭配标出类型：游牧式畜牧、定居放牧、商业化畜牧。"},{"en":"The same feeding root sits in pasture and pascere 'to graze'.","cn":"同一个「喂养」词根也见于 pasture 与 pascere「吃草」。"},{"en":"Anthropology pairs it with agriculture as the two dryland options.","cn":"人类学把它与农耕并列为干旱地区的两种选择。"}],"abstract":[{"en":"Picture a household that owns almost nothing except a moving herd and a route it has used for centuries.","cn":"想象一户人家，除了会走的畜群和一条用了数百年的路线，几乎一无所有。"},{"en":"Picture a field of grass that is never asked for more than it can regrow in a season.","cn":"想象一片草地，从不被索取超过一季能长回来的量。"},{"en":"Picture a poem about shepherds written by someone who has never smelled a sheep.","cn":"想象一首牧人诗，出自从未闻过羊味的人之手。"}]},"examples":[{"en":"Pastoralism survives in the highlands because ploughing there costs more than it returns.","cn":"畜牧在高地得以延续，因为在那里开垦的代价高于收成。"},{"en":"Scholars now treat pastoralism as one option among several, not as an earlier stage of farming.","cn":"学者如今把畜牧视为若干选择之一，而不是农耕的早期阶段。"},{"en":"The museum's pastoralism room explains how wool paid for salt and iron.","cn":"博物馆的畜牧展厅解释羊毛如何换来盐和铁。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pastor（牧人）+ ism（主义）」——把放羊当成一整套活法 → 畜牧经济、田园牧歌传统","word":"pastoralism"},"root":"拉丁 pascere「吃草、放牧」→ pastor「牧人」→ pastoralis「牧人的」+ 英语 -ism（体系后缀）；pascere 的印欧来源属重构形式。英语 pastoralism。","sensesIntro":{"en":"Eight senses follow one circuit: a household feeds a herd, the herd follows the grass, and the whole arrangement is then read as land use, culture, an ideal, an income, a research model and finally a general rule for slow resources.","cn":"八个义项沿一条循环展开：人家养畜群，畜群追草，整套安排再依次被读作土地利用、文化、理想、收入、研究模型，最后读作一条关于缓慢资源的通则。"},"semanticMap":{"core":{"en":"CORE IMAGE: a herder, a flock and a grass route bound into one moving unit.","cn":"核心意象：牧人、畜群与一条草地路线绑成一个会移动的整体。"},"chain":["FEED THE HERD","FOLLOW THE GRASS","LIVE OFF THE LAND","INHERIT THE CUSTOM","IDEALIZE THE LIFE","MODEL THE ECONOMY"],"branches":[{"senses":"01 · 06","en":"LIVELIHOOD AND INCOME: the herd is both the workplace and the household's purse.","cn":"生计与收入：畜群既是干活的地方，也是这户人家的钱袋。"},{"senses":"02 · 03","en":"MOVE AND GRAZE: following the grass turns a way of living into a way of using land.","cn":"迁移与放牧：追着草走，把一种活法变成了土地的用法。"},{"senses":"04 · 05","en":"CUSTOM AND DREAM: what is inherited as skill is also exported as poetry.","cn":"习俗与梦想：当作技艺传下来的东西，也被写成诗传出去。"},{"senses":"07","en":"RESEARCH MODEL: the whole livelihood is abstracted into a category for comparison.","cn":"研究模型：整套生计被抽象成一个可供比较的类别。"},{"senses":"08","en":"SLOW RESOURCE: strip away the sheep and one rule remains, take little and let it grow back.","cn":"缓慢资源：抽掉羊群，只剩一条规则，少取一点，让它长回来。"}]},"affixes":{"intro":{"en":"Pastoralism is built from a Latin noun and two suffixes, so its whole family can be read morpheme by morpheme.","cn":"pastoralism 由一个拉丁名词与两个后缀构成，因此整个词族可以按语素逐个读出。"},"latinIntro":{"en":"Latin pascere gives pastor, pastoralis and pastura; English adds -al, -ist and -ism to build the modern family.","cn":"拉丁 pascere 衍生 pastor、pastoralis 与 pastura；英语再加 -al、-ist 与 -ism 构成现代词族。"},"items":[{"word":"pascere","structure":"pascere (Latin verb, third conjugation)","meaning":"to feed, graze, pasture","meaningCN":"喂养；放牧；吃草","example":"The root names the act of putting animals on grass.","exampleCN":"这个词根指把牲畜放到草上的动作。"},{"word":"pastor","structure":"pastor, pastoris (Latin noun, third declension)","meaning":"shepherd, one who feeds","meaningCN":"牧人；喂养者","example":"The noun names the person who does the feeding.","exampleCN":"这个名词指执行喂养的人。"},{"word":"pastoralis","structure":"pastoralis, pastorale (Latin adjective, third declension)","meaning":"of shepherds, rural","meaningCN":"牧人的；乡野的","example":"The adjective covers both real flocks and shepherd verse.","exampleCN":"这个形容词既指真实的羊群，也指牧人诗。"},{"word":"-al","structure":"-alis (Latin adjective suffix, through French -al)","meaning":"relating to","meaningCN":"与……有关的","example":"Pastor plus -al yields the English adjective pastoral.","exampleCN":"pastor 加 -al 得出英语形容词 pastoral。"},{"word":"-ist","structure":"-ista (agent suffix, through French and Latin)","meaning":"one who practices or studies","meaningCN":"从事者；研究者","example":"Pastoral plus -ist yields pastoralist.","exampleCN":"pastoral 加 -ist 得出 pastoralist。"},{"word":"-ism","structure":"-ismus (system or practice suffix, from Greek -ismos)","meaning":"a system, practice or doctrine","meaningCN":"体系、实践或主张","example":"Pastoral plus -ism yields pastoralism.","exampleCN":"pastoral 加 -ism 得出 pastoralism。"},{"word":"pastoral","structure":"pastor + -al","meaning":"of shepherds; rural; a shepherd poem","meaningCN":"牧人的；田园的；田园诗","example":"The pastoral scene hung above the fireplace.","exampleCN":"那幅田园画挂在壁炉上方。"},{"word":"pastoralist","structure":"pastoral + -ist","meaning":"a person who lives by herding","meaningCN":"以畜牧为生的人","example":"The pastoralist knew every well along the route.","exampleCN":"这位畜牧者熟悉沿线每一口井。"},{"word":"pastorally","structure":"pastoral + -ly","meaning":"in a rural, shepherd-like manner","meaningCN":"以田园牧歌的方式","example":"The valley is pastorally quiet in early spring.","exampleCN":"初春时这道山谷安静得像田园牧歌。"}],"latinEntries":[{"word":"pascere","structure":"pascere, pavi, pastum (verb, third conjugation)","meaning":"to feed, graze","meaningCN":"喂养；放牧"},{"word":"pastor","structure":"pastor, pastoris (m., third declension)","meaning":"shepherd","meaningCN":"牧人"},{"word":"pastoralis","structure":"pastoralis, pastorale (adjective, third declension)","meaning":"of a shepherd","meaningCN":"牧人的"},{"word":"pastura","structure":"pastura, pasturae (f., first declension)","meaning":"grazing, pasture","meaningCN":"放牧；牧场"}]}},{"word":"herding","ipa_uk":"/ˈhɜːdɪŋ/","ipa_us":"/ˈhɜːrdɪŋ/","definition_zh":"放牧；看管畜群；把散开的人或物收拢到一处；群居动物聚成一团的习性","definition_en":"the work of driving and watching a group of animals, and by extension the gathering of people or things into one group","core_image":"牧羊犬在草坡两侧来回奔跑，把散开的羊只向中间收拢成一片移动的白云。","scene":"草坡上，牧羊犬从两侧来回奔跑，把散开的羊群收拢成一片。The shepherds spend the summer herding sheep across the high pastures.","sceneCN":"这里 herding 指「把牲畜赶到草场上并加以看管的日常劳动」（第 1 个义项：驱赶与收拢畜群的动作）；句意为牧人们在夏季把羊群放牧到高处草场。可辨识物件：牧羊犬、草坡、羊群、牧人、牧杖。","pos":[{"tag":"n.","zh":"放牧；看管畜群；（人群的）驱赶收拢"},{"tag":"v.","zh":"herd 的现在分词：把……赶到一起；放牧"}],"collocations":[{"phrase":"herding sheep","zh":"放羊"},{"phrase":"herding cattle","zh":"放牛"},{"phrase":"herding dogs","zh":"牧羊犬"},{"phrase":"herding instinct","zh":"群居聚拢的本能"},{"phrase":"herding people into","zh":"把人们驱赶进（某处）"},{"phrase":"nomadic herding","zh":"游牧式放牧"}],"forms":[{"label":"原形动词","form":"herd"},{"label":"三单（he/she/it）","form":"herds"},{"label":"过去式","form":"herded"},{"label":"过去分词","form":"herded"},{"label":"现在分词 / 名词","form":"herding"},{"label":"名词（畜群）","form":"herd / herds"}],"derivatives":[{"word":"herd","pos":"n./v.","zh":"古英语 heord（畜群）→ 兼作动词，语义由「一群牲畜」转为「把牲畜聚成一群」"},{"word":"herder","pos":"n.","zh":"herd + -er（施事后缀）→ 放牧者，语义落在日常照看的人"},{"word":"herdsman","pos":"n.","zh":"herd + 属格 -s + man（人）→ 牧人，语义偏重职业身份"},{"word":"herdswoman","pos":"n.","zh":"herdsman 的 man 换为 woman → 女牧人，语义仅改性别"},{"word":"herdlike","pos":"adj.","zh":"herd + -like（相似后缀）→ 像畜群一样的，语义偏重成群移动"}],"senses":[{"no":"01","title":"Drive livestock to pasture","titleCN":"把牲畜赶到草场放牧","definition":"the act of driving animals out to grass and keeping them there while they feed","definitionCN":"把牲畜赶到草地上，并在它们吃草时留在那里看管的行为","example":"Herding starts before sunrise, while the grass is still wet.","exampleCN":"放牧在天亮前就开始，那时草还湿着。","why":"the verb herd began as the daily act of driving animals to feed, so the -ing form names that act first.","whyCN":"动词 herd 最初就指每天把牲畜赶去吃草，因此 -ing 形式首先指这个动作。"},{"no":"02","title":"Tend a flock as an occupation","titleCN":"以看管畜群为职业","definition":"the paid or family work of watching a group of animals through the day and keeping them together","definitionCN":"整天看管一群牲畜、不让它们走散的有偿或家庭劳动","example":"Herding pays badly in cash but well in milk and wool.","exampleCN":"放牧的现金报酬很低，奶和羊毛的回报却不错。","why":"driving animals and watching them are one job, so the act noun also names the occupation built on it.","whyCN":"赶牲畜与看牲畜是同一件活，因此这个动作名词也指以此为生的职业。"},{"no":"03","title":"Gather scattered people or things","titleCN":"把散开的人或物收拢到一处","definition":"to collect scattered individuals into one place, as a dog collects sheep","definitionCN":"把散开的个体收拢到一处，如同牧犬收拢羊只","example":"Herding the children into the bus took ten minutes.","exampleCN":"把孩子们收拢上校车花了十分钟。","why":"the picture of a dog circling scattered sheep is applied unchanged to any crowd that must be collected.","whyCN":"牧犬绕着散羊收拢的画面被原样搬用到任何需要被聚拢的人群上。"},{"no":"04","title":"Push a crowd in one direction","titleCN":"把人群朝一个方向驱赶","definition":"to move a group of people steadily in one direction, often with little choice left to them","definitionCN":"把一群人稳定地朝一个方向赶，往往不给他们多少选择","example":"Guards were herding the crowd toward the single open gate.","exampleCN":"警卫把人群往唯一开着的门那边赶。","why":"animals are moved by pressure from behind, and the human use of the word keeps that pressure in view.","whyCN":"牲畜是被后方的压力赶动的，这个词用于人时保留了那种压力感。"},{"no":"05","title":"Work with dogs to control a flock","titleCN":"借助牧犬控制畜群的作业方式","definition":"the technique of controlling animals through trained dogs that flank and block them","definitionCN":"通过受训犬只在侧翼与前方拦截来控制牲畜的技术","example":"Herding with two dogs keeps a flock of three hundred together.","exampleCN":"用两只狗放牧，能让三百只羊不散群。","why":"in many regions the work is defined by the dog rather than the staff, so the practice takes the same name.","whyCN":"在许多地区，这活靠的是狗而不是牧杖，因此这种作业方式也用同一个名称。"},{"no":"06","title":"Cluster together as a social species","titleCN":"群居动物聚成一团的习性","definition":"the tendency of certain animals to stay close together in a group as protection against predators","definitionCN":"某些动物为防捕食者而保持彼此靠近、聚成一团的倾向","example":"Herding in antelope makes a single hunter's odds much worse.","exampleCN":"羚羊成群，使单个猎手的胜算大大降低。","why":"the behaviour looks like the work from the outside, so ecology borrowed the farm word for it.","whyCN":"这种行为从外面看就像放牧，因此生态学借用了农场的词来指它。"},{"no":"07","title":"Sort people into a pen","titleCN":"把人像牲口一样归入某类或赶进某处","definition":"to put people into a category or a confined place as if they were stock, usually with disapproval","definitionCN":"像对待牲畜那样把人归入某一类或赶进封闭之处，通常带贬义","example":"The report accused the agency of herding applicants into one narrow scheme.","exampleCN":"报告指责该机构把申请者统统赶进一个狭窄的方案里。","why":"once the word covers crowds, the stockyard image follows: people are penned by category.","whyCN":"一旦这个词能指人群，牲口栏的画面就跟着来了：人被按类别关进栏里。"},{"no":"08","title":"Raise stock as a livelihood","titleCN":"作为生计的畜牧活动","definition":"livestock raising as a household's main source of food and income, seen as an activity rather than a system","definitionCN":"作为家庭食物与收入主要来源的养畜活动，被看作一项活动而非整套体系","example":"Herding and fishing alternate with the seasons along this coast.","exampleCN":"在这片海岸，放牧与捕鱼随季节交替。","why":"the activity noun stands in for the livelihood whenever a speaker does not need the fuller word pastoralism.","whyCN":"当说话人不需要用更完整的 pastoralism 时，这个活动名词就代替了整套生计。"}],"etymology":{"intro":{"en":"Herding is the -ing form of herd, an Old English verb of the Germanic stock; it has no Latin ancestor, and its deeper origin is not settled.","cn":"herding 是 herd 的 -ing 形式，herd 是日耳曼语系的古英语动词，没有拉丁语祖先，其更深来源亦无定论。"},"items":[{"era":"OLD ENGLISH HEORD","en":"Heord meant 'a group of animals kept together'. It is generally regarded as coming from a Germanic noun seen also in German Herde, but the reconstructed Germanic shape is a reconstruction, not a recorded form.","cn":"heord 意为「聚在一起的一群牲畜」。一般认为它来自一个也见于德语 Herde 的日耳曼名词，但重构出的日耳曼语形式属重构形式，并非有记录的形式。"},{"era":"OLD ENGLISH HIERDAN","en":"The verb hierdan 'to tend, drive animals' was formed beside the noun and is the direct source of English herd.","cn":"动词 hierdan「看管、驱赶牲畜」与名词同时存在，是英语 herd 的直接来源。"},{"era":"MIDDLE ENGLISH","en":"Middle English herden kept both the noun and the verb, and the -ing form herding appears as a verbal noun for the work.","cn":"中古英语 herden 同时保留名词与动词，-ing 形式 herding 作为指这项劳动的名词出现。"},{"era":"DOG WORK","en":"From the sixteenth century herding is often described together with trained dogs, and the practice sense grew from those accounts.","cn":"从 16 世纪起，herding 常与受训犬只一起被记述，指作业方式的义项即由这些记载生长出来。"},{"era":"FIGURATIVE USE","en":"The crowd sense is modern and journalistic: people are described as herded when they are moved with as little choice as animals.","cn":"指人群的义项是近代新闻用法：当人被像牲畜一样驱赶、几乎没有选择时，就说他们被 herded。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the link of the Germanic noun to a wider Indo-European root is debated, so any such form offered here is a reconstruction.","cn":"来源不确定（更深词源）：这个日耳曼名词与更广的印欧词根的联系有争议，凡此处给出的此类形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words from the same English stock that are routinely confused; group two holds verbs of moving animals or people that differ in force and scale.","cn":"第一组是同出英语词源、常被混用的词；第二组是驱赶畜群或人群、但在力度与规模上不同的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"herd","ipa":"/hɜːd/","tag":"base form","definition":"The noun for the group and the verb for driving it; herding is only the -ing form of that verb.","definitionCN":"指畜群的名词，也指驱赶畜群的动词；herding 只是该动词的 -ing 形式。"},{"word":"heard","ipa":"/hɜːd/","tag":"different word","definition":"The past tense of hear, with no connection to animals; it is confused only because the sounds match exactly.","definitionCN":"hear 的过去式，与牲畜毫无关系，只因为读音完全相同才被混淆。"},{"word":"herder","ipa":"/ˈhɜːdə/","tag":"person","definition":"The person who herds; the -er suffix marks the doer rather than the activity.","definitionCN":"放牧的人；-er 后缀标记的是施事者，而不是活动本身。"},{"word":"herdsman","ipa":"/ˈhɜːdzmən/","tag":"occupational title","definition":"A more formal word for a professional keeper of stock, often in older texts.","definitionCN":"对职业牧人更正式的称呼，多见于较早的文本。"}]},{"heading":"NEAR MEANING","entries":[{"word":"driving","ipa":"/ˈdraɪvɪŋ/","tag":"force from behind","definition":"Moving animals or people forward by pressure; it stresses motion, while herding stresses keeping a group together.","definitionCN":"靠压力把牲畜或人向前赶；它强调移动，herding 强调把一群保持在一起。"},{"word":"tending","ipa":"/ˈtendɪŋ/","tag":"care, not motion","definition":"Looking after animals without necessarily moving them; it covers feeding, health and shelter.","definitionCN":"照看牲畜而不一定赶动它们，包含喂食、健康与圈舍。"},{"word":"rounding up","ipa":"/ˌraʊndɪŋ ˈʌp/","tag":"one gathering act","definition":"A single act of collecting scattered animals; herding is the continuous daily work.","definitionCN":"把散开的牲畜收拢一次的举动；herding 是每天持续进行的劳动。"},{"word":"pastoralism","ipa":"/ˈpɑːstərəlɪzəm/","tag":"whole system","definition":"The economy and culture built on livestock; herding is only the daily work inside it.","definitionCN":"建立在牲畜之上的经济与文化；herding 只是其中的日常劳动。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Old English pair of noun and verb, real compounds and real fixed phrases.","cn":"正常联想：真实的古英语名动配对、真实复合词与真实固定搭配。"},"normal":[{"en":"heord 'group of animals' + hierdan 'to drive them': the noun and the verb were born together.","cn":"heord「一群牲畜」+ hierdan「驱赶它们」：名词与动词是一起诞生的。"},{"en":"The family runs herd, herder, herding, herdsman and herdswoman.","cn":"同族词包括 herd、herder、herding、herdsman、herdswoman。"},{"en":"Fixed phrases mark the job: herding sheep, herding cattle, herding dogs.","cn":"固定搭配标出这项工作：放羊、放牛、牧羊犬。"},{"en":"The same Germanic stock gives German Herde and English herd.","cn":"同一日耳曼词源给出德语 Herde 与英语 herd。"},{"en":"Ecology speaks of a herding instinct in antelope and wildebeest.","cn":"生态学说羚羊与角马有群聚本能。"}],"abstract":[{"en":"Picture a dog drawing a wide circle while a hundred white dots slowly become one white patch.","cn":"想象一只狗画出一个大圈，一百个白点慢慢变成一块白斑。"},{"en":"Picture a crowd pushed through one narrow gate until the gate is all anyone can see.","cn":"想象人群被推过一道窄门，直到所有人眼里只剩那道门。"},{"en":"Picture animals standing shoulder to shoulder because the grass around them is empty.","cn":"想象牲畜肩并肩站着，因为四周的草已经空了。"}]},"examples":[{"en":"Herding is easier in the cool hours, when the animals do not scatter.","cn":"凉爽的时候放牧更容易，那时牲畜不散群。"},{"en":"The film shows herding dogs working a flock without a single command.","cn":"影片展示牧羊犬不用一声口令就驱拢羊群。"},{"en":"Critics say the policy is herding poor families into distant suburbs.","cn":"批评者说这项政策正把贫困家庭赶向远郊。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「herd（一群牲畜）+ ing」——把一群牲畜赶成一片 → 放牧、收拢人群","word":"herding"},"root":"古英语 heord「一群牲畜」与 hierdan「驱赶、看管」；同出日耳曼语系，德语作 Herde；更深印欧来源有争议，相关形式属重构。英语 herd → herding。","sensesIntro":{"en":"Eight senses follow one motion: scattered animals are drawn into one moving group. The motion then becomes an occupation, a technique with dogs, a crowd pushed through a gate, a clustering instinct and finally a whole livelihood.","cn":"八个义项沿同一个动作展开：散开的牲畜被收拢成一片会移动的群。这个动作再依次变成职业、借犬作业的技术、被赶过门的人群、聚团的习性，最后变成整套生计。"},"semanticMap":{"core":{"en":"CORE IMAGE: a moving white patch made of many animals kept from scattering.","cn":"核心意象：由许多牲畜聚成、始终不散的一片移动白斑。"},"chain":["DRIVE TO GRASS","KEEP TOGETHER","MAKE A LIVING","USE A DOG","PUSH A CROWD","CLUSTER BY INSTINCT"],"branches":[{"senses":"01 · 08","en":"DAILY ACT AND LIVELIHOOD: the same work is looked at as a morning's task and as a family's income.","cn":"日常动作与生计：同一件活，既可看作一个早晨的任务，也可看作全家的收入。"},{"senses":"02 · 05","en":"KEEPING THE GROUP: watching a flock all day and using dogs to hold its edges are two faces of the same skill.","cn":"守住一群：整天看管羊群与用狗守住群缘，是同一门手艺的两面。"},{"senses":"03 · 04","en":"COLLECT AND PUSH: gathering the scattered and moving the gathered are the two halves of one crowd action.","cn":"收拢与驱赶：把散的聚起来，再把聚起来的赶走，是同一个群体动作的两半。"},{"senses":"06","en":"INSTINCT: ecology borrows the farm picture for animals that cluster without a keeper.","cn":"本能：生态学借来农场的画面，指没有牧人也会聚团的动物。"},{"senses":"07","en":"PENNING PEOPLE: once the crowd is the object, the stockyard image turns critical.","cn":"把人关栏：一旦对象变成人群，牲口栏的画面就带上了批评意味。"}]},"affixes":{"intro":{"en":"Herding has no Latin parts: it is an Old English noun and verb plus the English suffix -ing, with later agent and compound forms.","cn":"herding 没有拉丁成分：它由古英语名词与动词加英语后缀 -ing 构成，施事与复合形式都是后来形成的。"},"latinIntro":{"en":"No Latin relative exists in this line, so the Latin list stays empty; the family is Germanic and English throughout.","cn":"这一词线没有拉丁同族词，因此拉丁列表留空；整个词族自始至终属日耳曼语与英语。"},"items":[{"word":"heord","structure":"heord (Old English noun, 'group of animals')","meaning":"a herd, a group of animals","meaningCN":"畜群；一群牲畜","example":"The noun named the group before the verb named the work.","exampleCN":"名词先给这一群命名，动词后才给这项劳动命名。"},{"word":"hierdan","structure":"hierdan (Old English verb, weak class)","meaning":"to tend, drive animals","meaningCN":"看管；驱赶牲畜","example":"The verb is the direct source of English herd.","exampleCN":"这个动词是英语 herd 的直接来源。"},{"word":"herd","structure":"herd (English noun and verb)","meaning":"a group of animals; to drive such a group","meaningCN":"畜群；驱赶畜群","example":"A herd of goats crossed the road.","exampleCN":"一群山羊穿过道路。"},{"word":"-ing","structure":"-ing (English suffix, verbal noun)","meaning":"the act or process of doing","meaningCN":"动作或过程","example":"Herd plus -ing yields herding, the work itself.","exampleCN":"herd 加 -ing 得出 herding，即这项工作本身。"},{"word":"-er","structure":"-er (English agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"Herd plus -er yields herder.","exampleCN":"herd 加 -er 得出 herder。"},{"word":"herder","structure":"herd + -er","meaning":"a person who tends animals","meaningCN":"照看牲畜的人","example":"The herder counted the flock twice.","exampleCN":"牧人数了两遍羊群。"},{"word":"herdsman","structure":"herd + genitive -s + man","meaning":"a professional keeper of stock","meaningCN":"职业牧人","example":"The herdsman slept beside the pen.","exampleCN":"牧人睡在羊栏旁边。"},{"word":"herdswoman","structure":"herdsman with man replaced by woman","meaning":"a woman who tends stock","meaningCN":"女牧人","example":"The herdswoman knew each ewe by name.","exampleCN":"这位女牧人给每只母羊都起了名字。"},{"word":"herding","structure":"herd + -ing","meaning":"the work of driving and watching a group","meaningCN":"驱赶与看管畜群的劳动","example":"Herding begins at dawn.","exampleCN":"放牧从黎明开始。"}],"latinEntries":[]}},{"word":"herdsman","ipa_uk":"/ˈhɜːdzmən/","ipa_us":"/ˈhɜːrdzmən/","definition_zh":"牧人；畜群看管者；牧场雇工；宗教比喻中的牧养者","definition_en":"a person who watches over and drives a herd of animals, either for a family or for an employer","core_image":"一个裹着旧毯子的人坐在羊栏边的石头上，手里的牧杖横在膝上，眼睛跟着每一只走动的羊。","scene":"夜里风大，羊栏边的石头上坐着一个人，牧杖横放膝头，眼睛跟着每一只羊。An old herdsman watched the flock while the others slept.","sceneCN":"这里 herdsman 指「看管并驱赶畜群的牧人」（第 1 个义项：以照看一群牲畜为职责的人）；句意为一位老牧人在其他人睡着时看守羊群。可辨识物件：羊栏、石头、牧杖、旧毯子、羊群。","pos":[{"tag":"n.","zh":"牧人；畜群看管者；（比喻）牧养者"}],"collocations":[{"phrase":"a nomadic herdsman","zh":"游牧的牧人"},{"phrase":"a cattle herdsman","zh":"牛倌"},{"phrase":"an experienced herdsman","zh":"经验丰富的牧人"},{"phrase":"the herdsman's staff","zh":"牧人的杖"},{"phrase":"herdsman of the steppe","zh":"草原牧人"}],"forms":[{"label":"单数","form":"herdsman"},{"label":"复数（不规则）","form":"herdsmen"},{"label":"阴性形式","form":"herdswoman"},{"label":"阴性复数","form":"herdswomen"},{"label":"同义职业词","form":"herder"}],"derivatives":[{"word":"herd","pos":"n./v.","zh":"古英语 heord（畜群）→ 由「一群牲畜」转为「把牲畜聚成一群」"},{"word":"herder","pos":"n.","zh":"herd + -er（施事后缀）→ 牧人，语义偏重日常照看者"},{"word":"herdswoman","pos":"n.","zh":"herdsman 的 man 换为 woman → 女牧人，语义仅改性别"},{"word":"herdsmanship","pos":"n.","zh":"herdsman + -ship（技艺或身份后缀）→ 牧放的本领与职责，语义由人转为能力"},{"word":"herding","pos":"n.","zh":"herd + -ing（动作名词后缀）→ 放牧这项劳动，语义由人转为活动"}],"senses":[{"no":"01","title":"A person who watches a herd","titleCN":"看管畜群的人","definition":"a person whose job is to keep a group of animals together and safe while they feed","definitionCN":"职责是在牲畜吃草时把它们聚在一起并保其安全的人","example":"An old herdsman watched the flock while the others slept.","exampleCN":"一位老牧人在其他人睡着时看守羊群。","why":"herd plus man simply names the person attached to the herd, so the basic sense is the keeper himself.","whyCN":"herd 加 man 直接指与畜群相连的人，因此最基本的义项就是看管者本人。"},{"no":"02","title":"Hired labour on a ranch","titleCN":"牧场上的雇工","definition":"a paid worker who tends stock on land owned by someone else","definitionCN":"在他人所有的土地上照看牲畜、领取报酬的工人","example":"The ranch hired two herdsmen for the lambing season.","exampleCN":"牧场在产羔季雇了两名牧工。","why":"once herding became wage work, the title split off from the owner and named the employee.","whyCN":"一旦放牧变成雇佣劳动，这个称呼就与所有者分开，用来指受雇者。"},{"no":"03","title":"A keeper of one kind of animal","titleCN":"专看某一种牲畜的人","definition":"a specialist who tends a single species, such as cattle, goats or camels","definitionCN":"只照看一种牲畜的专门人员，如牛、山羊或骆驼","example":"The cattle herdsman knew which cow would calve first.","exampleCN":"牛倌知道哪头母牛会先产犊。","why":"where a village keeps several species, the work divides, and the title takes the animal's name in front.","whyCN":"当村庄饲养数种牲畜时，工作会分门，称呼就在前面加上牲畜之名。"},{"no":"04","title":"Owner or manager of stock","titleCN":"牲畜的所有者或管理者","definition":"in older usage, the person who owns or directs the herd rather than only tending it","definitionCN":"在较早用法中，指拥有或支配畜群的人，而不只是照看者","example":"The herdsman whose brand marked the cattle also decided where they grazed.","exampleCN":"给牛打上烙印的畜主也决定它们去哪里吃草。","why":"before specialised labour, the keeper and the owner were often the same man, and the word covered both.","whyCN":"在分工之前，看管者与所有者常是同一个人，这个词因而兼指两者。"},{"no":"05","title":"A religious figure who tends souls","titleCN":"宗教比喻中的牧养者","definition":"a minister pictured as a shepherd guiding and protecting a congregation","definitionCN":"被比作牧羊人、引导并保护会众的宗教人员","example":"The sermon called every pastor a herdsman of people, not of sheep.","exampleCN":"布道把每位牧师称为人的牧人，而不是羊的牧人。","why":"the Bible uses shepherd imagery for leaders, and English sermons carried that imagery into herdsman language.","whyCN":"《圣经》用牧羊人的形象指领导者，英语布道把这一形象带进了 herdsman 的说法。"},{"no":"06","title":"An archetype in myth and literature","titleCN":"神话与文学中的牧人原型","definition":"the stock figure of the lonely keeper, often a guide, a singer or a witness in stories","definitionCN":"故事中孤独看管者的定型形象，常充当引路人、歌者或见证者","example":"In the legend the herdsman is the only one who sees the stranger arrive.","exampleCN":"传说中，牧人是唯一看见陌生人到来的人。","why":"a keeper who sits through the night sees what sleeping villages miss, so stories place him at the edge of events.","whyCN":"守夜的人看见睡着的村庄看不见的事，因此故事把他放在事件的边缘。"},{"no":"07","title":"One who guides a crowd","titleCN":"比喻义：带领并照看一群人的人","definition":"a leader described as keeping a group together and moving it safely, with a hint of care","definitionCN":"被描述为把一群人聚住并安全带走的人，含照料意味","example":"The strike leader acted as a herdsman for two hundred frightened workers.","exampleCN":"罢工领袖像牧人一样带着两百名惊恐的工人。","why":"guiding people and guiding animals share the same gestures, so the farm title transfers with its protective tone.","whyCN":"带人和带牲畜的手势相同，因此这个农场称呼连同其保护口吻一起转移过来。"},{"no":"08","title":"Any keeper of a dependent group","titleCN":"抽象义：任何照料并引导一群对象的人","definition":"anyone responsible for keeping a dependent collection together, whether animals, people or data","definitionCN":"负责把一群依赖性的对象聚住并照看的任何人，无论对象是牲畜、人还是数据","example":"The archive's herdsman kept ten thousand files from drifting apart.","exampleCN":"档案馆的看管人让一万份文件不致散失。","why":"the abstract sense keeps only the role: something scattered needs one person who holds it together.","whyCN":"抽象义只保留角色本身：散开的东西需要一个把它们聚住的人。"}],"etymology":{"intro":{"en":"Herdsman is an English compound of herd and man, with a genitive -s between them. Both parts are Old English and Germanic; no Latin element is involved.","cn":"herdsman 是 herd 与 man 的英语复合词，中间有属格 -s。两部分都属古英语与日耳曼语，不含拉丁成分。"},"items":[{"era":"OLD ENGLISH HEORD","en":"Heord 'group of animals' is the first element; its Germanic shape is reconstructed, and the exact wider Indo-European link is disputed.","cn":"heord「一群牲畜」是第一部分；其日耳曼语形式属重构，更广的印欧联系有争议。"},{"era":"OLD ENGLISH MAN","en":"Man meant 'human being, person' and still did when the compound formed; the modern restriction to an adult male came later.","cn":"man 意为「人、人类」，复合词形成时仍是此义；后来才收窄为成年男性。"},{"era":"GENITIVE -S","en":"The -s is the old genitive ending, so herdsman originally meant 'the herd's man', the man belonging to the herd.","cn":"这个 -s 是古属格词尾，因此 herdsman 原意是「畜群的人」，即属于这群牲畜的人。"},{"era":"MIDDLE ENGLISH","en":"Middle English herdesman kept the compound for a professional keeper, alongside the shorter herd and herder.","cn":"中古英语 herdesman 保留了这个复合词，指职业看管者，同时还有更短的 herd 与 herder。"},{"era":"RELIGIOUS USE","en":"From the sixteenth century English sermons applied shepherd and herdsman imagery to clergy, adding the figurative sense.","cn":"从 16 世纪起，英语布道把牧羊人与牧人的形象用于神职人员，增添了比喻义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the precise first written appearance of the compound is not fixed, and the pre-Germanic origin of heord remains unsettled.","cn":"来源不确定（首见年代）：这个复合词确切的首次书面出现并无定说，heord 在日耳曼语之前的来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds titles from the same herding stock that differ only in formality or gender; group two holds words for people who look after animals or people.","cn":"第一组是同出放牧词源、只在正式程度或性别上不同的称呼；第二组是照看动物或照看人的邻近词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"herder","ipa":"/ˈhɜːdə/","tag":"plain agent noun","definition":"The everyday word for a keeper of animals, formed with -er; herdsman is the older, more formal title.","definitionCN":"指牲畜看管者的日常词，由 -er 构成；herdsman 是更古老、更正式的称呼。"},{"word":"herd","ipa":"/hɜːd/","tag":"the group, not the person","definition":"The animals themselves, or the verb for driving them; it never names the keeper.","definitionCN":"指牲畜本身，或指驱赶它们的动词，从不指看管者。"},{"word":"herdswoman","ipa":"/ˈhɜːdzwʊmən/","tag":"feminine form","definition":"The same job with woman in place of man; the plural is herdswomen.","definitionCN":"同一职业，把 man 换成 woman；复数为 herdswomen。"},{"word":"shepherd","ipa":"/ˈʃepəd/","tag":"different stock","definition":"From sheep plus hierde 'herder', so it is a compound of a different animal and an older agent noun, not a variant of herdsman.","definitionCN":"由 sheep 加 hierde「牧人」构成，是另一种牲畜与更古老施事名词的复合，并非 herdsman 的变体。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cowboy","ipa":"/ˈkaʊbɔɪ/","tag":"cattle work, American","definition":"A rider who works cattle on open range; the word stresses horses and driving rather than daily watching.","definitionCN":"在开阔牧场上骑马管牛的人；这个词强调马与驱赶，而非日常看管。"},{"word":"stockman","ipa":"/ˈstɒkmən/","tag":"farm term","definition":"A farm worker who handles livestock; it is an agricultural job title rather than a cultural one.","definitionCN":"料理牲畜的农场工人；它是农业职称，而非文化称呼。"},{"word":"pastor","ipa":"/ˈpɑːstə/","tag":"religious sense only","definition":"A minister; its literal shepherd sense is historical, while herdsman keeps the animal sense alive.","definitionCN":"牧师；其字面的牧人义已属历史，而 herdsman 仍保留牲畜义。"},{"word":"rancher","ipa":"/ˈrɑːntʃə/","tag":"owner, not keeper","definition":"The owner or manager of a ranch; herdsman names the person who does the daily watching.","definitionCN":"牧场所有者或经营者；herdsman 指做日常看管的人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real genitive compound, real relatives and real occupational phrases.","cn":"正常联想：真实的属格复合、真实同族词与真实职业搭配。"},"normal":[{"en":"herd + genitive -s + man: literally 'the herd's man'.","cn":"herd + 属格 -s + man：字面就是「畜群的人」。"},{"en":"The family runs herd, herder, herding, herdsman, herdswoman, herdsmanship.","cn":"同族词包括 herd、herder、herding、herdsman、herdswoman、herdsmanship。"},{"en":"Fixed phrases mark the job: a cattle herdsman, a nomadic herdsman, the herdsman's staff.","cn":"固定搭配标出这一职业：牛倌、游牧牧人、牧人的杖。"},{"en":"Shepherd is a parallel compound, sheep plus the older agent noun hierde.","cn":"shepherd 是平行复合词，由 sheep 加更古老的施事名词 hierde 构成。"},{"en":"The irregular plural herdsmen keeps the old genitive sound.","cn":"不规则复数 herdsmen 保留了古属格的读音。"}],"abstract":[{"en":"Picture one man awake at night so that a hundred animals can sleep standing up.","cn":"想象一个人夜里不睡，好让一百头牲畜能站着睡。"},{"en":"Picture a staff laid across a lap, doubling as a seat and a counting tool.","cn":"想象一根杖横在膝上，既是坐处也是数数的工具。"},{"en":"Picture a leader who walks behind the crowd so that no one is left at the edge.","cn":"想象一位带头人走在人群后面，好让边上没人被落下。"}]},"examples":[{"en":"The herdsman could name every animal in the flock by its markings.","cn":"牧人能凭毛色花纹叫出羊群里每一只的名字。"},{"en":"Wages for a herdsman are low, but the work comes with milk and wool.","cn":"牧人的工资不高，但这活附带奶和羊毛。"},{"en":"Novels often give the herdsman a song and no other possession.","cn":"小说常给牧人一首歌，别的财产一概不给。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「herds（畜群）+ man（人）」——属于畜群的那个人 → 牧人、看管者","word":"herdsman"},"root":"古英语 heord「一群牲畜」+ 属格 -s + man「人」，字面为「畜群的人」；两部分皆属日耳曼语系，无拉丁成分。英语 herdsman。","sensesIntro":{"en":"Eight senses follow one role: a person attached to a herd. The role is then read as a hired worker, a species specialist, an owner, a pastor, a mythic figure, a guide of people and finally any keeper of a dependent group.","cn":"八个义项沿同一个角色展开：一个属于畜群的人。这个角色再依次被读作雇工、单一畜种的专人、畜主、牧养者、神话人物、人群的引导者，最后读作任何依赖群体的看管者。"},"semanticMap":{"core":{"en":"CORE IMAGE: one person awake at the edge of a sleeping flock.","cn":"核心意象：一个人醒着，守在一群睡着的牲畜旁边。"},"chain":["KEEP THE HERD","WORK FOR WAGES","SPECIALISE BY ANIMAL","OWN THE STOCK","TEND SOULS","HOLD A GROUP TOGETHER"],"branches":[{"senses":"01 · 04","en":"KEEPER AND OWNER: the same title covers the man who watches and the man whose brand the animals carry.","cn":"看管者与所有者：同一个称呼既指看羊的人，也指牲畜身上打着他烙印的人。"},{"senses":"02 · 03","en":"DIVIDED LABOUR: hired hands and single-species specialists appear once herds grow beyond one family.","cn":"分工：当畜群超过一户人家能管的规模，雇工与单一畜种的专人就出现了。"},{"senses":"05 · 06","en":"SOULS AND STORIES: the night watcher becomes a pastor in sermons and a witness in legends.","cn":"灵魂与故事：守夜人在布道里成了牧养者，在传说里成了见证者。"},{"senses":"07","en":"GUIDE OF PEOPLE: the protective gestures of herding transfer to a leader of a crowd.","cn":"人的引导者：放牧中保护性的手势转移到带领人群的人身上。"},{"senses":"08","en":"ANY DEPENDENT GROUP: keep only the role, and files or data can need a keeper too.","cn":"任何依赖群体：只保留角色，文件或数据也可以需要一个看管者。"}]},"affixes":{"intro":{"en":"Herdsman is a two-part English compound with an old genitive ending; no Latin prefix or root takes part.","cn":"herdsman 是由两部分构成的英语复合词，中间带古属格词尾，不含拉丁前缀或词根。"},"latinIntro":{"en":"This line has no Latin relative, so the Latin list is left empty; the parts are Old English and Germanic.","cn":"这一词线没有拉丁同族词，因此拉丁列表留空；各成分属古英语与日耳曼语。"},"items":[{"word":"heord","structure":"heord (Old English noun, 'group of animals')","meaning":"a herd","meaningCN":"畜群","example":"The first element names the animals.","exampleCN":"第一部分指那群牲畜。"},{"word":"hierde","structure":"hierde (Old English noun, 'herder')","meaning":"a keeper of animals","meaningCN":"牲畜看管者","example":"The older agent noun also survives inside shepherd.","exampleCN":"更古老的施事名词也残留在 shepherd 里。"},{"word":"man","structure":"man (Old English noun, 'person')","meaning":"a person","meaningCN":"人","example":"The second element names the person, not the sex.","exampleCN":"第二部分指人，而不是指性别。"},{"word":"-s-","structure":"-s (Old English genitive singular ending)","meaning":"of, belonging to","meaningCN":"……的；属于","example":"The ending makes herdsman literally 'the herd's man'.","exampleCN":"这个词尾使 herdsman 字面成为「畜群的人」。"},{"word":"herd","structure":"heord (Old English) → herd","meaning":"a group of animals; to drive them","meaningCN":"畜群；驱赶畜群","example":"The herd moved down the valley.","exampleCN":"畜群沿着山谷下行。"},{"word":"herder","structure":"herd + -er","meaning":"a keeper of animals","meaningCN":"牲畜看管者","example":"The herder carried no staff.","exampleCN":"这位牧人没有带杖。"},{"word":"-ship","structure":"-scipe (Old English abstract suffix)","meaning":"state, skill or office","meaningCN":"状态、技艺或职务","example":"Herdsman plus -ship yields herdsmanship.","exampleCN":"herdsman 加 -ship 得出 herdsmanship。"},{"word":"herdsmanship","structure":"herdsman + -ship","meaning":"the skill and duty of tending stock","meaningCN":"放牧的技艺与职责","example":"Herdsmanship was judged by the winter survival rate.","exampleCN":"放牧本领以越冬存活率来评判。"},{"word":"herdswoman","structure":"herdsman with woman for man","meaning":"a woman who tends stock","meaningCN":"女牧人","example":"The herdswoman kept the sick lambs indoors.","exampleCN":"女牧人把病羔留在室内。"}],"latinEntries":[]}},{"word":"tribe","ipa_uk":"/traɪb/","ipa_us":"/traɪb/","definition_zh":"部落；民族的支系；（非正式）一大家子；有共同趣味的小圈子","definition_en":"a group of people linked by kinship, language and territory, and by extension any close-knit circle","core_image":"一圈人围着同一堆火，火光照出同一张亲缘网，网外的人站在暗处。","scene":"清晨的河边，几十个人围着火堆坐成一圈，长者先开口，年轻人依次应答。Herders of the tribe move camp whenever the water sinks.","sceneCN":"这里 tribe 指「由血缘、语言与地域联结起来的群体」（第 1 个义项：以亲缘关系为核心的人群单位）；句意为这个部落的牧人在水位下降时就迁营。可辨识物件：火堆、围坐的人、河岸、帐篷、水罐。","pos":[{"tag":"n.","zh":"部落；支系；（非正式）家族、圈子"}],"collocations":[{"phrase":"a nomadic tribe","zh":"游牧部落"},{"phrase":"an indigenous tribe","zh":"原住民部落"},{"phrase":"the twelve tribes","zh":"（古代以色列的）十二支派"},{"phrase":"tribe and nation","zh":"部落与国家"},{"phrase":"a tribe of lawyers","zh":"律师这一圈子（戏称）"},{"phrase":"belong to a tribe","zh":"属于某个部落"}],"forms":[{"label":"单数","form":"tribe"},{"label":"复数","form":"tribes"},{"label":"形容词","form":"tribal"},{"label":"名词（部落主义）","form":"tribalism"},{"label":"副词（按部落方式）","form":"tribally"}],"derivatives":[{"word":"tribal","pos":"adj.","zh":"tribe + -al（关系形容词后缀）→ 由「部落」转为「部落的」"},{"word":"tribally","pos":"adv.","zh":"tribal + -ly（副词后缀）→ 以部落的方式，语义落在组织形态"},{"word":"tribalism","pos":"n.","zh":"tribal + -ism（体系或主张后缀）→ 由形容词转为「部落主义、宗族忠诚」"},{"word":"tribalist","pos":"n.","zh":"tribal + -ist（从事者或主张者后缀）→ 信奉本群体优先的人"},{"word":"tribelet","pos":"n.","zh":"tribe + -let（指小后缀）→ 规模很小的部落单位，语义缩小"}],"senses":[{"no":"01","title":"A group bound by kinship and place","titleCN":"以血缘、语言与地域联结的群体","definition":"a community whose members trace common descent, speak one language and hold one stretch of country","definitionCN":"成员共有祖先、使用同一种语言、占有同一片土地的共同体","example":"Herders of the tribe move camp whenever the water sinks.","exampleCN":"这个部落的牧人在水位下降时就迁营。","why":"the Roman tribus named a division of the people, and the English word kept that sense of a bounded slice of a larger population.","whyCN":"罗马的 tribus 指人民中的一个分支，英语继承了这个「较大人群中的一块」的意思。"},{"no":"02","title":"A label for pre-state societies","titleCN":"人类学中以前国家社会为对象的泛称","definition":"a general term used by researchers for societies organized by kinship rather than by a state, now often treated with caution","definitionCN":"研究者用来指按亲缘而非国家组织的社会，如今常被谨慎使用","example":"The textbook warns that tribe is a loose label, not a legal category.","exampleCN":"教科书提醒说，tribe 是宽松的标签，不是法律类别。","why":"nineteenth-century writers needed one word for peoples without states, so they widened the older word far beyond its Roman meaning.","whyCN":"19 世纪的作者需要用一个词概括没有国家的人群，于是把旧词的含义远远扩展到罗马义之外。"},{"no":"03","title":"A branch of a whole people","titleCN":"一个民族的支系","definition":"one of the named divisions of a people, as in the twelve tribes of Israel","definitionCN":"一个民族中被命名的分支之一，如以色列十二支派","example":"Each tribe supplied one gate of the city in the old account.","exampleCN":"在旧记载中，每个支派负责城门中的一座。","why":"the biblical use fixed the word as a division within one people, which is the closest English sense to Latin tribus.","whyCN":"《圣经》用法把这个词固定为同一民族内部的分支，这是英语中最接近拉丁 tribus 的义项。"},{"no":"04","title":"A large family, informally","titleCN":"非正式用法：一大家子","definition":"a person's extended family or a crowd of relatives, said with a smile rather than as a technical term","definitionCN":"一个人的大家族或一群亲戚，带玩笑口吻，而非术语","example":"Half the tribe turned up for the wedding.","exampleCN":"一大家子有一半人出现在婚礼上。","why":"if a tribe is a kinship group, any big family can be called one in jest.","whyCN":"既然部落就是亲缘群体，任何大家庭都可以被戏称为一个部落。"},{"no":"05","title":"A circle with shared taste","titleCN":"趣味相同的小圈子","definition":"a close group of people who share an interest, style or occupation and keep outsiders at a distance","definitionCN":"兴趣、风格或职业相同、并对外人保持距离的紧密群体","example":"The tribe of coffee obsessives knows every roaster in the city.","exampleCN":"咖啡痴迷者的圈子认识城里每一家烘焙商。","why":"the kinship image survives in the group's loyalty and its clear edge, even when no ancestor is shared.","whyCN":"即使没有共同祖先，群体内部的忠诚与清晰的边界仍保留了亲缘意象。"},{"no":"06","title":"A bloc inside a larger body","titleCN":"更大组织内部的派系","definition":"a faction within a party or institution that acts for its own members before the whole","definitionCN":"政党或机构内部、先顾自己成员再顾整体的派系","example":"The party split into three tribes before the vote.","exampleCN":"投票前，这个党分裂成了三派。","why":"a tribe's loyalty to its own people is exactly what a faction shows, so the word moves easily into politics.","whyCN":"部落对自家人优先的忠诚，正是派系所表现出的东西，因此这个词很容易进入政治语境。"},{"no":"07","title":"An administrative unit","titleCN":"殖民与行政语境中的管理单位","definition":"a unit used by officials to count, tax or govern a population, often drawn with little regard for real ties","definitionCN":"官员用来统计、征税或治理人群的单位，划分时常不顾真实关系","example":"The old register lists the village as one tribe of four hundred souls.","exampleCN":"旧登记册把这个村子列为一个四百人的部落单位。","why":"governments needed countable units, and they borrowed the word for a people and turned it into a box on a form.","whyCN":"政府需要可计数的单位，于是借来指人群的词，把它变成表格上的一格。"},{"no":"08","title":"Any group one is born into","titleCN":"抽象义：任何与生俱来的归属群体","definition":"any group whose membership comes by birth and which expects loyalty before choice","definitionCN":"成员身份由出生决定、并要求忠诚先于选择的任何群体","example":"For him the firm was a tribe, entered at birth and never left.","exampleCN":"对他来说，那家公司就是一个部落，生来就在其中，从未离开。","why":"the abstract sense keeps the structure of birth plus loyalty and drops the land and the ancestors.","whyCN":"抽象义保留了「出生加忠诚」的结构，丢掉了土地与祖先。"}],"etymology":{"intro":{"en":"Tribe comes from Latin tribus, the name of a division of the Roman people, through Old French tribu. The origin of tribus itself is uncertain.","cn":"tribe 经古法语 tribu 来自拉丁 tribus，后者是罗马人民中一个分支的名称。tribus 本身的来源不确定。"},"items":[{"era":"LATIN TRIBUS","en":"Tribus named one of the divisions into which Roman citizens were enrolled. Its own origin is uncertain: a link with tri- 'three' and a link with tribuere 'to allot' are both offered as hypotheses, and neither is established.","cn":"tribus 指罗马公民被编入的各个分支之一。它自身的来源不确定：与 tri-「三」的联系、与 tribuere「分配」的联系都只是假说，两者均未得到证实。"},{"era":"ROMAN VOTING","en":"In the Republic the tribus were voting divisions, not ethnic groups, so the Latin word already meant an administrative slice of a people.","cn":"在共和国时期，tribus 是投票分区，而非族群，因此这个拉丁词本义就是人民中的一个行政切片。"},{"era":"OLD FRENCH TRIBU","en":"Old French tribu brought the word into English in the fourteenth century, first in biblical passages about the twelve tribes.","cn":"古法语 tribu 在 14 世纪把该词带入英语，最初见于关于十二支派的圣经段落。"},{"era":"COLONIAL WIDENING","en":"From the eighteenth century travellers applied the word to peoples across Asia, Africa and the Americas, often with little knowledge of their institutions.","cn":"从 18 世纪起，旅行者把这个词用于亚洲、非洲与美洲各地的族群，往往对其制度所知甚少。"},{"era":"MODERN CAUTION","en":"Twentieth-century anthropology treated tribe as a loose category and often replaced it with more precise terms such as band or lineage.","cn":"20 世纪的人类学把 tribe 视为宽松类别，常用 band（小游群）或 lineage（世系群）等更精确的词替代。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (origin and first date): the derivation of tribus is unsettled, and the earliest English citation is only approximately dated.","cn":"来源不确定（词源与首见年代）：tribus 的派生关系无定论，最早的英语书证只有约数。"}]},"similar":{"note":{"en":"Group one holds words that resemble tribe in sound or derivation but differ in meaning; group two holds terms for human groups that differ in scale and in how membership is defined.","cn":"第一组是读音或词源上与 tribe 相近、但意义不同的词；第二组是人群单位，差别在规模与成员资格的界定方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tribal","ipa":"/ˈtraɪbl/","tag":"adjective","definition":"The adjective describing anything of a tribe; it cannot stand for the group itself.","definitionCN":"描述与部落有关之事的形容词，不能代替群体本身。"},{"word":"tribalism","ipa":"/ˈtraɪbəlɪzəm/","tag":"loyalty, not group","definition":"Loyalty to one's own group above the wider society; it names an attitude or system, not a people.","definitionCN":"对本群体优先于大社会的忠诚；它指态度或制度，而非一个族群。"},{"word":"tribute","ipa":"/ˈtrɪbjuːt/","tag":"different derivation","definition":"From Latin tributum, from tribuere 'to allot, pay'; whether tribus itself comes from tribuere is disputed, so the two words are not simply one root.","definitionCN":"来自拉丁 tributum，出自动词 tribuere「分配、支付」；tribus 是否也出自 tribuere 尚有争议，因此两者并非简单的同一词根。"},{"word":"tribune","ipa":"/ˈtrɪbjuːn/","tag":"Roman office","definition":"From tribunus, an officer tied to the tribus; in English it means a Roman magistrate or a raised platform, not a people.","definitionCN":"来自 tribunus，是与 tribus 相关的官员；英语中指罗马长官或讲台，不指族群。"}]},{"heading":"NEAR MEANING","entries":[{"word":"clan","ipa":"/klæn/","tag":"descent group","definition":"A group of families claiming one ancestor; a tribe may contain several clans, so clan is the smaller unit.","definitionCN":"自称出自同一祖先的若干家庭；一个部落可含数个氏族，因此氏族是更小的单位。"},{"word":"ethnic group","ipa":"/ˈeθnɪk ɡruːp/","tag":"shared culture","definition":"A group defined by shared culture, language or descent; it is the neutral term preferred in modern writing.","definitionCN":"以共同文化、语言或血统界定的群体，是现代写作偏好的中性说法。"},{"word":"nation","ipa":"/ˈneɪʃn/","tag":"political scale","definition":"A people organized as a state or claiming one; it is larger and more political than a tribe.","definitionCN":"组织为国家或主张建国的民族，比部落更大、更具政治性。"},{"word":"band","ipa":"/bænd/","tag":"smallest unit","definition":"A small group of a few families who move and hunt together; anthropologists treat it as smaller than a tribe.","definitionCN":"由几户人家组成、共同迁移与狩猎的小群体；人类学视其为比部落更小的单位。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin division, real relatives and real fixed phrases.","cn":"正常联想：真实的拉丁分区、真实同族词与真实固定搭配。"},"normal":[{"en":"Latin tribus was a division of the Roman people, so tribe began as a slice of a larger whole.","cn":"拉丁 tribus 是罗马人民的一个分区，因此 tribe 最初指较大整体中的一块。"},{"en":"The family runs tribe, tribal, tribally, tribalism, tribalist and tribelet.","cn":"同族词包括 tribe、tribal、tribally、tribalism、tribalist、tribelet。"},{"en":"Fixed phrases mark the scale: a nomadic tribe, an indigenous tribe, tribe and nation.","cn":"固定搭配标出规模：游牧部落、原住民部落、部落与国家。"},{"en":"The biblical twelve tribes fixed the sense of a branch within one people.","cn":"圣经中的十二支派固定了「同一民族内分支」这一义项。"},{"en":"Anthropology now prefers band, lineage or ethnic group for precise work.","cn":"人类学如今在精确研究中更偏好 band、lineage 或 ethnic group。"}],"abstract":[{"en":"Picture one fire with a fixed ring of faces around it and a dark ring of backs beyond.","cn":"想象一堆火，前面是一圈固定的面孔，后面是一圈背对火光的黑影。"},{"en":"Picture a family reunion where the seating chart is the family tree.","cn":"想象一次家庭聚会，座位表就是那棵家谱树。"},{"en":"Picture a club with no membership card, only a shared accent.","cn":"想象一个没有会员卡的俱乐部，凭的只是同一种口音。"}]},"examples":[{"en":"The tribe's grazing rights were written down only in the elders' memory.","cn":"这个部落的放牧权只记在长者们的记忆里。"},{"en":"Officials counted the tribe as one unit and ignored its internal divisions.","cn":"官员把这个部落当作一个单位来统计，忽略了它内部的分支。"},{"en":"At the conference the two tribes of researchers sat at opposite tables.","cn":"会上，两个研究圈子坐在相对的桌旁。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「try（试着）+ be（成为）」——试着成为同一群人 → 部落、支系","word":"tribe"},"root":"拉丁 tribus「罗马人民的一个分区」，经古法语 tribu 入英语；tribus 自身来源不确定，与 tri-「三」及 tribuere「分配」的联系均为假说。英语 tribe。","sensesIntro":{"en":"Eight senses follow one shape: a bounded slice of a people. The slice is read as a kinship community, a research label, a biblical branch, a family, a taste circle, a political bloc, an office unit and finally any group entered by birth.","cn":"八个义项沿同一个形状展开：人群中被划出的一块。这块再依次被读作亲缘共同体、研究标签、圣经支派、大家庭、趣味圈子、政治派系、行政单位，最后读作任何凭出生进入的群体。"},"semanticMap":{"core":{"en":"CORE IMAGE: one fire with a fixed ring of faces and a dark ring beyond it.","cn":"核心意象：一堆火，一圈固定面孔，圈外是一片暗影。"},"chain":["A DIVISION OF A PEOPLE","KIN AND LAND","A RESEARCH LABEL","A FAMILY CIRCLE","A FACTION","BIRTH-GROUP"],"branches":[{"senses":"01 · 04","en":"KIN AND FAMILY: from a people's division down to one's relatives, the bond is always descent.","cn":"亲缘与家庭：从民族的分支到自己的亲戚，纽带始终是血统。"},{"senses":"02 · 03","en":"LABEL AND SCRIPTURE: the same word serves a researcher's category and a sacred list of branches.","cn":"标签与经文：同一个词既作研究类别，也作神圣的支派清单。"},{"senses":"05","en":"TASTE CIRCLE: shared style does the work of shared ancestry.","cn":"趣味圈子：共同风格替代了共同祖先的作用。"},{"senses":"06 · 07","en":"BLOC AND BOX: inside a party it is a faction; on a form it is a countable unit.","cn":"派系与表格：在政党内部它是派系，在表格上是可计数的单位。"},{"senses":"08","en":"BIRTH-GROUP: keep only birth and loyalty, and any institution can become a tribe.","cn":"出生群体：只留出生与忠诚，任何机构都能变成一个部落。"}]},"affixes":{"intro":{"en":"Tribe is a Latin noun with no prefix; English adds -al, -ism and -let to build the family.","cn":"tribe 是一个不含前缀的拉丁名词；英语加 -al、-ism 与 -let 构成词族。"},"latinIntro":{"en":"Latin tribus gives the noun; the related verb tribuere 'to allot' stands behind tribute and tribune, but the exact link to tribus is disputed.","cn":"拉丁 tribus 给出名词；相关动词 tribuere「分配」是 tribute 与 tribune 的来源，但它与 tribus 的确切联系有争议。"},"items":[{"word":"tribus","structure":"tribus, tribus (Latin noun, fourth declension)","meaning":"a division of the Roman people","meaningCN":"罗马人民的一个分区","example":"The noun already meant an administrative slice.","exampleCN":"这个名词本义就是行政上的一块。"},{"word":"tribuere","structure":"tribuere, tribui, tributum (Latin verb, third conjugation)","meaning":"to allot, assign, pay","meaningCN":"分配；分给；支付","example":"The verb stands behind tribute, not directly behind tribe.","exampleCN":"这个动词是 tribute 的来源，而不是 tribe 的直接来源。"},{"word":"-al","structure":"-alis (Latin adjective suffix, through French -al)","meaning":"relating to","meaningCN":"与……有关的","example":"Tribe plus -al yields tribal.","exampleCN":"tribe 加 -al 得出 tribal。"},{"word":"-ly","structure":"-lice (Old English adverb suffix)","meaning":"in the manner of","meaningCN":"以……方式","example":"Tribal plus -ly yields tribally.","exampleCN":"tribal 加 -ly 得出 tribally。"},{"word":"-ism","structure":"-ismus (system or doctrine suffix, from Greek)","meaning":"a system, practice or doctrine","meaningCN":"体系、实践或主张","example":"Tribal plus -ism yields tribalism.","exampleCN":"tribal 加 -ism 得出 tribalism。"},{"word":"-ist","structure":"-ista (agent or adherent suffix)","meaning":"one who practices or supports","meaningCN":"从事者或支持者","example":"Tribal plus -ist yields tribalist.","exampleCN":"tribal 加 -ist 得出 tribalist。"},{"word":"-let","structure":"-let (diminutive suffix, from French)","meaning":"small","meaningCN":"小的","example":"Tribe plus -let yields tribelet, a small tribal unit.","exampleCN":"tribe 加 -let 得出 tribelet，即小型部落单位。"},{"word":"tribal","structure":"tribe + -al","meaning":"of a tribe","meaningCN":"部落的","example":"Tribal land is held by the group, not the individual.","exampleCN":"部落土地由群体而非个人持有。"},{"word":"tribalism","structure":"tribal + -ism","meaning":"loyalty to one's own group","meaningCN":"对本群体的忠诚","example":"Tribalism can outlast the tribe itself.","exampleCN":"宗族忠诚可以比部落本身活得更久。"}],"latinEntries":[{"word":"tribus","structure":"tribus, tribus (f., fourth declension)","meaning":"a division of the Roman people","meaningCN":"罗马人民的一个分区"},{"word":"tribuere","structure":"tribuere, tribui, tributum (verb, third conjugation)","meaning":"to allot, assign","meaningCN":"分配；分给"},{"word":"tribunus","structure":"tribunus, tribuni (m., second declension)","meaning":"an officer of a tribus","meaningCN":"与分区相关的长官"},{"word":"tributum","structure":"tributum, tributi (n., second declension)","meaning":"a payment, tribute","meaningCN":"缴纳之物；贡赋"}]}},{"word":"tribal","ipa_uk":"/ˈtraɪbl/","ipa_us":"/ˈtraɪbl/","definition_zh":"部落的；按部落组织的；部落社会特有的；（贬义）只认自己群体的","definition_en":"relating to a tribe, or organized around tribes rather than around a state","core_image":"同一条纹披肩从左肩绕到右肩，条纹的数目就是辈分的记号，一眼能看出谁该先说话。","scene":"广场上，人们披着相同的条纹披肩，鼓声一响便按辈分站成两排。The dancers wore tribal patterns that showed which family they came from.","sceneCN":"这里 tribal 指「与部落相关的、属于部落的」（第 1 个义项：描述事物归属某一部落）；句意为舞者身上的部落花纹表明他们出自哪个家族。可辨识物件：条纹披肩、鼓、两排舞者、广场、花纹带。","pos":[{"tag":"adj.","zh":"部落的；部落制的；只认自己群体的"}],"collocations":[{"phrase":"tribal elders","zh":"部落长者"},{"phrase":"tribal land","zh":"部落土地"},{"phrase":"tribal identity","zh":"部落认同"},{"phrase":"tribal loyalty","zh":"宗族式的忠诚"},{"phrase":"tribal customs","zh":"部落习俗"},{"phrase":"tribal warfare","zh":"部落间的争斗"}],"forms":[{"label":"原级","form":"tribal"},{"label":"比较级","form":"more tribal"},{"label":"最高级","form":"most tribal"},{"label":"副词","form":"tribally"},{"label":"名词（部落）","form":"tribe"},{"label":"名词（部落主义）","form":"tribalism"}],"derivatives":[{"word":"tribe","pos":"n.","zh":"拉丁 tribus「分区」经古法语 tribu → 部落，语义由行政分区扩为亲缘群体"},{"word":"tribally","pos":"adv.","zh":"tribal + -ly（副词后缀）→ 以部落方式，语义落在组织形态"},{"word":"tribalism","pos":"n.","zh":"tribal + -ism（体系或主张后缀）→ 由形容词转为「宗族忠诚、部落主义」"},{"word":"tribalist","pos":"n./adj.","zh":"tribal + -ist（主张者后缀）→ 主张本群体优先的人；带此色彩的"},{"word":"tribalistic","pos":"adj.","zh":"tribalist + -ic（形容词后缀）→ 带有宗派忠诚色彩的"},{"word":"detribalize","pos":"v.","zh":"de-（去除）+ tribal + -ize（动词后缀）→ 使脱离部落组织，语义指向制度变迁"}],"senses":[{"no":"01","title":"Belonging to a tribe","titleCN":"属于某个部落的","definition":"of or belonging to a tribe, its members or its territory","definitionCN":"属于某个部落、其成员或其土地的","example":"The dancers wore tribal patterns that showed which family they came from.","exampleCN":"舞者身上的部落花纹表明他们出自哪个家族。","why":"tribe plus the relational suffix -al produces the plain adjective of belonging.","whyCN":"tribe 加关系形容词后缀 -al，就得出表示归属的普通形容词。"},{"no":"02","title":"Organized by tribes, not by a state","titleCN":"按部落而非国家组织的","definition":"describing a political order in which authority rests with tribal groups rather than with central institutions","definitionCN":"描述权威属于各部落群体、而非中央机构的政治秩序","example":"The region has a tribal order that no capital has ever fully replaced.","exampleCN":"这个地区有一套部落秩序，任何首都都未能完全取代。","why":"if the basic unit of society is the tribe, then the whole order can be called tribal.","whyCN":"如果社会的基本单位是部落，整个秩序就可以被称为部落制的。"},{"no":"03","title":"Characteristic of tribal society","titleCN":"部落社会特有的","definition":"typical of life in a kinship-based society, such as shared land, elders' councils and inherited roles","definitionCN":"亲缘社会生活的典型特征，如共有土地、长者议事与世袭角色","example":"Tribal customs settled the dispute before any court existed.","exampleCN":"在法院出现之前，部落习俗就已经解决了争端。","why":"customs that grow from kinship organization are naturally labelled with the adjective of that organization.","whyCN":"从亲缘组织中生长出来的习俗，自然用这种组织的形容词来标记。"},{"no":"04","title":"Fiercely loyal to one's own group","titleCN":"对本群体极为忠诚的","definition":"showing strong preference for one's own group and its members over outsiders","definitionCN":"对自群体及其成员表现出强于对外人的偏护","example":"Tribal loyalty decided the election long before the speeches began.","exampleCN":"早在演讲开始之前，宗族式的忠诚就已经决定了选举。","why":"the loyalty a tribe demands became the defining colour of the adjective, even outside real tribes.","whyCN":"部落所要求的忠诚成了这个形容词的鲜明色彩，即使在真实部落之外也如此。"},{"no":"05","title":"Of traditional patterned design","titleCN":"传统图案风格的","definition":"describing art, cloth or ornament whose patterns come from a particular people's tradition","definitionCN":"描述图案来自某一民族传统的艺术、织物或饰物","example":"The museum labels the rugs as tribal work, not factory work.","exampleCN":"博物馆把这些地毯标为部落手工，而非工厂制品。","why":"makers' group identity is written into the pattern, so the adjective moves from people to product.","whyCN":"制作者的群体身份被写进图案，因此这个形容词从人转到了物。"},{"no":"06","title":"Bloc-minded in politics","titleCN":"政治上只认自己一派的（贬义）","definition":"acting in narrow factional interest, as if a party were a tribe","definitionCN":"以狭窄派系利益行事，仿佛政党就是部落","example":"Commentators called the budget debate tribal rather than ideological.","exampleCN":"评论员说这场预算辩论是宗派之争，而非意识形态之争。","why":"when loyalty to a subgroup outranks the common institution, observers reach for the tribal label.","whyCN":"当对小团体的忠诚压过共同制度时，观察者就会取用 tribal 这个标签。"},{"no":"07","title":"Divided into tribes administratively","titleCN":"行政上划分为部落的","definition":"describing a system that treats the population as a set of tribes for counting or governing","definitionCN":"把人口当作一组部落来统计或治理的制度","example":"The tribal districts were drawn to match the old grazing boundaries.","exampleCN":"部落选区是按旧的放牧边界划定的。","why":"once officials adopt the tribe as their unit, the resulting map and system are called tribal.","whyCN":"一旦官员采用部落作为单位，由此产生的地图与制度就被称为部落制的。"},{"no":"08","title":"Marked by in-group boundaries","titleCN":"抽象义：以群体归属划界的","definition":"any arrangement in which belonging to one group decides trust, access and obligation","definitionCN":"任何由群体归属决定信任、机会与义务的安排","example":"The office had a tribal feel: outsiders learned nothing until they married in.","exampleCN":"那间办公室有种部落气息：外人除非娶进去，否则什么也学不到。","why":"strip away the ancestors and what remains is the boundary itself, which is the abstract sense.","whyCN":"抽掉祖先，剩下的就是那条边界本身，这就是抽象义。"}],"etymology":{"intro":{"en":"Tribal is tribe plus the Latin-derived suffix -al. The noun came from Latin tribus through Old French; the adjective is an English formation.","cn":"tribal 由 tribe 加源自拉丁的后缀 -al 构成。名词经古法语来自拉丁 tribus，形容词则是英语自身的构造。"},"items":[{"era":"LATIN TRIBUS","en":"Tribus was a division of the Roman people, and its own derivation is uncertain; the hypotheses linking it to tri- 'three' or to tribuere 'to allot' are not established.","cn":"tribus 是罗马人民的一个分区，其自身来源不确定；把它与 tri-「三」或 tribuere「分配」相联的假说均未证实。"},{"era":"OLD FRENCH TRIBU","en":"The noun reached English in the fourteenth century as tribu, first in biblical lists of the twelve tribes.","cn":"名词在 14 世纪以 tribu 形式进入英语，最初见于十二支派的圣经清单。"},{"era":"SUFFIX -AL","en":"The suffix -alis had long supplied English adjectives of relation, so tribe plus -al needed no Latin model.","cn":"后缀 -alis 早已为英语提供关系形容词，因此 tribe 加 -al 无须拉丁范本。"},{"era":"SEVENTEENTH CENTURY","en":"Tribal appears in English writing of the seventeenth century, first describing peoples and their customs.","cn":"tribal 见于 17 世纪的英语写作，最初描述各个民族及其习俗。"},{"era":"MODERN WIDENING","en":"In the twentieth century the adjective extended to design, politics and institutional loyalty, where no actual tribe exists.","cn":"到 20 世纪，这个形容词扩展到设计、政治与机构忠诚，那里并没有真实的部落。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest use of tribal is only approximately dated, and the origin of tribus remains unsettled.","cn":"来源不确定（首见年代）：tribal 的最早用法只有约数，tribus 的来源仍无定论。"}]},"similar":{"note":{"en":"Group one holds forms of the same word family that are often swapped by mistake; group two holds adjectives for social orders that are not tribal.","cn":"第一组是同一词族中常被误换的形式；第二组是描述非部落社会秩序的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tribe","ipa":"/traɪb/","tag":"noun","definition":"The group itself; tribal is only its adjective and cannot replace it in a sentence like 'the tribe met'.","definitionCN":"群体本身；tribal 只是它的形容词，不能代替「部落开会」这类句子里的名词。"},{"word":"tribalism","ipa":"/ˈtraɪbəlɪzəm/","tag":"attitude or system","definition":"Loyalty to one's group; it is a noun of attitude, while tribal describes what has that attitude or structure.","definitionCN":"对本群体的忠诚；它是态度名词，而 tribal 描述带有这种态度或结构的事物。"},{"word":"tribally","ipa":"/ˈtraɪbəli/","tag":"adverb","definition":"In a tribal manner; it modifies verbs, as in land held tribally.","definitionCN":"以部落方式；修饰动词，如土地由部落共有。"},{"word":"tribune","ipa":"/ˈtrɪbjuːn/","tag":"different word","definition":"A Roman office or a raised platform; it shares letters with tribe but names no people.","definitionCN":"罗马官职或讲台；与 tribe 共享字母，却不指任何族群。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ethnic","ipa":"/ˈeθnɪk/","tag":"culture, not polity","definition":"Relating to a people's culture or descent; it is the neutral choice where tribal would sound loaded.","definitionCN":"关于一个民族的文化或血统；在 tribal 显得带偏见处，它是中性选择。"},{"word":"clannish","ipa":"/ˈklænɪʃ/","tag":"closed circle","definition":"Keeping tightly to one's family or circle and cold to outsiders; it stresses exclusion rather than organization.","definitionCN":"紧抱自家或自己圈子、对外人冷淡；强调排外而非组织形态。"},{"word":"local","ipa":"/ˈləʊkl/","tag":"place, not descent","definition":"Tied to a place; a tribal order is tied to descent, which local does not say.","definitionCN":"与地点相连；部落秩序与血统相连，而 local 不含此意。"},{"word":"communal","ipa":"/kəˈmjuːnl/","tag":"shared property","definition":"Held or done in common; it describes ownership, while tribal describes the social unit that owns.","definitionCN":"共同持有或共同进行；它描述所有权，tribal 描述持有的社会单位。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real noun-plus-suffix build, real relatives and real fixed phrases.","cn":"正常联想：真实的名词加后缀构造、真实同族词与真实搭配。"},"normal":[{"en":"tribe + -al: the adjective of belonging, nothing more elaborate.","cn":"tribe + -al：表示归属的形容词，没有更复杂的构造。"},{"en":"The family runs tribe, tribal, tribally, tribalism, tribalist, tribalistic.","cn":"同族词包括 tribe、tribal、tribally、tribalism、tribalist、tribalistic。"},{"en":"Fixed phrases mark the uses: tribal elders, tribal land, tribal loyalty.","cn":"固定搭配标出用法：部落长者、部落土地、宗族式忠诚。"},{"en":"The stress stays on the first syllable: TRIB-al, like TRIBE.","cn":"重音留在第一音节：TRIB-al，与 TRIBE 一致。"},{"en":"Detribalize reverses the adjective with de- and -ize.","cn":"detribalize 用 de- 与 -ize 把这一形容词反向动词化。"}],"abstract":[{"en":"Picture a striped shawl that tells every stranger your rank before you speak.","cn":"想象一条条纹披肩，在你开口之前就向每个陌生人说明了你的辈分。"},{"en":"Picture a map coloured by group rather than by river.","cn":"想象一张按群体、而不是按河流上色的地图。"},{"en":"Picture an office where the org chart is drawn like a family tree.","cn":"想象一间办公室，组织图被画成了家谱。"}]},"examples":[{"en":"Tribal elders still settle most boundary quarrels without a lawyer.","cn":"部落长者仍然不用律师就解决大多数边界纠纷。"},{"en":"The label tribal is now avoided where ethnic group would be clearer.","cn":"在 ethnic group 更清楚的地方，如今避免使用 tribal 这个标签。"},{"en":"The debate turned tribal once each side began defending its own members only.","cn":"一旦双方都只护自己人，辩论就变成了宗派之争。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「tribe（部落）+ al（的）」——属于部落的 → 部落的、只认自己人的","word":"tribal"},"root":"英语 tribe（拉丁 tribus「分区」经古法语 tribu）+ 拉丁系形容词后缀 -al；tribus 自身来源不确定，相关假说均未证实。英语 tribal。","sensesIntro":{"en":"Eight senses follow one relation: belonging to a tribe. The relation is then read as a political order, a set of customs, a loyalty, a design style, a factional habit, an administrative map and finally any boundary of belonging.","cn":"八个义项沿同一种关系展开：归属于某个部落。这种关系再依次被读作政治秩序、习俗体系、忠诚、图案风格、派系习气、行政划分，最后读作任何归属边界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a striped shawl that announces rank and family before a word is spoken.","cn":"核心意象：一条条纹披肩，在人开口之前就说明辈分与家族。"},"chain":["OF A TRIBE","TRIBE-RUN ORDER","INHERITED CUSTOM","GROUP LOYALTY","PATTERN STYLE","DRAWN BOUNDARY"],"branches":[{"senses":"01 · 07","en":"BELONG AND ADMINISTER: the same adjective marks a people's own things and the map an office draws of them.","cn":"归属与行政：同一个形容词既标记一个民族自己的东西，也标记机关画出的地图。"},{"senses":"02 · 03","en":"ORDER AND CUSTOM: rule by tribes and the habits that grow under it are two sides of one arrangement.","cn":"秩序与习俗：部落掌权与在其下生长的习惯，是同一安排的两面。"},{"senses":"04 · 06","en":"LOYALTY AND FACTION: warm loyalty inside becomes cold factionalism outside.","cn":"忠诚与派系：对内的热忠诚，对外就成了冷派系。"},{"senses":"05","en":"PATTERN STYLE: the group's identity passes into cloth and ornament.","cn":"图案风格：群体身份进入织物与饰物。"},{"senses":"08","en":"BOUNDARY: remove the tribe and only the line between insiders and outsiders remains.","cn":"边界：去掉部落，只剩圈内人与圈外人之间那条线。"}]},"affixes":{"intro":{"en":"Tribal is a noun with one relational suffix; the wider family adds -ism, -ist and the reversive de-.","cn":"tribal 是一个名词加一个关系后缀；更大的词族再加 -ism、-ist 与反向前缀 de-。"},"latinIntro":{"en":"Latin tribus supplies the noun and -alis the suffix pattern; tribuere stands behind tribute but not certainly behind tribus.","cn":"拉丁 tribus 提供名词，-alis 提供后缀模式；tribuere 是 tribute 的来源，但不一定是 tribus 的来源。"},"items":[{"word":"tribus","structure":"tribus, tribus (Latin noun, fourth declension)","meaning":"a division of the Roman people","meaningCN":"罗马人民的一个分区","example":"The Latin noun already named a slice of a people.","exampleCN":"这个拉丁名词本义就指人群中的一块。"},{"word":"-alis","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix passed into English as -al.","exampleCN":"这个后缀以 -al 形式进入英语。"},{"word":"tribe","structure":"tribus (Latin) → Old French tribu → English tribe","meaning":"a kinship community","meaningCN":"亲缘共同体","example":"The noun is the base of the adjective.","exampleCN":"这个名词是形容词的基础。"},{"word":"-al","structure":"-al (English relational suffix)","meaning":"of or relating to","meaningCN":"……的；与……有关的","example":"Tribe plus -al yields tribal.","exampleCN":"tribe 加 -al 得出 tribal。"},{"word":"-ly","structure":"-ly (English adverb suffix)","meaning":"in the manner of","meaningCN":"以……方式","example":"Tribal plus -ly yields tribally.","exampleCN":"tribal 加 -ly 得出 tribally。"},{"word":"-ism","structure":"-ism (system or doctrine suffix)","meaning":"a system or attitude","meaningCN":"体系或态度","example":"Tribal plus -ism yields tribalism.","exampleCN":"tribal 加 -ism 得出 tribalism。"},{"word":"-ist","structure":"-ist (adherent suffix)","meaning":"one who supports or practices","meaningCN":"支持者或从事者","example":"Tribal plus -ist yields tribalist.","exampleCN":"tribal 加 -ist 得出 tribalist。"},{"word":"-ic","structure":"-ic (adjective suffix, from Latin -icus)","meaning":"having the character of","meaningCN":"具有……性质","example":"Tribalist plus -ic yields tribalistic.","exampleCN":"tribalist 加 -ic 得出 tribalistic。"},{"word":"de-","structure":"de- (Latin prefix, 'away, remove')","meaning":"removal, reversal","meaningCN":"去除；反转","example":"De- plus tribal plus -ize yields detribalize.","exampleCN":"de- 加 tribal 再加 -ize 得出 detribalize。"},{"word":"tribalism","structure":"tribal + -ism","meaning":"loyalty to one's own group","meaningCN":"对本群体的忠诚","example":"Tribalism hardened the boundary the adjective describes.","exampleCN":"宗族忠诚使这个形容词所描述的边界更加坚硬。"}],"latinEntries":[{"word":"tribus","structure":"tribus, tribus (f., fourth declension)","meaning":"a division of the Roman people","meaningCN":"罗马人民的一个分区"},{"word":"tribuere","structure":"tribuere, tribui, tributum (verb, third conjugation)","meaning":"to allot, assign","meaningCN":"分配；分给"},{"word":"tributarius","structure":"tributarius, tributaria, tributarium (adjective)","meaning":"subject to tribute","meaningCN":"需缴纳贡赋的"}]}},{"word":"tribalism","ipa_uk":"/ˈtraɪbəlɪzəm/","ipa_us":"/ˈtraɪbəlɪzəm/","definition_zh":"部落主义；宗族忠诚；以部落为基础的社会制度；排外的小团体意识","definition_en":"strong loyalty to one's own tribe or group over the wider society, and social organization built on tribes","core_image":"两条村路并排通向同一座桥，上桥后各自只走一边，谁也不肯让谁先过。","scene":"两条村路并排通向同一座桥，上桥后各自靠一边走，谁也不肯让谁先过。Tribalism kept the two valleys apart long after the road joined them.","sceneCN":"这里 tribalism 指「对本部落或本群体的忠诚高于对更大社会的忠诚」（第 1 个义项：以本群体为先的忠诚与做法）；句意为道路把两处山谷连起来很久之后，宗族式的忠诚仍让它们彼此分隔。可辨识物件：两条村路、石桥、两侧行人、界石、山谷。","pos":[{"tag":"n.","zh":"部落主义；宗族忠诚；部落制度"}],"collocations":[{"phrase":"ethnic tribalism","zh":"族群宗派主义"},{"phrase":"political tribalism","zh":"政治上的派系主义"},{"phrase":"the rise of tribalism","zh":"宗派主义的抬头"},{"phrase":"tribalism and nationalism","zh":"宗族主义与民族主义"},{"phrase":"overcome tribalism","zh":"克服宗派观念"},{"phrase":"tribalism in the workplace","zh":"职场中的小团体主义"}],"forms":[{"label":"不可数名词","form":"tribalism"},{"label":"形容词","form":"tribal"},{"label":"名词（信奉者）","form":"tribalist"},{"label":"名词（信奉者，复数）","form":"tribalists"},{"label":"形容词（宗派色彩的）","form":"tribalistic"},{"label":"动词（去除部落组织）","form":"detribalize"}],"derivatives":[{"word":"tribal","pos":"adj.","zh":"tribe + -al（关系形容词后缀）→ 由「部落」转为「部落的」"},{"word":"tribalist","pos":"n.","zh":"tribal + -ist（主张者后缀）→ 以本群体为先的人，语义由性质转为人"},{"word":"tribalistic","pos":"adj.","zh":"tribalist + -ic（形容词后缀）→ 带有宗派忠诚色彩的"},{"word":"detribalize","pos":"v.","zh":"de-（去除）+ tribal + -ize（动词后缀）→ 使脱离部落组织，语义指向制度变迁"},{"word":"detribalization","pos":"n.","zh":"detribalize + -ation（过程名词后缀）→ 脱离部落组织的过程"}],"senses":[{"no":"01","title":"Loyalty to one's group before society","titleCN":"对本群体的忠诚高于更大社会","definition":"the habit of putting one's own tribe or group first, even when the wider society suffers","definitionCN":"把本部落或本群体放在首位、即使更大社会受损也如此的习惯","example":"Tribalism kept the two valleys apart long after the road joined them.","exampleCN":"道路把两处山谷连起来很久之后，宗族式的忠诚仍让它们彼此分隔。","why":"the suffix -ism turns tribal into the name of an attitude, and that attitude is loyalty to the tribe.","whyCN":"后缀 -ism 把 tribal 变成一种态度的名称，而这种态度就是对本部落的忠诚。"},{"no":"02","title":"Organization of the state by tribes","titleCN":"以部落为基础的国家组织方式","definition":"a political system in which tribal units, not central offices, hold the real power","definitionCN":"由部落单位而非中央机关掌握实权的政治制度","example":"Tribalism in the province meant every ministry job belonged to a valley.","exampleCN":"在这个省，部落主义意味着每个部门的职位都归某条山谷。","why":"if the tribe is the unit that governs, the system itself takes the name of that unit.","whyCN":"如果部落是治理单位，这套制度就以这个单位命名。"},{"no":"03","title":"Tribal social organization as studied","titleCN":"人类学研究的部落型社会组织","definition":"the form of social organization in which kinship groups, not classes or offices, set the order","definitionCN":"由亲缘群体而非阶级或职位决定秩序的社会组织形式","example":"The early survey described tribalism as a stage rather than a stain.","exampleCN":"早期调查报告把部落组织描述为一个阶段，而不是污点。","why":"researchers first used the word neutrally for a type of organization, before it acquired its critical tone.","whyCN":"研究者最初中性使用这个词，指一种组织类型，后来它才带上批评口吻。"},{"no":"04","title":"Sectarian hostility toward outsiders","titleCN":"贬义：对外人的宗派敌意","definition":"a narrow and hostile preference for one's own group, with suspicion of everyone outside it","definitionCN":"对本群体狭隘而敌意的偏护，对圈外一切人抱有怀疑","example":"The report blamed tribalism for the collapse of the shared council.","exampleCN":"报告把共同议会的瓦解归咎于宗派主义。","why":"loyalty inside a group looks like hostility from outside, and modern usage usually takes that outside view.","whyCN":"群体内的忠诚从外面看就是敌意，现代用法通常采取这个外部视角。"},{"no":"05","title":"Pride in tribal identity","titleCN":"对部落身份与文化的自豪","definition":"a positive attachment to one's people's language, customs and history","definitionCN":"对本民族语言、习俗与历史的正面依恋","example":"The festival celebrates tribalism as heritage, not as division.","exampleCN":"这个节庆把部落认同当作遗产来庆祝，而不是当作分裂。","why":"the same loyalty can be praised as heritage when the speaker stands inside the group.","whyCN":"当说话人站在群体内部时，同一种忠诚就会被赞为遗产。"},{"no":"06","title":"Factionalism inside an institution","titleCN":"机构内部的派系主义","definition":"the tendency of departments or teams to defend their own members against the whole organization","definitionCN":"部门或团队护自己成员、对抗整个机构的倾向","example":"Tribalism between departments delayed the merger by a year.","exampleCN":"部门之间的派系主义让合并推迟了一年。","why":"a company can reproduce the tribe's structure, so the critical sense transfers to offices.","whyCN":"公司可以复制部落的结构，因此这个批评义项也转移到办公室。"},{"no":"07","title":"Any in-group bias","titleCN":"抽象义：任何内群体偏私","definition":"the general tendency to favour insiders and distrust outsiders, whatever the group may be","definitionCN":"偏护圈内人、怀疑圈外人的普遍倾向，不论群体是什么","example":"Fans show tribalism even when the teams are made of strangers.","exampleCN":"即使球队由陌生人组成，球迷仍表现出内群体偏私。","why":"the abstract sense drops tribe, kin and land and keeps only the insider boundary.","whyCN":"抽象义丢掉部落、亲缘与土地，只保留圈内边界。"},{"no":"08","title":"Revival of tribal tradition","titleCN":"部落传统的复兴","definition":"a movement to restore tribal language, law or ceremony after a period of suppression","definitionCN":"在压制期之后恢复部落语言、法律或仪式的运动","example":"The school was founded as tribalism in the best sense, a recovery of lost songs.","exampleCN":"这所学校是作为最好意义上的部落传统复兴而创办的，找回失传的歌。","why":"when a tradition returns, the word can name the movement rather than the bias.","whyCN":"当传统回归时，这个词可以指那场运动，而不是指偏见。"}],"etymology":{"intro":{"en":"Tribalism is tribal plus -ism. The noun tribe came from Latin tribus through Old French, and the derivative is an English formation of the nineteenth century.","cn":"tribalism 由 tribal 加 -ism 构成。名词 tribe 经古法语来自拉丁 tribus，这一派生词是 19 世纪的英语构造。"},"items":[{"era":"LATIN TRIBUS","en":"Tribus named a division of the Roman people; its own origin is uncertain, and the hypotheses connecting it to tri- 'three' or to tribuere 'to allot' are not established.","cn":"tribus 指罗马人民的一个分区，其自身来源不确定；把它与 tri-「三」或 tribuere「分配」相联的假说均未证实。"},{"era":"ENGLISH TRIBE","en":"English tribe arrived in the fourteenth century through Old French tribu, first in biblical lists of the twelve tribes.","cn":"英语 tribe 在 14 世纪经古法语 tribu 传入，最初见于十二支派的圣经清单。"},{"era":"ADJECTIVE TRIBAL","en":"Tribal appears in the seventeenth century; the adjective made a noun of attitude easy to form.","cn":"tribal 出现在 17 世纪；这个形容词使表示态度的名词很容易构造。"},{"era":"SUFFIX -ISM","en":"The suffix -ismus names systems and doctrines, so tribal plus -ism produced a word for loyalty to tribes as a principle.","cn":"后缀 -ismus 标记体系与主张，因此 tribal 加 -ism 造出了把部落忠诚当作原则的词。"},{"era":"NINETEENTH CENTURY","en":"Colonial administrators and early anthropologists used tribalism for social organization, often ranking it against their own institutions.","cn":"殖民官员与早期人类学家用 tribalism 指社会组织形式，往往把它与自身制度排成高低。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest use of tribalism is only approximately dated, and the origin of tribus remains unsettled.","cn":"来源不确定（首见年代）：tribalism 的最早用法只有约数，tribus 的来源仍无定论。"}]},"similar":{"note":{"en":"Group one holds forms from the same family that are routinely confused with the attitude noun; group two holds words for group partiality in other frames.","cn":"第一组是同一词族中常与这一态度名词混淆的形式；第二组是其他框架下表示群体偏私的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tribal","ipa":"/ˈtraɪbl/","tag":"adjective","definition":"Describing what belongs to a tribe; tribalism is the attitude or system itself.","definitionCN":"描述属于部落的事物；tribalism 是态度或制度本身。"},{"word":"tribe","ipa":"/traɪb/","tag":"the group","definition":"The people themselves; tribalism can outlast any actual tribe.","definitionCN":"指人群本身；tribalism 可以比任何真实部落活得更久。"},{"word":"tribalist","ipa":"/ˈtraɪbəlɪst/","tag":"person","definition":"A person who puts the group first; the -ist suffix marks the supporter, not the doctrine.","definitionCN":"把本群体放在首位的人；-ist 标记支持者，而不是主张。"},{"word":"tribulation","ipa":"/ˌtrɪbjuˈleɪʃn/","tag":"different root","definition":"From Latin tribulare 'to thresh, afflict', built on tribulum 'threshing sledge'; it shares a prefix of sound only.","definitionCN":"来自拉丁 tribulare「打谷、使受苦」，由 tribulum「打谷板」构成，仅读音开头相近。"}]},{"heading":"NEAR MEANING","entries":[{"word":"factionalism","ipa":"/fækˈʃənəlɪzəm/","tag":"inside an institution","definition":"The splitting of an organization into rival cliques; it is the office version of tribalism.","definitionCN":"组织分裂为对立小集团；它是部落主义在办公室里的版本。"},{"word":"sectarianism","ipa":"/sekˈteəriənɪzəm/","tag":"doctrinal hostility","definition":"Hostility between religious or political sects; it adds doctrine, which tribalism need not have.","definitionCN":"宗教或政治派别之间的敌意；它含有教义成分，而部落主义不必有。"},{"word":"patriotism","ipa":"/ˈpætriətɪzəm/","tag":"loyalty to a state","definition":"Loyalty to a nation-state; it is loyalty upward in scale, while tribalism is loyalty to a smaller unit.","definitionCN":"对民族国家的忠诚；是规模更大的忠诚，而部落主义是对更小单位的忠诚。"},{"word":"nepotism","ipa":"/ˈnepətɪzəm/","tag":"family favouritism","definition":"Favouring relatives in appointments; it is one practical form that tribalism can take.","definitionCN":"任用亲属；它是部落主义可能采取的一种实际形式。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real adjective-plus-suffix build, real relatives and real fixed phrases.","cn":"正常联想：真实的形容词加后缀构造、真实同族词与真实搭配。"},"normal":[{"en":"tribal + -ism: loyalty to the tribe raised to a principle.","cn":"tribal + -ism：把对部落的忠诚提升为一条原则。"},{"en":"The family runs tribe, tribal, tribalism, tribalist, tribalistic, detribalize.","cn":"同族词包括 tribe、tribal、tribalism、tribalist、tribalistic、detribalize。"},{"en":"Fixed phrases mark the criticism: political tribalism, ethnic tribalism, overcome tribalism.","cn":"固定搭配标出批评语境：政治派系主义、族群宗派主义、克服宗派观念。"},{"en":"Compare factionalism: the same shape inside a company instead of a valley.","cn":"对照 factionalism：同样的形状，发生在公司里而不是山谷里。"},{"en":"Detribalize is the verb that names the opposite movement.","cn":"detribalize 是命名相反运动的动词。"}],"abstract":[{"en":"Picture a bridge wide enough for everyone, used one half at a time.","cn":"想象一座宽得能容下所有人的桥，却每次只用一半。"},{"en":"Picture a hiring committee that reads surnames before files.","cn":"想象一个招聘委员会，先看姓氏再看材料。"},{"en":"Picture a stadium where the same city cheers two different halves.","cn":"想象一座体育场，同一座城市为两个不同的半场欢呼。"}]},"examples":[{"en":"Economists warn that tribalism raises the cost of every public project.","cn":"经济学家警告说，宗派主义会抬高每一项公共工程的成本。"},{"en":"The novel treats tribalism as both shelter and cage.","cn":"这部小说把部落认同既写成庇护，也写成牢笼。"},{"en":"Reformers hoped railways would weaken tribalism; instead the lines carried it farther.","cn":"改革者原指望铁路削弱宗族观念，结果铁路把它带得更远。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「tribal（部落的）+ ism（主义）」——把本部落放在所有人前面 → 部落主义、宗派忠诚","word":"tribalism"},"root":"英语 tribal（tribe + -al，源自拉丁 tribus「分区」）+ -ism（体系或主张后缀）；tribus 自身来源不确定，相关假说均未证实。英语 tribalism。","sensesIntro":{"en":"Eight senses follow one preference: my group before the wider whole. The preference is read as a system, a research category, hostility, pride, office factionalism, a general bias and finally a movement to restore what was lost.","cn":"八个义项沿同一种偏好展开：本群体先于更大的整体。这种偏好再依次被读作制度、研究类别、敌意、自豪、职场派系、普遍偏私，最后读作恢复失落的运动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bridge used one half at a time by people who could share it.","cn":"核心意象：一座本可共享的桥，被两边的人分半使用。"},"chain":["MY GROUP FIRST","TRIBE-RUN POWER","SOCIAL TYPE","HOSTILITY OUTWARD","HERITAGE PRIDE","INSIDER BIAS"],"branches":[{"senses":"01 · 04","en":"FIRST AND HOSTILE: the same preference looks like warmth inside and enmity outside.","cn":"优先与敌意：同一种偏护，对内是温暖，对外是敌意。"},{"senses":"02 · 03","en":"SYSTEM AND STUDY: rule by tribes and the category used to describe it share one name.","cn":"制度与研究：部落掌权与描述它的类别共用同一个名称。"},{"senses":"05 · 08","en":"PRIDE AND REVIVAL: attachment to one's own culture can be celebrated or rebuilt.","cn":"自豪与复兴：对本文化的依恋，可以被庆祝，也可以被重建。"},{"senses":"06","en":"OFFICE FACTION: a company reproduces the valley's boundary inside one building.","cn":"职场派系：公司在一栋楼里复制了山谷的边界。"},{"senses":"07","en":"GENERAL BIAS: remove tribe and kin, and only the insider line is left.","cn":"普遍偏私：去掉部落与亲缘，只剩圈内那条线。"}]},"affixes":{"intro":{"en":"Tribalism is an English adjective plus a Greek-derived suffix; the wider family adds -ist, -istic and the reversive de-.","cn":"tribalism 是英语形容词加源自希腊的后缀；更大的词族再加 -ist、-istic 与反向前缀 de-。"},"latinIntro":{"en":"Latin tribus supplies the base noun, while the suffix -ismus came to English through Latin from Greek -ismos.","cn":"拉丁 tribus 提供基础名词，而后缀 -ismus 经拉丁语从希腊语 -ismos 进入英语。"},"items":[{"word":"tribus","structure":"tribus, tribus (Latin noun, fourth declension)","meaning":"a division of the Roman people","meaningCN":"罗马人民的一个分区","example":"The base noun named an administrative slice of a people.","exampleCN":"基础名词指人群中的一个行政切片。"},{"word":"tribe","structure":"tribus (Latin) → Old French tribu → English tribe","meaning":"a kinship community","meaningCN":"亲缘共同体","example":"Tribe is the noun behind the adjective.","exampleCN":"tribe 是这一形容词背后的名词。"},{"word":"-al","structure":"-al (English relational suffix)","meaning":"of or relating to","meaningCN":"……的；与……有关的","example":"Tribe plus -al yields tribal.","exampleCN":"tribe 加 -al 得出 tribal。"},{"word":"-ism","structure":"-ismus (Latin, from Greek -ismos)","meaning":"a system, practice or doctrine","meaningCN":"体系、实践或主张","example":"Tribal plus -ism yields tribalism.","exampleCN":"tribal 加 -ism 得出 tribalism。"},{"word":"-ist","structure":"-ista (agent or adherent suffix)","meaning":"one who supports or practices","meaningCN":"支持者或从事者","example":"Tribal plus -ist yields tribalist.","exampleCN":"tribal 加 -ist 得出 tribalist。"},{"word":"-istic","structure":"-isticus (adjective suffix, from Greek -istikos)","meaning":"having the character of","meaningCN":"具有……性质","example":"Tribalist plus -istic yields tribalistic.","exampleCN":"tribalist 加 -istic 得出 tribalistic。"},{"word":"de-","structure":"de- (Latin prefix, 'away, remove')","meaning":"removal, reversal","meaningCN":"去除；反转","example":"De- plus tribal plus -ize yields detribalize.","exampleCN":"de- 加 tribal 再加 -ize 得出 detribalize。"},{"word":"-ize","structure":"-izare (verb suffix, from Greek -izein through Latin)","meaning":"to make or become","meaningCN":"使……；变成……","example":"The suffix turns the adjective into a verb of change.","exampleCN":"这个后缀把形容词变成表示变化的动词。"},{"word":"-ation","structure":"-atio (Latin process noun suffix)","meaning":"the act or process","meaningCN":"动作或过程","example":"Detribalize plus -ation yields detribalization.","exampleCN":"detribalize 加 -ation 得出 detribalization。"},{"word":"tribalist","structure":"tribal + -ist","meaning":"one who puts the group first","meaningCN":"把本群体放在首位的人","example":"The tribalist trusted no outside referee.","exampleCN":"这位宗派拥护者不信任任何外部裁判。"}],"latinEntries":[{"word":"tribus","structure":"tribus, tribus (f., fourth declension)","meaning":"a division of the Roman people","meaningCN":"罗马人民的一个分区"},{"word":"tribuere","structure":"tribuere, tribui, tributum (verb, third conjugation)","meaning":"to allot, assign","meaningCN":"分配；分给"},{"word":"-ismus","structure":"-ismus (Latin suffix of systems, from Greek -ismos)","meaning":"a system or doctrine","meaningCN":"体系或主张"}]}},{"word":"clan","ipa_uk":"/klæn/","ipa_us":"/klæn/","definition_zh":"氏族；大家族；帮派团伙；游戏中的公会","definition_en":"a group of people who claim descent from a common ancestor and act as one social unit, or a close group with a shared interest","core_image":"一群人围在一起清点祖先的名字，把家谱铺在桌上。","scene":"山脚下的老屋里，族人围坐，把家谱铺在桌上，逐代念出祖先的名字并核对辈分。The elders of the clan keep the genealogy in a wooden chest and read it aloud at every wedding.","sceneCN":"这里 clan 指「共享祖先、以血缘联结的氏族」（第 1 个义项：以共同祖先为纽带的群体）；句意为族中长者把族谱收在木箱里，每逢婚礼就当众诵读。可辨识物件：家谱、木箱、老屋、围坐的族人。","pos":[{"tag":"n.","zh":"氏族；家族；部落分支"},{"tag":"n.","zh":"帮派；小集团（口语）"}],"collocations":[{"phrase":"the head of the clan","zh":"族长"},{"phrase":"clan loyalty","zh":"家族忠诚"},{"phrase":"clan warfare","zh":"氏族间的争斗"},{"phrase":"join a clan","zh":"加入一个氏族或公会"},{"phrase":"clan structure","zh":"氏族结构"}],"forms":[{"label":"单数","form":"clan"},{"label":"复数","form":"clans"},{"label":"形容词（氏族的）","form":"clannish"},{"label":"副词（抱团排外）","form":"clannishly"},{"label":"名词（抱团排外）","form":"clannishness"}],"derivatives":[{"word":"clannish","pos":"adj.","zh":"clan + -ish（形容词后缀）→ 抱团排外的，语义落在群体内部的紧密与排他"},{"word":"clannishly","pos":"adv.","zh":"clannish + -ly（副词后缀）→ 以抱团排外的方式，语义仅改词性"},{"word":"clannishness","pos":"n.","zh":"clannish + -ness（名词后缀）→ 抱团排外的性质，语义抽象化为品质"},{"word":"clansman","pos":"n.","zh":"clan + 连接成分 -s + man（人）→ 同氏族成员，语义落在成员身份"},{"word":"clanship","pos":"n.","zh":"clan + -ship（状态后缀）→ 氏族归属与氏族制度，语义由群体转为制度"}],"senses":[{"no":"01","title":"A group tracing one ancestor","titleCN":"共享祖先的氏族","definition":"a social unit whose members claim descent from a common ancestor and recognize shared obligations","definitionCN":"成员自称出自同一祖先、并承认相互义务的社会单位","example":"The whole clan gathers at the ancestral hall each spring.","exampleCN":"每年春天，整个氏族都在祠堂聚会。","why":"Scots clann originally meant 'children, family', so the first sense is a family widened to all who claim one ancestor.","whyCN":"苏格兰语 clann 原意是「子女、家族」，因此第一义就是把家庭扩展到所有自称同祖的人。"},{"no":"02","title":"An extended family network","titleCN":"大家族与亲属网络","definition":"the practical network of relatives who help one another with money, labour and marriages","definitionCN":"在经济、劳力与婚姻上互相帮衬的亲属关系网络","example":"The marriage joined two clans that had traded for a century.","exampleCN":"这场婚姻把两个通商百年的家族连在一起。","why":"a clan in daily use is less a pedigree than a set of people you can call on, so the kin group becomes a support network.","whyCN":"日常所说的 clan 与其说是一份谱系，不如说是一群可以求助的人，于是血亲团体变成了互助网络。"},{"no":"03","title":"A tribal division under a chief","titleCN":"部落之下由首领统辖的分支","definition":"a subdivision of a tribe, usually led by a chief or a council of elders","definitionCN":"部落之下的分支，通常由首领或长老会领导","example":"Each clan sent one elder to the tribal council.","exampleCN":"每个氏族派一名长老参加部落议事会。","why":"anthropology needed a unit between the single household and the whole tribe, and the old family word took that place.","whyCN":"人类学需要在单户家庭与整个部落之间找一个单位，旧的「家族」词就占了这个位置。"},{"no":"04","title":"A close exclusive faction","titleCN":"抱团的排外小集团","definition":"a small group of colleagues or friends who promote one another and keep outsiders at a distance","definitionCN":"互相提携、对圈外人保持距离的同事或朋友小圈子","example":"The department is run by a clan of people who lunch together.","exampleCN":"这个部门由一个总在一起吃午饭的小圈子把持。","why":"the family image is borrowed with irony: the group behaves as if related, and its warmth excludes.","whyCN":"借用了家庭的意象并带讽刺：这群人表现得像亲戚，其温情同时排斥外人。"},{"no":"05","title":"A criminal or street gang","titleCN":"犯罪集团或街头帮派","definition":"an organized criminal group that protects its members and demands loyalty above the law","definitionCN":"保护成员、要求忠诚高于法律的有组织犯罪团体","example":"Police linked the warehouse fire to a clan fighting over the docks.","exampleCN":"警方把仓库大火与一个争夺码头的帮派联系起来。","why":"loyalty, silence and inherited membership look like kinship rules, so the word moves easily from family to gang.","whyCN":"忠诚、缄默与世袭身份都像亲属规则，因此这个词很容易从家族滑向帮派。"},{"no":"06","title":"A gaming guild of players","titleCN":"玩家自发组成的公会","definition":"an in-game association of players who share a name, a chat channel and joint activities","definitionCN":"共享名称、聊天频道与集体活动的游戏内玩家组织","example":"Our clan meets online every Friday to raid together.","exampleCN":"我们的公会每周五上线，一起团队副本。","why":"online groups revive the old feature of a shared name and mutual aid, so players borrowed the word whole.","whyCN":"线上群体恢复了共享名称与互助的旧特点，因此玩家把整个词借了过去。"},{"no":"07","title":"A biological lineage","titleCN":"生物学中的同一世系","definition":"a set of individuals or cell lines descended from one common ancestor","definitionCN":"由一个共同祖先传下来的个体集合或细胞系","example":"All the mice in the study belong to a single clan.","exampleCN":"研究中的全部小鼠都属于同一个世系。","why":"genetics kept only the descent component of the word and dropped the social obligations.","whyCN":"遗传学只保留了这个词的「传承」成分，去掉了社会义务。"},{"no":"08","title":"An in-group sharing taste or habit","titleCN":"抽象义：共享品味或习惯的内群体","definition":"any loose in-group defined by a shared taste, jargon or routine rather than by kinship","definitionCN":"由共同品味、行话或习惯而非血亲界定出来的松散内群体","example":"The film has become a clan of people who quote it daily.","exampleCN":"这部电影已经成了一个每天引用台词的圈子。","why":"once the word means any close group, kinship can drop out entirely and only the boundary remains.","whyCN":"一旦这个词泛指任何紧密群体，血亲关系就可完全脱落，只剩边界。"}],"etymology":{"intro":{"en":"Clan came into English from Scottish Gaelic clann 'children, family', which goes back to Old Irish cland and, through borrowing, to Latin planta 'sprout, plant'.","cn":"clan 从苏格兰盖尔语 clann「子女、家族」进入英语，上承古爱尔兰语 cland，再往上经借用关系连到拉丁 planta「芽、植株」。"},"items":[{"era":"LATIN PLANTA","en":"Planta meant 'sprout, shoot, plant'; the image is a shoot growing from one stock, which is also how a lineage is pictured.","cn":"planta 意为「芽、新枝、植株」；意象是从同一根桩上长出的新枝，血统也正以此取象。"},{"era":"BORROWING INTO CELTIC","en":"The Latin noun was taken into early Celtic as a word for offspring or family; the exact route is source uncertain, and no single borrowing path is agreed.","cn":"这个拉丁名词被早期凯尔特语借去，用来指后代或家族；具体路径来源不确定，学界并无一致说法。"},{"era":"OLD IRISH CLAND","en":"Old Irish cland is recorded with the sense 'family, offspring'; from it comes the Gaelic form that English later took.","cn":"古爱尔兰语 cland 有「家族、后代」的义项记录；盖尔语形式即由其而来，英语后来又借入这个盖尔语形式。"},{"era":"SCOTTISH GAELIC CLANN","en":"Scottish Gaelic clann kept the meaning 'children, family' and was used for a group claiming one ancestor, without any claim to a separate race.","cn":"苏格兰盖尔语 clann 保留「子女、家族」之义，用来指自称同祖的一群人，并不含「另一个种族」的意思。"},{"era":"ENGLISH CLAN","en":"English took the word in the late Middle Ages for Highland kin groups; the wider senses of faction and guild are much later extensions.","cn":"英语在中世纪晚期借入此词，指高地亲族团体；小集团与公会等更宽的义项是很晚的延伸。"},{"era":"MODERN DRIFT","en":"The sense 'race' sometimes read into the word is a later misunderstanding; dictionaries stress descent and loyalty, not biology.","cn":"有时被人读进这个词的「种族」义属后来误解；词典强调的是世系与忠诚，而非生物学。"}]},"similar":{"note":{"en":"Group one holds words whose form is close but whose root is different; group two holds real kin-group terms that differ in scale or in the tie invoked.","cn":"第一组是形近而词根不同的词；第二组是真正的亲族词，差别在规模或所诉诸的纽带。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"clam","ipa":"/klæm/","tag":"different root","definition":"A shellfish or the shell itself; its own origin is source uncertain, and it has no established link to clan beyond a similar shape and short vowel.","definitionCN":"蛤蜊或蛤壳，其自身来源不确定，除拼写与短元音外与 clan 并无确立的联系。"},{"word":"clamp","ipa":"/klæmp/","tag":"different root","definition":"A device that holds things tightly; its origin is not established as the same as clan's, and only the opening sounds coincide.","definitionCN":"夹紧器；其来源是否与 clan 相同并无定论，只共享开头音，不能据此认为同源。"},{"word":"klan","ipa":"/klæn/","tag":"loan spelling, different referent","definition":"A homophone often confused with clan; the organisation it names is entirely different, and any historical link between the two words is source uncertain.","definitionCN":"与 clan 同音、常被混淆的词；它所称的组织完全不同，两词之间是否有历史联系则来源不确定。"},{"word":"clone","ipa":"/kləʊn/","tag":"different root","definition":"From Greek klōn 'twig, slip', a cutting used to propagate a plant; the 'twig' picture is the only faint echo of clan.","definitionCN":"来自希腊语 klōn「枝条、插穗」，指用来繁殖植物的切枝；只有「枝条」意象与 clan 隐约相像。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tribe","ipa":"/traɪb/","tag":"larger political unit","definition":"A larger group of clans or bands united by a common name and leadership; a clan is one unit inside it.","definitionCN":"由多个氏族或部落分支联合而成、共享名称与领导的更大群体；clan 是其中一个单位。"},{"word":"lineage","ipa":"/ˈlaɪnɪdʒ/","tag":"descent line only","definition":"A line of descent traced from an ancestor; it stresses genealogy and may have no corporate action or territory.","definitionCN":"从某位祖先追下来的世系；强调谱系，未必有集体行动或领地。"},{"word":"kindred","ipa":"/ˈkɪndrəd/","tag":"relatives, not a named group","definition":"One's relatives taken together, without a clan name, a chief or a common ritual.","definitionCN":"一个人全部亲属的集合，没有氏族名称、首领或共同仪式。"},{"word":"extended family","ipa":"/ɪkˈstendɪd ˈfæmɪli/","tag":"household scale","definition":"Relatives beyond the nuclear household who cooperate in daily life; the term is domestic, while a clan may hold land and feuds.","definitionCN":"核心家庭之外、在日常生活中互助的亲属；这个词属家庭层面，而氏族可拥有土地与世仇。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Gaelic source, the Latin plant image, and the words English built on clan.","cn":"正常联想：真实的盖尔语来源、拉丁「植株」意象，以及英语在 clan 之上造出的词。"},"normal":[{"en":"Gaelic clann 'children': a clan is a family written large.","cn":"盖尔语 clann「子女」：氏族就是一个放大了的家庭。"},{"en":"Latin planta 'sprout' sits at the far end of the borrowing chain: one stock, many shoots.","cn":"借用链的最远端是拉丁 planta「芽」：一根桩，许多新枝。"},{"en":"clan + -ish gives clannish, the everyday adjective for a group that keeps others out.","cn":"clan 加 -ish 得到 clannish，是形容群体排外的日常形容词。"},{"en":"Clansman and clanship mark the member and the system.","cn":"clansman 与 clanship 分别标记成员与制度。"},{"en":"The fixed phrase 'the head of the clan' shows how a group is imagined as one body.","cn":"固定搭配「族长」显示这群人被想象成一个身体。"}],"abstract":[{"en":"Picture a name that everyone in the room shares and no outsider may use.","cn":"想象一个名字，屋里人人共有，外人不得使用。"},{"en":"Picture a debt that passes to children who never agreed to it.","cn":"想象一笔债，传给从未同意过的孩子。"},{"en":"Picture a family tree with roots below the soil, where nobody can see where it began.","cn":"想象一棵家谱树，根埋在土下，无人看得见它从何处起头。"}]},"examples":[{"en":"The clan still owns the terraced fields below the village.","cn":"这个氏族至今拥有村下的梯田。"},{"en":"In the game, a clan can hold a fortress only if its members log in together.","cn":"在游戏里，公会只有成员一起上线才能占据堡垒。"},{"en":"The novelist describes a political clan that treats the ministry as family property.","cn":"小说家描写一个把部委当作家族财产的政治小集团。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「克蓝」：一族人都穿同一种蓝布衣，远远一看便知是自己人 → 氏族、家族、抱团的小集团","word":"clan"},"root":"苏格兰盖尔语 clann「子女、家族」< 古爱尔兰语 cland < 拉丁 planta「芽、植株」（借词链）；现代英语 clan。","sensesIntro":{"en":"Eight senses spread outward from one ancestor: a named descent group, then its living network, its place in a tribe, then groups that only imitate kinship, a gang, a gaming guild, a biological line and finally any in-group with a boundary.","cn":"八个义项从一位祖先向外扩散：有名号的世系群体，接着是它活生生的关系网、它在部落中的位置，然后是只模仿亲属关系的群体、帮派、游戏公会、生物世系，最后是任何有边界的内部圈子。"},"semanticMap":{"core":{"en":"CORE IMAGE: one ancestor's name, and everyone who answers to it.","cn":"核心意象：一个祖先的名字，以及所有应这个名字的人。"},"chain":["NAME THE ANCESTOR","COUNT THE KIN","PLACE THE GROUP IN A TRIBE","CLOSE THE BOUNDARY","EXTEND TO ANY IN-GROUP","TRACE THE LINE IN NATURE"],"branches":[{"senses":"01 · 03","en":"DESCENT AND POLITICS: a named kin group and its standing inside a larger tribe.","cn":"世系与政治：有名号的亲族群体，以及它在更大部落中的地位。"},{"senses":"02","en":"LIVING NETWORK: the relatives one actually calls on for labour, money and marriage.","cn":"活的关系网：真正能为劳力、金钱与婚姻去求助的那些亲戚。"},{"senses":"04 · 05","en":"FAMILY IMITATED: factions and gangs borrow the loyalty and silence of kinship.","cn":"被模仿的家庭：小集团与帮派借用了亲属关系的忠诚与缄默。"},{"senses":"06 · 08","en":"VOLUNTARY BOUNDARY: guilds and taste groups keep the name and the inside/outside line.","cn":"自愿的边界：公会与品味圈子保留了名称与内外界线。"},{"senses":"07","en":"PURE LINEAGE: biology keeps only descent and lets the social duties fall away.","cn":"纯世系：生物学只留下传承，让社会义务脱落。"}]},"affixes":{"intro":{"en":"Clan itself is a borrowing, so its family is mostly English suffixes added to a Gaelic noun, with a Latin noun at the end of the borrowing chain.","cn":"clan 本身是借词，因此它的词族主要是加在这个盖尔语名词上的英语后缀，借用链末端则是一个拉丁名词。"},"latinIntro":{"en":"The Latin source is planta 'sprout, plant' with its verb plantare; Latin supplies no further relative of English clan except through this borrowing.","cn":"拉丁语一端是 planta「芽、植株」及其动词 plantare；除这条借用链之外，拉丁语并不提供英语 clan 的其他同族词。"},"items":[{"word":"clan","structure":"Scottish Gaelic clann (noun), borrowed whole","meaning":"a group claiming one ancestor","meaningCN":"自称同祖的群体","example":"The word entered English with no change of shape.","exampleCN":"这个词以原来的形式整体进入英语。"},{"word":"-ish","structure":"-ish (Old English adjective suffix)","meaning":"having the character of","meaningCN":"具有……性质的","example":"Clan plus -ish yields clannish.","exampleCN":"clan 加 -ish 得出 clannish。"},{"word":"clannish","structure":"clan + -ish","meaning":"loyal to one's group and cold to outsiders","meaningCN":"对内忠诚、对外冷淡的","example":"The office felt clannish to a new arrival.","exampleCN":"新来的人觉得这间办公室很抱团排外。"},{"word":"clannishly","structure":"clannish + -ly","meaning":"in an exclusive, group-bound way","meaningCN":"以排外、抱团的方式","example":"The hiring was done clannishly, among cousins.","exampleCN":"招聘是在表亲之间抱团完成的。"},{"word":"clannishness","structure":"clannish + -ness","meaning":"the quality of being exclusive","meaningCN":"排外抱团的性质","example":"Their clannishness kept good applicants away.","exampleCN":"他们的抱团排外把优秀申请者挡在门外。"},{"word":"clansman","structure":"clan + -s- + man","meaning":"a member of a clan","meaningCN":"氏族成员","example":"A clansman carried the chief's banner.","exampleCN":"一名氏族成员扛着首领的旗帜。"},{"word":"clanship","structure":"clan + -ship","meaning":"the system of clan loyalty","meaningCN":"氏族归属与忠诚制度","example":"Clanship shaped who could vote in the village.","exampleCN":"氏族归属决定了村里谁有投票权。"},{"word":"-ship","structure":"-scipe (Old English state suffix)","meaning":"state, condition or office","meaningCN":"状态、身份或职位","example":"Clan plus -ship yields clanship.","exampleCN":"clan 加 -ship 得出 clanship。"},{"word":"planta","structure":"planta, plantae (Latin noun, first declension)","meaning":"sprout, shoot, plant","meaningCN":"芽；新枝；植株","example":"The Latin noun opens the borrowing chain.","exampleCN":"这个拉丁名词是借用链的起点。"},{"word":"plantare","structure":"plantare, plantavi, plantatum (Latin verb, first conjugation)","meaning":"to set out, to plant","meaningCN":"栽种；插枝","example":"The verb describes putting a shoot into the ground.","exampleCN":"这个动词指把新枝插进土里。"}],"latinEntries":[{"word":"planta","structure":"planta, plantae (f., first declension)","meaning":"sprout, shoot, plant","meaningCN":"芽；新枝；植株"},{"word":"plantare","structure":"plantare, plantavi, plantatum (verb, first conjugation)","meaning":"to plant, set out","meaningCN":"栽种；插枝"},{"word":"plantatio","structure":"plantatio, plantationis (f., third declension)","meaning":"a planting, setting out","meaningCN":"栽种；插植"}]}},{"word":"kinship","ipa_uk":"/ˈkɪnʃɪp/","ipa_us":"/ˈkɪnʃɪp/","definition_zh":"亲属关系；血亲与姻亲；亲切感、认同感；亲属制度研究","definition_en":"the relationship between people who are related by blood or by marriage, or a feeling of closeness and shared identity","core_image":"一张织锦上两簇同色的线，一股从上一代直着下来，一股在两边横向打结。","scene":"织锦铺在桌上，中间一股线从上一代直着垂下，两侧另有几股横向打结，把两家人缝到一起。The woven panel shows both kinship by blood and marriage ties between the two villages.","sceneCN":"这里 kinship 指「由血缘或婚姻连接起来的亲属关系」（第 1 个义项：血亲层面的亲属关系）；句意为这块织锦同时呈现两村之间的血亲与姻亲关系。可辨识物件：织锦、垂下的直线、横向的结、两侧的线团。","pos":[{"tag":"n.","zh":"亲属关系；血亲与姻亲"},{"tag":"n.","zh":"亲切感；精神上的亲近"}],"collocations":[{"phrase":"blood kinship","zh":"血亲关系"},{"phrase":"kinship by marriage","zh":"姻亲关系"},{"phrase":"a sense of kinship","zh":"亲近感"},{"phrase":"kinship terms","zh":"亲属称谓"},{"phrase":"kinship system","zh":"亲属制度"},{"phrase":"kinship ties","zh":"亲属纽带"}],"forms":[{"label":"形容词（亲属的）","form":"kin"},{"label":"复数名词（亲属）","form":"kin"},{"label":"名词（亲属关系）","form":"kinship"},{"label":"集合名词（同族）","form":"kindred"},{"label":"形容词（血缘的）","form":"consanguine"},{"label":"名词（血缘）","form":"consanguinity"}],"derivatives":[{"word":"kin","pos":"n./adj.","zh":"古英语 cynn（家族、种类）→ 直接保留为「亲属；有亲属关系的」，语义收窄到人"},{"word":"kinsman","pos":"n.","zh":"kin + 属格 -s + man（人）→ 男性亲属，语义落在个体成员"},{"word":"kinswoman","pos":"n.","zh":"kinsman 的 man 换为 woman → 女性亲属，语义仅改性别"},{"word":"kindred","pos":"n./adj.","zh":"kin + -red（古英语 rǣden「条件、状态」）→ 全体亲属，语义由个体转到集体"},{"word":"akin","pos":"adj.","zh":"a-（表「属于」）+ kin → 同族的；引申为「相似的」，语义由血缘扩到性质"}],"senses":[{"no":"01","title":"Relation through blood","titleCN":"血亲关系","definition":"the tie between people descended from the same ancestor","definitionCN":"出自同一祖先的人之间的纽带","example":"Kinship through the mother's line decides who inherits the orchard.","exampleCN":"母系的血亲关系决定果园由谁继承。","why":"kin meant 'family, kind' in Old English, and -ship names a state, so kinship is literally the state of being of one family.","whyCN":"古英语的 kin 意为「家族、种类」，-ship 表示状态，因此 kinship 字面就是「同属一家」的状态。"},{"no":"02","title":"Relation created by marriage","titleCN":"由婚姻建立的姻亲关系","definition":"the tie created when a marriage joins two families, with its own duties and claims","definitionCN":"婚姻把两家人联结起来所产生、自带义务与权利主张的纽带","example":"Their kinship began as an alliance of two farming households.","exampleCN":"他们的姻亲关系起初是两个农耕家庭的结盟。","why":"the word covers anyone a family treats as related, so in-laws enter it as soon as the household counts them.","whyCN":"这个词涵盖家庭当作亲属的所有人，因此一旦家庭把姻亲算进来，姻亲就进入此义。"},{"no":"03","title":"A feeling of closeness","titleCN":"亲人般的亲近感","definition":"a felt bond of warmth and understanding with someone who is not actually a relative","definitionCN":"与并非真正亲属的人之间感到的温暖与理解纽带","example":"She felt a kinship with the strangers who had fled the same flood.","exampleCN":"她与那些逃离同一场洪水的陌生人感到一种亲近。","why":"if shared descent makes people kin, shared experience can produce the same feeling, and the word follows the feeling.","whyCN":"既然共同的血统使人成为亲属，共同的经历也能产生同样的感觉，词义便跟着感觉走。"},{"no":"04","title":"The study of kin systems","titleCN":"亲属制度的研究","definition":"the branch of anthropology that compares how societies define relatives, descent and marriage","definitionCN":"比较各社会如何界定亲属、世系与婚姻的人类学分支","example":"Kinship was the first subject taught in the new anthropology department.","exampleCN":"亲属制度是新设人类学系最先开课的题目。","why":"once researchers compared many societies, the mass noun became a field of study rather than one family's tie.","whyCN":"研究者比较众多社会之后，这个不可数名词就从一家人的关系变成一个研究领域。"},{"no":"05","title":"A relation between languages or ideas","titleCN":"语言或思想上的同源关系","definition":"a shared origin or close structural relation between languages, ideas or works","definitionCN":"语言、思想或作品之间共享的来源或紧密的结构关系","example":"The kinship of the two dialects shows in their verb endings.","exampleCN":"两种方言的同源关系体现在动词词尾上。","why":"family trees serve both genealogists and linguists, so the word moves from people to anything that branches from one source.","whyCN":"家谱树既供谱系学者用，也供语言学者用，于是这个词从人扩到任何由同一源头分出的东西。"},{"no":"06","title":"A close structural resemblance","titleCN":"结构上的相似","definition":"a strong likeness between two things that suggests they belong to one family of forms","definitionCN":"两物之间强烈相似，使人感到它们属于同一形式家族","example":"The kinship between the two poems lies in their shared metre.","exampleCN":"两首诗近缘之处在于共用同一格律。","why":"descent can be replaced by resemblance: the word keeps the family shape but drops the ancestor.","whyCN":"传承关系可被相似性替代：这个词保留家族的形状，却丢掉了祖先。"},{"no":"07","title":"A nation imagined as one family","titleCN":"被想象成一个大家庭的民族","definition":"a shared national or ethnic identity expressed as brotherhood and common ancestry","definitionCN":"以兄弟情谊与共同祖先表达的民族或族群认同","example":"The speech appealed to kinship among all the islanders.","exampleCN":"演讲唤起全体岛民之间的同胞之情。","why":"politics borrows the warmth of the family word to make a large population feel related.","whyCN":"政治借用了家庭词的温情，让大量人口感到彼此是亲属。"},{"no":"08","title":"A natural or spiritual affinity","titleCN":"抽象义：人与物、人与地之间的天然契合","definition":"a deep affinity felt between a person and a place, an animal or a calling","definitionCN":"人与地方、动物或使命之间感到的深切契合","example":"He speaks of his kinship with the river as if it were a relative.","exampleCN":"他谈起自己与这条河的契合，仿佛那是位亲戚。","why":"the abstract end of the word keeps only affinity, with no genealogy behind it at all.","whyCN":"这个词的抽象一端只保留契合，背后已完全没有谱系。"}],"etymology":{"intro":{"en":"Kinship joins kin, from Old English cynn 'family, kind', to the suffix -ship. Cynn goes back to Germanic *kunja-, and the deeper Indo-European form is a reconstruction.","cn":"kinship 由古英语 cynn「家族、种类」加后缀 -ship 构成。cynn 上承日耳曼语 *kunja-，更深的印欧语形式则属重构。"},"items":[{"era":"OLD ENGLISH CYNN","en":"Cynn meant 'family, race, kind' and also 'nature, quality'; the recorded word already carried both the kin sense and the kind sense.","cn":"cynn 意为「家族、族类、种类」，也指「本性、品质」；有记录的这个词已兼有亲属与种类两义。"},{"era":"GERMANIC *KUNJA-","en":"The Germanic base *kunja- is generally regarded as the source of cynn and of cognates in the other Germanic languages.","cn":"一般认为日耳曼语词基 *kunja- 是 cynn 及其在其他日耳曼语中同源词的来源。"},{"era":"GERMANIC *KUNNAN","en":"*Kunnan 'to know' is generally connected with *kunja-: a family is the group one knows and recognizes. English know is the same root.","cn":"一般认为 *kunnan「知道」与 *kunja- 相关：家族就是自己所认识、所认可的那群人。英语 know 同出这个词根。"},{"era":"INDO-EUROPEAN *ǴENH₁-","en":"*Ǵenh₁- 'to give birth, beget' is generally regarded as the deeper source of *kunja-, but the Indo-European form itself is a reconstruction.","cn":"一般认为 *ǵenh₁-「生育、产生」是 *kunja- 更深层的来源，但该印欧语形式本身属重构。"},{"era":"SUFFIX -SHIP","en":"-ship, from Old English -scipe 'state, condition', turns a noun of persons into a noun of relation, as in kinship and friendship.","cn":"-ship 出自古英语 -scipe「状态、情形」，把指人的名词变成指关系的名词，kinship 与 friendship 皆如此。"},{"era":"MODERN SPECIALIZATION","en":"The compound is recorded from the Middle Ages; its use as the name of an anthropological field is a nineteenth-century specialization.","cn":"这个复合词在中世纪已有记录；把它用作人类学领域名称则是 19 世纪的专业化用法。"}]},"similar":{"note":{"en":"Group one holds look-alikes, one of them a true relative with a different everyday sense; group two holds terms that name one part or one type of the same field.","cn":"第一组是形近词，其中一个是真同族词但日常义不同；第二组是只指同一领域某一部分或某种类型的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"kind","ipa":"/kaɪnd/","tag":"same root, different sense","definition":"From the same cynn, but its everyday sense is 'type' or 'good-natured'; the family sense survives only in kindred and mankind.","definitionCN":"同出 cynn，但日常义是「种类」或「和善的」；家族义只留在 kindred 与 mankind 里。"},{"word":"kinetic","ipa":"/kɪˈnetɪk/","tag":"different root","definition":"From Greek kinētikos 'of motion', built on kinein 'to move'; motion, not kinship, is its centre.","definitionCN":"来自希腊语 kinētikos「运动的」，由 kinein「移动」构成；中心是运动，不是亲属关系。"},{"word":"kink","ipa":"/kɪŋk/","tag":"different root","definition":"A twist or bend, probably from Middle Dutch; the shared opening sound hides a totally different source.","definitionCN":"扭结、弯折，可能来自中古荷兰语；相同的开头音掩盖了完全不同的来源。"},{"word":"kiosk","ipa":"/ˈkiːɒsk/","tag":"different root","definition":"From Turkish köşk 'pavilion', through French; it names a small booth and has no link to family.","definitionCN":"经法语来自土耳其语 köşk「亭」，指小售货亭，与家族无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"affinity","ipa":"/əˈfɪnəti/","tag":"in-law link or attraction","definition":"Relationship through marriage, or a natural attraction; it names one kind of tie, while kinship covers both kinds and the feeling as well.","definitionCN":"通过婚姻形成的关系，或天然的吸引；它只指一种纽带，而 kinship 兼指两类关系与那种感觉。"},{"word":"consanguinity","ipa":"/ˌkɒnsæŋˈɡwɪnəti/","tag":"blood only","definition":"Shared descent from a common ancestor, literally 'with the same blood'; marriage ties are excluded.","definitionCN":"出自同一祖先的血统关系，字面为「同血」；姻亲关系不在其中。"},{"word":"descent","ipa":"/dɪˈsent/","tag":"the line, not the bond","definition":"The line traced from an ancestor to a descendant; kinship is the whole set of ties, descent only the vertical line.","definitionCN":"从祖先追到后代的那条线；kinship 是全部纽带的集合，descent 只是纵向那条线。"},{"word":"relatedness","ipa":"/rɪˈleɪtɪdnəs/","tag":"measurable connection","definition":"The degree to which two people or populations share genes; it is a technical measure, not the social claim that kinship carries.","definitionCN":"两人或两群体共享基因的程度；这是技术性度量，而非 kinship 自带的社会主张。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the recorded Old English noun, its Germanic relatives, and the English words built with the same two morphemes.","cn":"正常联想：有记录的古英语名词、它的日耳曼同源词，以及用同两个语素造出的英语词。"},"normal":[{"en":"kin + -ship, exactly as friend + -ship: the suffix names a state of relation.","cn":"kin 加 -ship，正如 friend 加 -ship：后缀标出关系的状态。"},{"en":"Old English cynn covered both 'family' and 'kind', which is why kind survives beside kin.","cn":"古英语 cynn 兼指「家族」与「种类」，所以 kind 与 kin 至今并存。"},{"en":"The same Germanic base gives English kin and German Kind 'child'.","cn":"同一日耳曼语词基给出英语 kin 与德语 Kind「孩子」。"},{"en":"*Kunnan 'know' explains the ancient link between knowing someone and counting them as family.","cn":"*kunnan「知道」解释了「认识某人」与「把某人算作家人」之间的古老联系。"},{"en":"The fixed phrase 'a sense of kinship' shows the feeling sense plainly.","cn":"固定搭配「一种亲近感」清楚显示了这个感觉义。"}],"abstract":[{"en":"Picture a loom where one thread going down and one thread crossing are equally strong.","cn":"想象一台织机，一根向下的线与一根横穿的线一样结实。"},{"en":"Picture a stranger who reminds you of your sister, and the word that arrives before any reason.","cn":"想象一个让你想起姐姐的陌生人，以及那句先于任何理由出现的话。"},{"en":"Picture a language family drawn as a tree that grows downward from a single seed.","cn":"想象一个语系被画成一棵树，从一粒种子向下生长。"}]},"examples":[{"en":"Kinship ties still decide which family gets the water rights.","cn":"亲属纽带仍然决定哪个家庭得到水权。"},{"en":"The two composers share a kinship of style rather than of blood.","cn":"这两位作曲家在风格上相近，而非血脉相连。"},{"en":"Early anthropology mapped kinship before it mapped trade.","cn":"早期人类学先绘制亲属关系，再绘制贸易路线。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「亲」与「ship」同船：亲属关系像一条船，把散在两岸的人装在一起 → 血亲、姻亲、亲近感","word":"kinship"},"root":"古英语 cynn「家族、种类」< 日耳曼语 *kunja-，与 *kunnan「知道」（同源 know）相关；更深一般认为来自印欧语 *ǵenh₁-「生育」，该形式属重构。加 -ship 构成 kinship。","sensesIntro":{"en":"Eight senses move from the fact of descent to the feeling of it: blood tie, marriage tie, felt closeness, the comparative study of such ties, shared origin in language, structural likeness, national brotherhood and finally affinity with a place.","cn":"八个义项从「传承的事实」走向「传承的感觉」：血亲、姻亲、感到的亲近、对这类纽带的比较研究、语言上的同源、结构相似、民族同胞之情，最后是与地方的契合。"},"semanticMap":{"core":{"en":"CORE IMAGE: a loom with one vertical thread of descent and one horizontal thread of marriage.","cn":"核心意象：一台织机，一根纵向的传承之线，一根横向的婚姻之线。"},"chain":["TRACE THE BLOOD","KNOT IN THE MARRIAGE","FEEL THE CLOSENESS","COMPARE THE SYSTEMS","EXTEND TO LANGUAGE","KEEP ONLY AFFINITY"],"branches":[{"senses":"01 · 02","en":"TWO KINDS OF TIE: one inherited, one made by marriage, equally binding in daily life.","cn":"两类纽带：一类继承而来，一类由婚姻造成，在日常生活中同样有约束力。"},{"senses":"03 · 07","en":"WARMTH WRIT LARGE: the feeling of closeness, scaled from two people up to a whole nation.","cn":"被放大的温情：亲近感从两个人扩展到整个民族。"},{"senses":"04","en":"THE COMPARATIVE FIELD: many societies' rules studied side by side as one subject.","cn":"比较领域：把众多社会的规则并置为一个学科来研究。"},{"senses":"05 · 06","en":"SHARED ORIGIN IN THINGS: languages and works inherit, or merely resemble, one source.","cn":"事物之间的同源：语言与作品或真继承同一源头，或只是彼此相像。"},{"senses":"08","en":"PURE AFFINITY: no ancestor left, only the fit between a person and a place.","cn":"纯契合：祖先已退场，只剩人与地方之间的相合。"}]},"affixes":{"intro":{"en":"Kinship is the clearest case of an English word built from two native morphemes: a noun of family plus a suffix of state.","cn":"kinship 是英语本土语素构词最清楚的例子：一个表家族的名词加一个表状态的后缀。"},"latinIntro":{"en":"There is no Latin relative here: kin is native Germanic, so the Latin list is empty by design, and the family is read through Old English and Germanic forms only.","cn":"这里没有拉丁同族词：kin 是本土日耳曼词，因此拉丁词条按体例留空，整个词族只经古英语与日耳曼语形式来读。"},"items":[{"word":"kin","structure":"Old English cynn (noun), surviving unchanged in form","meaning":"family, relatives","meaningCN":"家族；亲属","example":"His kin live in the next valley.","exampleCN":"他的亲属住在邻谷。"},{"word":"-ship","structure":"-scipe (Old English noun suffix)","meaning":"state or condition","meaningCN":"状态或情形","example":"Kin plus -ship yields kinship.","exampleCN":"kin 加 -ship 得出 kinship。"},{"word":"kinship","structure":"kin + -ship","meaning":"the state of being related","meaningCN":"具有亲属关系的状态","example":"Kinship carries duties as well as warmth.","exampleCN":"亲属关系既带来温情，也带来义务。"},{"word":"kinsman","structure":"kin + -s- + man","meaning":"a male relative","meaningCN":"男性亲属","example":"A kinsman spoke for the family at the hearing.","exampleCN":"一位男性亲属在听证会上代表家族发言。"},{"word":"kinswoman","structure":"kin + -s- + woman","meaning":"a female relative","meaningCN":"女性亲属","example":"Her kinswoman kept the letters.","exampleCN":"她的女性亲属保存了那些信件。"},{"word":"kindred","structure":"kin + Old English -rǣden 'condition'","meaning":"the whole body of relatives","meaningCN":"全体亲属","example":"The whole kindred came to the funeral.","exampleCN":"全体亲属都来参加了葬礼。"},{"word":"akin","structure":"a- 'of' + kin","meaning":"related by blood; similar in nature","meaningCN":"有血缘关系的；性质相似的","example":"Their humour is akin to ours.","exampleCN":"他们的幽默感与我们的相近。"},{"word":"kind","structure":"Old English cynd (noun), same base as cynn","meaning":"type, sort; nature","meaningCN":"种类；本性","example":"That kind of answer ends the argument.","exampleCN":"那种回答会结束争论。"},{"word":"kindliness","structure":"kindly + -ness","meaning":"warm, generous disposition","meaningCN":"和善慷慨的性情","example":"Her kindliness made the room easy to enter.","exampleCN":"她的和善让那间屋子容易走进去。"}],"latinEntries":[]}},{"word":"kinship system","ipa_uk":"/ˈkɪnʃɪp ˈsɪstəm/","ipa_us":"/ˈkɪnʃɪp ˈsɪstəm/","definition_zh":"亲属制度；亲属称谓体系；婚配与继嗣规则；角色义务的整套安排","definition_en":"the organized set of rules and terms by which a society defines relatives, descent, marriage and mutual duties","core_image":"一张铺开的图表，横向列出称谓，纵向串起世代，边上用箭头标出谁可娶谁。","scene":"一张图表铺在桌上，横向一排称谓，纵向串起世代，边上的箭头标明谁可以与谁成婚。The kinship system of the islanders allows marriage between certain cousins but forbids it between others.","sceneCN":"这里 kinship system 指「一个社会界定亲属、世系、婚姻与相互义务的整套规则与称谓」（第 1 个义项：以称谓为骨架的亲属制度）；句意为岛民的亲属制度允许某些表亲通婚，却禁止另一些。可辨识物件：铺开的图表、称谓栏、世代竖线、箭头、批注。","pos":[{"tag":"n.","zh":"亲属制度；亲属体系"},{"tag":"n.","zh":"（某一社会的）亲属称谓与规则的总和"}],"collocations":[{"phrase":"bilateral kinship system","zh":"双边亲属制度"},{"phrase":"unilineal kinship system","zh":"单系亲属制度"},{"phrase":"kinship system of a society","zh":"某社会的亲属制度"},{"phrase":"classificatory kinship system","zh":"归类式亲属制度"},{"phrase":"change in the kinship system","zh":"亲属制度的变化"}],"forms":[{"label":"单数","form":"kinship system"},{"label":"复数","form":"kinship systems"},{"label":"相关名词（亲属关系）","form":"kinship"},{"label":"相关形容词（制度的）","form":"systemic"},{"label":"相关形容词（体系性的）","form":"systematic"}],"derivatives":[{"word":"system","pos":"n.","zh":"希腊 systēma（组合体）→ 直接保留为「体系、系统」，语义由「拼合在一起的东西」转为「有规则的整套安排」"},{"word":"systematic","pos":"adj.","zh":"system + -atic（形容词后缀）→ 有系统的，语义落在「按规则成体系」"},{"word":"systemic","pos":"adj.","zh":"system + -ic（形容词后缀）→ 整个体系层面的，语义偏重「牵动全局」而非「有条理」"},{"word":"systematize","pos":"v.","zh":"systematic + -ize（动词后缀）→ 使成体系，语义由状态转为动作"},{"word":"kinship","pos":"n.","zh":"kin + -ship（状态后缀）→ 亲属关系，作复合词的前项限定领域"}],"senses":[{"no":"01","title":"A set of kin terms","titleCN":"亲属称谓体系","definition":"the vocabulary a language uses to label relatives, with each label fixing a bundle of duties","definitionCN":"一种语言给亲属命名的词汇系统，每个名称都固定了一束义务","example":"The kinship system distinguishes mother's brother from father's brother.","exampleCN":"这套亲属称谓把母亲的兄弟与父亲的兄弟区分开来。","why":"the first thing a fieldworker records is who is called what, so the term names the labels before it names the rules.","whyCN":"田野工作者最先记录的是谁被称作什么，因此这个术语先指称谓，再指规则。"},{"no":"02","title":"Rules on whom one may marry","titleCN":"婚配规则","definition":"the rules that mark some relatives as marriageable and others as forbidden, including preferred cousin marriage","definitionCN":"规定哪些亲属可婚、哪些禁婚，并包含优先表亲婚配的规则","example":"Their kinship system prefers a marriage between cross-cousins.","exampleCN":"他们的亲属制度偏好姑表亲之间的婚姻。","why":"terms and prohibitions are learned together, so the label for relatives also covers the marriage rules attached to each label.","whyCN":"称谓与禁例是一起学会的，因此亲属的名称也涵盖附着在每个名称上的婚配规则。"},{"no":"03","title":"Rules of descent and inheritance","titleCN":"继嗣与继承规则","definition":"the rules deciding whether name, property and office pass through the father's line, the mother's line or both","definitionCN":"决定名号、财产与职位经父系、母系还是双系传递的规则","example":"A patrilineal kinship system moved the fields to the sons.","exampleCN":"父系亲属制度把田地传给儿子们。","why":"descent is the backbone of the whole arrangement, because it decides which of the recorded relatives actually inherit.","whyCN":"继嗣是整套安排的骨架，因为它决定所记录的亲属中谁真正继承。"},{"no":"04","title":"Rules on where a couple lives","titleCN":"婚后居住规则","definition":"the rule that sends a newly married couple to the husband's village, the wife's village or a new household","definitionCN":"规定新婚夫妇住在夫家村、妻家村还是另立新户的规则","example":"The kinship system is uxorilocal, so the groom moves to her house.","exampleCN":"这套亲属制度是妻家居住制，因此新郎搬进她的屋子。","why":"residence decides which relatives a child grows up beside, so it is read as part of the same system.","whyCN":"居住地决定孩子与哪些亲属一起长大，因此它被看作同一体系的一部分。"},{"no":"05","title":"Allocation of roles and duties","titleCN":"角色与义务的分配","definition":"the assignment of who feeds, shelters, disciplines and buries whom, and who may speak for the family","definitionCN":"规定谁供养、收留、管教、安葬谁，以及谁可代表家族发言","example":"Under this kinship system, a mother's brother trains the boys.","exampleCN":"在这套亲属制度下，由母亲的兄弟负责训练男孩。","why":"labels are empty without duties, so the system also names the work each relative owes.","whyCN":"没有义务，称谓就是空的，因此这套体系也规定了每位亲属该承担的工作。"},{"no":"06","title":"A comparative research model","titleCN":"用于比较研究的分析模型","definition":"an abstract model that lets anthropologists compare how different societies organize relatives","definitionCN":"让人类学家比较不同社会如何组织亲属的抽象模型","example":"The textbook treats every kinship system as a set of testable rules.","exampleCN":"教科书把每一种亲属制度当作一套可检验的规则。","why":"once the word is used in the plural for many societies, it becomes a unit of comparison rather than a local fact.","whyCN":"一旦这个词以复数形式用于众多社会，它就成了比较的单位，而非本地事实。"},{"no":"07","title":"The official legal framework","titleCN":"法律与行政上的正式框架","definition":"the framework a state uses to decide next of kin, guardianship and inheritance claims","definitionCN":"国家用来认定近亲、监护资格与继承主张的框架","example":"The court applied the statutory kinship system, not local custom.","exampleCN":"法院适用法定亲属制度，而不是地方习俗。","why":"the state needs one fixed table of who counts as next of kin, so the anthropological word is borrowed for law.","whyCN":"国家需要一张固定的近亲认定表，于是人类学的词被借到法律里。"},{"no":"08","title":"Any rule-governed classification","titleCN":"抽象义：任何按规则组织的分类体系","definition":"any arrangement that sorts people into named categories and attaches rights and duties to each category","definitionCN":"任何把人分进有名称的类别、并给每类附加权利与义务的安排","example":"The guild's kinship system was a ladder of apprentices, journeymen and masters.","exampleCN":"行会的「亲属式」体系是一道学徒、帮工与师傅的阶梯。","why":"the abstract sense keeps only the machinery: names, categories and inherited positions, with no family involved.","whyCN":"抽象义只保留机械结构：名称、类别与承袭的位置，与家庭无关。"}],"etymology":{"intro":{"en":"The phrase joins kinship, from Old English cynn 'family', to system, from late Latin systema and Greek systēma 'a composite whole'. Neither half is Latin-native to the other; the compound itself is a modern coinage.","cn":"这个短语把 kinship（出自古英语 cynn「家族」）与 system（出自晚期拉丁 systema、希腊 systēma「组合的整体」）并置。两半并非同出一源；整个复合词是近代造语。"},"items":[{"era":"GREEK SYN-","en":"Greek syn- 'together, with' is the prefix of systēma; it marks things placed as one.","cn":"希腊语 syn-「一起、与」是 systēma 的前缀，标记被并置为一的东西。"},{"era":"GREEK HISTANAI","en":"Histanai 'to make stand, to place' is the verb behind the second half; the whole noun pictures parts set standing together.","cn":"histanai「使立起、放置」是后半部分的动词；整个名词的意象是把各部分立在一起。"},{"era":"GREEK SYSTĒMA","en":"Systēma meant 'a composite whole, an organized body'; it was used for bodies of troops and of theory alike.","cn":"systēma 意为「组合的整体、有组织的团体」，既用于军队编制，也用于理论体系。"},{"era":"LATIN SYSTEMA","en":"Late Latin took systema from Greek unchanged in sense; English received it through learned writing, not through speech.","cn":"晚期拉丁语把 systema 连义带形借入；英语是通过学术书写、而非口语得到它的。"},{"era":"ENGLISH SYSTEM","en":"English system first named the ordered arrangement of the heavens and the body, then any set of connected parts.","cn":"英语 system 先指天体与身体的有序安排，后指任何由相互关联部分组成的集合。"},{"era":"MODERN COMPOUND","en":"Placing kinship before system belongs to nineteenth-century anthropology; the exact first use is source uncertain, and the earliest citations are not agreed.","cn":"把 kinship 放在 system 之前属 19 世纪人类学的做法；确切的首见来源不确定，最早书证也无定说。"}]},"similar":{"note":{"en":"Group one holds forms built on the same system root that are routinely confused; group two holds narrower or broader labels often used in place of the full phrase.","cn":"第一组是同出 system 词根、常被混用的形式；第二组是常被用来代替完整短语的较窄或较宽标签。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"systematic","ipa":"/ˌsɪstəˈmætɪk/","tag":"same root, method sense","definition":"Done according to a plan or method; it describes a careful procedure, not a structure of related parts.","definitionCN":"按计划或方法做的；描述细心的程序，而非由相关部分构成的结构。"},{"word":"systemic","ipa":"/sɪˈstemɪk/","tag":"same root, whole-body sense","definition":"Belonging to the whole system rather than one part; in medicine it means affecting the entire body.","definitionCN":"属于整个体系而非某一部分；在医学中指影响全身。"},{"word":"systole","ipa":"/ˈsɪstəli/","tag":"different root","definition":"The heart's contraction, from Greek systolē built on stellein 'to send, contract'; the syn- prefix is shared, the verb is not.","definitionCN":"心脏收缩，来自希腊语 systolē，由 stellein「送出、收缩」构成；前缀 syn- 相同，动词却不同源。"},{"word":"system","ipa":"/ˈsɪstəm/","tag":"base word, wider scope","definition":"Any set of connected parts; on its own it says nothing about relatives, which is what the first element adds.","definitionCN":"任何由相互关联部分构成的集合；单独使用时与亲属无关，亲属这一层由前项补上。"}]},{"heading":"NEAR MEANING","entries":[{"word":"kinship terms","ipa":"/ˈkɪnʃɪp tɜːmz/","tag":"vocabulary only","definition":"Just the labels for relatives; the full system also includes marriage, descent, residence and duties.","definitionCN":"只指亲属的名称标签；完整制度还包括婚配、继嗣、居住与义务。"},{"word":"family law","ipa":"/ˈfæmɪli lɔː/","tag":"legal subset","definition":"The statutes governing marriage, guardianship and inheritance; it is one official slice of a kinship system.","definitionCN":"管辖婚姻、监护与继承的成文法；它是亲属制度中官方的一部分。"},{"word":"social organization","ipa":"/ˈsəʊʃl ˌɔːɡənaɪˈzeɪʃn/","tag":"broader umbrella","definition":"The whole ordering of a society, including but not limited to its rules about relatives.","definitionCN":"一个社会的整体秩序，包含却不限于其关于亲属的规则。"},{"word":"household system","ipa":"/ˈhaʊshəʊld ˈsɪstəm/","tag":"domestic unit","definition":"Who lives under one roof and shares work; a kinship system may span many households and is not the same unit.","definitionCN":"指同住一屋、共担劳作的人；亲属制度可跨许多户，并不是同一个单位。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real words joined, the Greek verb inside system, and the vocabulary anthropologists actually use.","cn":"正常联想：两个真词并置、system 内部的希腊动词，以及人类学者实际使用的术语。"},"normal":[{"en":"kin + -ship + system: relatives, their relation, and the rules holding the relation in place.","cn":"kin 加 -ship 再加 system：亲属、亲属关系，以及把关系固定下来的规则。"},{"en":"Greek syn- 'together' + histanai 'place': parts placed together into one standing whole.","cn":"希腊语 syn-「一起」加 histanai「放置」：各部分被并置成一个立住的整体。"},{"en":"Anthropology's standard contrast is bilateral versus unilineal systems.","cn":"人类学的标准对照是双边制与单系制。"},{"en":"The fixed phrase 'classificatory kinship system' marks the type that merges several relatives under one term.","cn":"固定搭配「归类式亲属制度」指把数位亲属并入同一称谓的类型。"},{"en":"Descent, marriage and residence are the three questions every such system answers.","cn":"继嗣、婚姻与居住是每一套这类制度都要回答的三个问题。"}],"abstract":[{"en":"Picture a chart where every name carries a small list of jobs attached to it.","cn":"想象一张图表，每个名称后面都挂着一小串该做的事。"},{"en":"Picture a door that opens for one cousin and stays shut for another.","cn":"想象一扇门，对一位表亲敞开，对另一位却关着。"},{"en":"Picture a society handing its property down a single column while ignoring the other column.","cn":"想象一个社会只沿一列把财产往下传，另一列则被略过。"}]},"examples":[{"en":"The kinship system changed once women began inheriting land.","cn":"一旦女性开始继承土地，这套亲属制度就变了。"},{"en":"A kinship system is not a list of names but a set of claims people can make.","cn":"亲属制度不是一串名字，而是一组人们可以提出的权利主张。"},{"en":"Missionaries misunderstood the kinship system and banned the wrong marriage.","cn":"传教士误解了这套亲属制度，禁错了婚事。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「亲系统」：亲属关系被排成一套有开关的机器，谁进谁出一按便知 → 亲属称谓、婚配与继嗣规则","word":"kinship system"},"root":"kinship（古英语 cynn「家族」+ -ship）+ system（晚期拉丁 systema < 希腊 systēma，syn-「一起」+ histanai「放置」）；复合词为近代人类学造语。","sensesIntro":{"en":"Eight senses build one machine from its parts: the names, the marriage gate, the descent line, the residence rule, the duties, the comparative model, the legal version and finally any classification that works the same way.","cn":"八个义项把一台机器逐件装起：称谓、婚姻闸门、继嗣线、居住规则、义务、比较模型、法律版本，最后是任何按同样方式运作的分类。"},"semanticMap":{"core":{"en":"CORE IMAGE: a chart of names, lines and arrows that tells each relative what to do.","cn":"核心意象：一张由名称、线条与箭头构成的图表，规定每位亲属该做什么。"},"chain":["NAME THE RELATIVE","OPEN OR CLOSE MARRIAGE","DRAW THE DESCENT LINE","FIX THE RESIDENCE","ASSIGN THE DUTY","COMPARE THE MODELS"],"branches":[{"senses":"01 · 05","en":"NAME AND DUTY: every label is a post with work attached, not a bare word.","cn":"名称与义务：每个称谓都是一个带工作的岗位，而非空词。"},{"senses":"02","en":"THE MARRIAGE GATE: who may pair with whom, and which cousin is refused.","cn":"婚姻闸门：谁可与谁结合，哪一位表亲被拒绝。"},{"senses":"03 · 04","en":"LINE AND HOUSE: property follows a column, and the couple sleeps in a chosen village.","cn":"世系与居所：财产沿一列传递，夫妇睡在被选定的村子。"},{"senses":"06 · 07","en":"MODEL AND STATUTE: the same rules are read as a research unit and as law.","cn":"模型与法规：同一套规则既被读作研究单位，也被读作法律。"},{"senses":"08","en":"THE MACHINE ALONE: strip out relatives and any rule-bound sorting remains.","cn":"只剩机器：抽走亲属，任何按规则归类的做法都还留着。"}]},"affixes":{"intro":{"en":"The phrase has two buildable halves, and each half brings its own small family of forms.","cn":"这个短语两半都可拆解，每一半都带来自己的小型词族。"},"latinIntro":{"en":"The Latin element is systema, late Latin for the Greek systēma; the Latin family here is small, and the Greek source form is listed beside it for clarity.","cn":"拉丁语一端是 systema，即希腊语 systēma 的晚期拉丁形式；此处的拉丁词族很小，为清楚起见把希腊语源形式一并列出。"},"items":[{"word":"kinship","structure":"kin + -ship","meaning":"the state of being related","meaningCN":"亲属关系的状态","example":"Kinship decides who may speak for the family.","exampleCN":"亲属关系决定谁可代表家族发言。"},{"word":"system","structure":"late Latin systema < Greek systēma","meaning":"an organized whole of connected parts","meaningCN":"由相互关联部分构成的有序整体","example":"The system explains more than any single rule.","exampleCN":"这套体系比任何单条规则解释得更多。"},{"word":"-atic","structure":"-aticus (adjectival ending, through Latin and French)","meaning":"relating to a method","meaningCN":"与某种方法有关的","example":"System plus -atic yields systematic.","exampleCN":"system 加 -atic 得出 systematic。"},{"word":"systematic","structure":"system + -atic","meaning":"done by a fixed method","meaningCN":"按固定方法做的","example":"The survey was systematic, village by village.","exampleCN":"这次调查是系统性的，逐村进行。"},{"word":"systemic","structure":"system + -ic","meaning":"affecting the whole system","meaningCN":"影响整个体系的","example":"The shortage was systemic, not accidental.","exampleCN":"这种短缺是体系性的，不是偶然的。"},{"word":"systematize","structure":"systematic + -ize","meaning":"to arrange into a system","meaningCN":"使排列成体系","example":"They systematized the records by generation.","exampleCN":"他们按世代把记录整理成体系。"},{"word":"kinship system","structure":"kinship + system (noun compound)","meaning":"the rules and terms organizing relatives","meaningCN":"组织亲属关系的规则与称谓","example":"The kinship system survived the change of religion.","exampleCN":"这套亲属制度在宗教更替后仍延续。"},{"word":"systematization","structure":"systematize + -ation","meaning":"the act of arranging into a system","meaningCN":"把事物整理成体系的行为","example":"Systematization of the archives took a decade.","exampleCN":"档案的系统化整理花了十年。"},{"word":"-ize","structure":"-izare (verb suffix, through French from Greek)","meaning":"to make or become","meaningCN":"使成为；变成","example":"Systematic plus -ize yields systematize.","exampleCN":"systematic 加 -ize 得出 systematize。"},{"word":"-ation","structure":"-atio (Latin noun suffix)","meaning":"the act or result of","meaningCN":"行为或结果","example":"Systematize plus -ation yields systematization.","exampleCN":"systematize 加 -ation 得出 systematization。"}],"latinEntries":[{"word":"systema","structure":"systema, systematis (n., third declension, late Latin from Greek)","meaning":"an organized whole","meaningCN":"有组织的整体"},{"word":"systēma","structure":"systēma, systēmatos (Greek noun, third declension; source of Latin systema)","meaning":"composite body, organized whole","meaningCN":"组合体；有组织的整体"},{"word":"systematicus","structure":"systematicus, systematica, systematicum (late Latin adjective)","meaning":"of a system, methodical","meaningCN":"体系的；有条理的"}]}},{"word":"lineage system","ipa_uk":"/ˈlɪniɪdʒ ˈsɪstəm/","ipa_us":"/ˈlɪniɪdʒ ˈsɪstəm/","definition_zh":"继嗣制度；世系体系；谱系记录体系；以世系为单位的组织方式","definition_en":"the set of rules and records by which a society reckons descent and places each person in a line of ancestors","core_image":"一卷摊开的族谱把一个个名字连成向下的枝条，每根枝条的末端都站着一个活人。","scene":"祠堂的长桌上摊开一卷族谱，长老用炭笔在名字旁添上记号，说明这一代该归入哪一支。The lineage system decides which clan a newborn belongs to.","sceneCN":"这里 lineage system 指「一个社会用来判定成员归属哪一支世系的继嗣规则」（第 1 个义项：按出生确定归属的成套规则）；句意为这套继嗣制度决定新生儿归入哪一个氏族。可辨识物件：长桌、摊开的族谱、炭笔、名字旁的记号、围坐的年轻人。","pos":[{"tag":"n.","zh":"继嗣制度；世系体系；谱系记录体系（可数，指某一套具体规则）"}],"collocations":[{"phrase":"patrilineal lineage system","zh":"父系继嗣制度"},{"phrase":"matrilineal lineage system","zh":"母系继嗣制度"},{"phrase":"unilineal lineage system","zh":"单系继嗣制度"},{"phrase":"a rigid lineage system","zh":"僵硬的世系制度"},{"phrase":"lineage system and marriage rules","zh":"继嗣制度与婚姻规则"},{"phrase":"trace a lineage system","zh":"追溯一套世系体系"}],"forms":[{"label":"单数（短语整体）","form":"lineage system"},{"label":"复数（短语整体）","form":"lineage systems"},{"label":"名词（世系；血统）","form":"lineage"},{"label":"名词复数（世系）","form":"lineages"},{"label":"形容词（直系的；世系的）","form":"lineal"},{"label":"副词（按直系地）","form":"lineally"}],"derivatives":[{"word":"lineage","pos":"n.","zh":"line + -age（古法语名词后缀）→ 由「线」转为「世系、血统」，指一条祖辈连成的线"},{"word":"lineal","pos":"adj.","zh":"lineage 的词干加 -al（拉丁形容词后缀）→ 由「世系」转为「直系的、按世系的」"},{"word":"lineally","pos":"adv.","zh":"lineal + -ly（英语副词后缀）→ 由形容词转为副词，指按直系的方式"},{"word":"line","pos":"n./v.","zh":"拉丁 linea「线」经古法语 ligne 进入英语 → 保留最朴素的「线、行」，也指家族的一支"},{"word":"collineal","pos":"adj.","zh":"col-（共同）加 lineal → 由「直系」转为「同属一支世系的」"}],"senses":[{"no":"01","title":"Rules that fix a person's descent","titleCN":"判定一个人世系归属的规则","definition":"the body of rules a society uses to trace a person's descent from known ancestors","definitionCN":"一个社会用来把某人的血统追溯到已知祖先的整套规则","example":"Each village applies its own lineage system when a child is named.","exampleCN":"每个村落在给孩子命名时都施行自己的一套继嗣规则。","why":"lineage is Latin linea 'line' plus -age, a line drawn through ancestors, and system is a set of parts placed together, so the phrase names rules arranged into a whole.","whyCN":"lineage 是拉丁 linea「线」加 -age，指穿过祖先画出的一条线；system 指被放在一起的一整套部分，因此这个短语指排列成整体的规则。"},{"no":"02","title":"Descent through one parent only","titleCN":"只经父或母一方计算血统","definition":"a rule that reckons descent through a single parent, either the father or the mother, and excludes the other line","definitionCN":"只经父亲或母亲一方计算血统、排除另一方那条线的规则","example":"A patrilineal lineage system passes the family name through the father alone.","exampleCN":"父系继嗣制度只让姓氏沿父亲一线传下去。","why":"once descent is drawn as one line, the rule must say which parent supplies it, and the choice produces the unilineal form.","whyCN":"一旦把血统画成一条线，规则就必须说明由哪一位家长提供这条线，这个选择就产生了单系形态。"},{"no":"03","title":"The recorded roll of ancestors","titleCN":"写下来或口传的祖先名录","definition":"the written or recited record of ancestors and the links between them","definitionCN":"以书写或背诵方式留存的祖先名录及其相互连接","example":"The lineage system is recited at funerals so that no name is dropped.","exampleCN":"族谱在葬礼上被逐一背诵，以免漏掉任何一个名字。","why":"a line that is not remembered cannot be used, so record keeping becomes the memory of the rule itself.","whyCN":"一条不被记住的线无法使用，因此保存记录就成了规则本身的记忆。"},{"no":"04","title":"Goods and rights passing down the line","titleCN":"财产与权利沿世系下传","definition":"the arrangement by which property, titles and rights pass from one generation of a line to the next","definitionCN":"财产、名号与权利沿一条世系由上一代传到下一代的安排","example":"Under this lineage system, the orchards go to the eldest son of the senior branch.","exampleCN":"按这套继嗣制度，果园归长支的长子所有。","why":"property follows the same line that names the heir, so inheritance is the economic face of descent.","whyCN":"财产沿着给继承人命名的那条线走，因此继承是世系的经济面孔。"},{"no":"05","title":"A descent group acting as a political body","titleCN":"作为政治单位行动的世系群体","definition":"a group of kin descended from one ancestor that holds land, settles disputes and speaks for its members","definitionCN":"同出一位祖先、共同持有土地、裁断纠纷并代表其成员的亲属群体","example":"The lineage system settles boundary quarrels without any court.","exampleCN":"这套世系体系不用任何法庭就能裁断地界纠纷。","why":"a line of kin that owns land together and answers for its members turns a family record into a unit of government.","whyCN":"一条共同持有土地、并为成员作担保的亲属线，把家族记录变成了治理单位。"},{"no":"06","title":"One family's actual ancestry","titleCN":"某一家庭实际的血统线","definition":"the particular chain of ancestors that a family claims and can name","definitionCN":"某个家庭所主张、并能逐一称说的那条具体祖先链","example":"Her lineage system reaches back to a family of salt traders.","exampleCN":"她的世系可以上溯到一个盐商家族。","why":"the abstract rule also names the concrete thread it is applied to, so one family's ancestry is called its lineage system too.","whyCN":"抽象规则也用来指它所施用的具体那条线，因此一个家庭的血统线也被称作它的世系。"},{"no":"07","title":"Any chain handed down between generations","titleCN":"抽象义：代际传递的任何链条","definition":"any chain in which a skill, quality or right is passed from one generation to the next","definitionCN":"技艺、品质或权利由一代传到下一代的任何链条","example":"The workshop's lineage system of apprenticeship kept the craft alive.","exampleCN":"作坊里师徒相承的传承链让这门手艺活了下来。","why":"the abstract sense keeps only the shape of descent: a line of predecessors, each handing something to the next.","whyCN":"抽象义只保留了世系的形状：一条先辈的线，每一位把某物交给下一位。"},{"no":"08","title":"A model for comparing societies","titleCN":"人类学中用于比较社会的模型","definition":"an analytic model that compares how different societies reckon descent and place members in groups","definitionCN":"比较不同社会如何计算血统、如何把成员放入群体的分析模型","example":"The textbook treats the lineage system as one of four basic models.","exampleCN":"教科书把世系体系视为四种基本模型之一。","why":"researchers needed a neutral label for local rules, so they took the older phrase and turned it into a category for comparison.","whyCN":"研究者需要为地方规则找一个中性标签，于是取来旧短语，把它改造成可供比较的类别。"}],"etymology":{"intro":{"en":"Lineage comes from Old French lignage, from Latin linea 'line', and linea itself from linum 'flax'. System comes from Late Latin systema, from Greek systēma, built on syn- 'together' and histanai 'to place'. Dates are approximate.","cn":"lineage 来自古法语 lignage，出自拉丁 linea「线」，而 linea 又出自 linum「亚麻」。system 来自晚期拉丁 systema，出自希腊 systēma，由 syn-「一起」与 histanai「放置」构成。年代均为约数。"},"items":[{"era":"LATIN LINUM","en":"Linum meant 'flax', the plant whose stalks were spun into thread. Its earlier origin is source uncertain, and any Indo-European form offered for it is a reconstruction.","cn":"linum 意为「亚麻」，这种植物的茎被纺成线。其更早来源不确定，凡为其给出的印欧形式均属重构形式。"},{"era":"LATIN LINEA","en":"Linea 'line, thread' was formed on linum, so the word for a drawn line began as the word for a flaxen thread. The step from thread to line is generally regarded as established.","cn":"linea「线、细绳」由 linum 构成，因此指画出的线，起初指的是亚麻线。由「细绳」到「线」这一步一般认为成立。"},{"era":"OLD FRENCH LIGNAGE","en":"Old French lignage added -age to ligne 'line' and shifted the sense from a drawn line to a line of people, that is, a group of common descent.","cn":"古法语 lignage 在 ligne「线」上加 -age，语义由画出的线转为一条人的线，即同出一源的群体。"},{"era":"FRENCH SUFFIX -AGE","en":"The suffix -age, from Latin -aticum, forms nouns of state, action or collection; applied here, it turned 'line' into 'descent'.","cn":"后缀 -age 出自拉丁 -aticum，构成表状态、动作或集合的名词；用在此处，它把「线」变成了「世系」。"},{"era":"GREEK SYSTEMA","en":"Greek systēma meant 'a whole put together', from syn- 'together' and histanai 'to place, stand'. The deeper origin of histanai is generally regarded as a root meaning 'to stand', but that form is a reconstruction.","cn":"希腊 systēma 意为「组合起来的整体」，由 syn-「一起」与 histanai「放置、站立」构成。histanai 的更深来源一般认为是一个意为「站立」的词根，但该形式属重构形式。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the compound lineage system is a modern label in anthropology, no agreed first citation is recorded, and the pre-Latin shapes of linum and histanai remain reconstructions.","cn":"来源不确定：lineage system 是人类学中的近代标签，最早书证并无定说；linum 与 histanai 在拉丁语、希腊语之前的形式仍属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms built on the same line stock that are easily mistaken for the whole phrase; group two holds neighbouring terms for descent that differ in scope.","cn":"第一组是同出「线」词干、容易被当成整个短语的词；第二组是范围不同的邻近继嗣术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"lineage","ipa":"/ˈlɪniɪdʒ/","tag":"same root, noun alone","definition":"The noun for a line of ancestors; it names the line itself, while the full phrase names the rules and records built on that line.","definitionCN":"指祖先连成的那条线本身；完整短语则指建立在这条线上的规则与记录。"},{"word":"lineal","ipa":"/ˈlɪniəl/","tag":"same root, adjective","definition":"Built on line with -al, it describes a person in the direct line, as in a lineal heir; it never names a system of rules.","definitionCN":"由 line 加 -al 构成，形容处于直系的人，如直系继承人；它从不指一套规则体系。"},{"word":"line","ipa":"/laɪn/","tag":"same root, plain word","definition":"The basic noun for a thread, a row or a branch of a family; most of its everyday senses have nothing to do with descent.","definitionCN":"指线、行或家族一支的基本名词；它大多数日常义与血统无关。"},{"word":"linage","ipa":"/ˈlaɪnɪdʒ/","tag":"homophone, different branch","definition":"Spelled with one n fewer than lineage, it means the number of lines on a page or payment by the line, from line 'row of type' plus -age; despite the shared sound it has no link to ancestors.","definitionCN":"比 lineage 少一个 n，意为版面上行数或按行计酬，来自 line「一行字」加 -age；尽管读音相同，它与祖先毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"descent","ipa":"/dɪˈsent/","tag":"the principle in the abstract","definition":"The general principle by which a person is connected to ancestors; a lineage system is the organized rules plus the records that apply it.","definitionCN":"指人如何与祖先相连的一般原则；lineage system 则是施用这一原则的成套规则加上记录。"},{"word":"kinship system","ipa":"/ˈkɪnʃɪp ˈsɪstəm/","tag":"wider network","definition":"The whole network of blood and marriage ties in a society; a lineage system is one narrow, rule-bound part of that network.","definitionCN":"一个社会中血亲与姻亲关系的整个网络；lineage system 只是其中窄小且有规则约束的一部分。"},{"word":"clan system","ipa":"/ˈklæn ˈsɪstəm/","tag":"the group, not the rule","definition":"It stresses the clan as a body of people; a lineage system stresses how membership in that body is reckoned and recorded.","definitionCN":"强调氏族作为一个人的团体；lineage system 强调如何计算并记录成员资格。"},{"word":"genealogy","ipa":"/dʒiːˈælədʒi/","tag":"the record and the study","definition":"The tracing and recording of ancestors, and the study of such traces; the lineage system is the social rule that makes the tracing necessary.","definitionCN":"指对祖先的追溯与记录，以及对此的研究；lineage system 是使这种追溯成为必要的社会规则。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"linea 'line' plus -age: a family drawn as one long line.","cn":"linea「线」加 -age：把一个家族画成一条长线。"},{"en":"system is Greek syn- 'together' plus histanai 'to place': rules placed together into a whole.","cn":"system 是希腊 syn-「一起」加 histanai「放置」：规则被放在一起成为整体。"},{"en":"The family runs line, lineage, lineal, lineally and lineage system.","cn":"同族词包括 line、lineage、lineal、lineally 与 lineage system。"},{"en":"Fixed phrases mark the types: patrilineal, matrilineal and unilineal lineage system.","cn":"固定搭配标出类型：父系、母系与单系继嗣制度。"},{"en":"Anthropology pairs it with kinship system: one narrow rule inside a wider net.","cn":"人类学把它与亲属体系并列：宽大网络里的一条窄规则。"}],"abstract":[{"en":"Picture a family tree drawn on cloth, with one straight thread running from the first name to a newborn.","cn":"想象一棵画在布上的家族树，一条直直的线从最初的名字一直连到新生儿。"},{"en":"Picture a rulebook so old that its pages are read aloud at funerals rather than opened.","cn":"想象一本旧得不再翻开的规则册，只在葬礼上被高声背诵。"},{"en":"Picture a craft passed from hand to hand along a line of teachers, with no blood relation at all.","cn":"想象一门手艺沿一列师父的手传下去，彼此完全没有血缘。"}]},"examples":[{"en":"Missionaries misunderstood the lineage system because they assumed descent ran through both parents.","cn":"传教士误解了这套继嗣制度，因为他们以为血统同时经父母双方计算。"},{"en":"Where land is scarce, the lineage system usually becomes stricter about who may inherit.","cn":"在土地稀少之处，继嗣制度对谁可以继承通常变得更为严格。"},{"en":"The archive holds a lineage system written on bamboo slips more than two thousand years old.","cn":"档案馆藏有一套写在两千多年前竹简上的世系记录。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「line（线）+ age（世代）+ system（体系）」——把家族画成一条线，再配上规则 → 继嗣制度、世系体系","word":"lineage system"},"root":"拉丁 linum「亚麻」→ linea「线」→ 古法语 lignage（ligne + -age，语义转为世系）；希腊 syn-「一起」+ histanai「放置」→ systēma → 晚期拉丁 systema → 英语 system。英语 lineage system。","sensesIntro":{"en":"Eight senses follow one line: a rule fixes descent, the rule picks a single parent, the line is recorded, property follows it, the kin group acts politically, one family claims it, and then the same shape is read as any chain of handing down and finally as a model.","cn":"八个义项沿一条线展开：规则先定下血统，规则再选定一方家长，这条线被记录，财产沿它下传，亲属群体据此行事，某个家庭认领它，随后同一形状被读作任何传递链，最后被读作一个模型。"},"semanticMap":{"core":{"en":"CORE IMAGE: a written line of names that tells each living person where to stand.","cn":"核心意象：一条写下来的名字之线，告诉每个活人该站在哪里。"},"chain":["FIX DESCENT","CHOOSE ONE PARENT","RECORD THE LINE","PASS PROPERTY","ACT AS A BODY","MODEL THE RULE"],"branches":[{"senses":"01 · 02","en":"THE RULE: descent must be traced, and a single line must be chosen.","cn":"规则：血统必须被追溯，而且必须选定单独一条线。"},{"senses":"03 · 04","en":"THE LINE ON PAPER AND IN LAW: a record keeps the names, and property follows them.","cn":"纸上的线与法上的线：记录保住名字，财产沿名字走。"},{"senses":"05 · 06","en":"THE GROUP AND THE FAMILY: the same line can govern a village or name one household's ancestry.","cn":"群体与家庭：同一条线可以治理一个村落，也可以指一个家庭的血统。"},{"senses":"07","en":"THE CHAIN WITHOUT KIN: only the shape of handing down survives the loss of blood relation.","cn":"去掉亲属的链条：失去血缘后，只剩传递的形状。"},{"senses":"08","en":"THE MODEL: local rules are abstracted into a category for comparison.","cn":"模型：地方规则被抽象成一个可供比较的类别。"}]},"affixes":{"intro":{"en":"The phrase is built from two independent word families, a Latin line stock with a French suffix and a Greek whole assembled from a prefix and a verb.","cn":"这个短语由两个独立的词族构成：一个带法语后缀的拉丁「线」词族，以及一个由前缀与动词拼合的希腊「整体」词。"},"latinIntro":{"en":"Latin linum gives linea, and Old French turns linea's descendant into lignage; Latin systema, borrowed from Greek, supplies the second word.","cn":"拉丁 linum 衍生 linea，古法语又把 linea 的后代变成 lignage；第二词则来自借入拉丁语的希腊 systēma。"},"items":[{"word":"linum","structure":"linum, lini (Latin noun, neuter, second declension)","meaning":"flax","meaningCN":"亚麻","example":"The plant gave its name to the thread spun from it.","exampleCN":"这种植物把名字给了由它纺出的线。"},{"word":"linea","structure":"linea, lineae (Latin noun, feminine, first declension)","meaning":"a line, a thread","meaningCN":"线；细绳","example":"Linea was formed on the flax word and named anything drawn straight.","exampleCN":"linea 在「亚麻」这个词上构成，用来指任何画直的东西。"},{"word":"lineage","structure":"Old French lignage, from ligne + -age","meaning":"descent, family line","meaningCN":"世系；家族血统","example":"Old French lignage turned the thread into a family line.","exampleCN":"古法语 lignage 把「线」变成了家族的一条线。"},{"word":"-age","structure":"-age (French noun suffix, from Latin -aticum)","meaning":"state, action or collection","meaningCN":"状态、动作或集合","example":"The suffix turned a noun of thread into a noun of descent.","exampleCN":"这个后缀把「线」的名词变成「世系」的名词。"},{"word":"line","structure":"line (English noun, from Latin linea through French)","meaning":"a cord, a row, a family branch","meaningCN":"线；行；家族的一支","example":"English keeps the plain noun line beside the longer lineage.","exampleCN":"英语在较长的 lineage 之外保留了朴素的 line。"},{"word":"lineal","structure":"line + -al","meaning":"of a direct line of descent","meaningCN":"直系的；世系的","example":"Lineal heirs stand in the direct line.","exampleCN":"直系继承人处在直接的一支上。"},{"word":"system","structure":"systema (Late Latin) from systēma (Greek)","meaning":"an organized whole","meaningCN":"有组织的整体","example":"The second half of the phrase names the whole arrangement.","exampleCN":"短语的后半部分指整套安排。"},{"word":"systema","structure":"systema, systematis (Late Latin noun, neuter, third declension)","meaning":"a whole made of parts","meaningCN":"由部分构成的整体","example":"Late Latin systema carried the Greek word into learned English.","exampleCN":"晚期拉丁 systema 把这个希腊词带入学术英语。"},{"word":"syn-","structure":"syn- (Greek prefix)","meaning":"together, with","meaningCN":"一起；共同","example":"The prefix marks parts placed together.","exampleCN":"这个前缀标记被放在一起的部分。"},{"word":"histanai","structure":"histanai (Greek verb)","meaning":"to place, to stand","meaningCN":"放置；使站立","example":"The Greek verb supplies the placing inside systēma.","exampleCN":"这个希腊动词为 systēma 提供了「放置」的意思。"}],"latinEntries":[{"word":"linum","structure":"linum, lini (n., second declension)","meaning":"flax","meaningCN":"亚麻"},{"word":"linea","structure":"linea, lineae (f., first declension)","meaning":"line, thread","meaningCN":"线；细绳"},{"word":"systema","structure":"systema, systematis (n., third declension)","meaning":"a whole made of parts","meaningCN":"由部分构成的整体"}]}},{"word":"social structure","ipa_uk":"/ˈsəʊʃəl ˈstrʌktʃə/","ipa_us":"/ˈsoʊʃəl ˈstrʌktʃər/","definition_zh":"社会结构；社会分层格局；群体间持久关系的总体安排；社会学中约束行动的格局","definition_en":"the overall arrangement of institutions, roles and ranked groups that shapes how people in a society relate to one another","core_image":"一张摊开的村落地图，田块、祠堂、集市与水渠各归其位，人的位置被这些格子预先定好。","scene":"村口的地图钉在木板上，田块、祠堂、集市和水渠分列其上，谁在何处做事一目了然。The social structure of the valley shows in its shared fields, shrines and market days.","sceneCN":"这里 social structure 指「一个社会中制度与角色的总体安排」（第 1 个义项：各类制度与角色被摆在一起的整体格局）；句意为这道山谷的社会结构体现在共耕的田、祠堂与赶集日之中。可辨识物件：钉在木板上的地图、田块、祠堂、集市摊位、水渠。","pos":[{"tag":"n.","zh":"社会结构；社会格局（可数，指某一社会的具体结构）"}],"collocations":[{"phrase":"the existing social structure","zh":"现有的社会结构"},{"phrase":"a rigid social structure","zh":"僵化的社会结构"},{"phrase":"change the social structure","zh":"改变社会结构"},{"phrase":"analyse social structure","zh":"分析社会结构"},{"phrase":"social structure and culture","zh":"社会结构与文化"},{"phrase":"the social structure of a village","zh":"一个村落的社会结构"}],"forms":[{"label":"单数（短语整体）","form":"social structure"},{"label":"复数（短语整体）","form":"social structures"},{"label":"形容词（社会的）","form":"social"},{"label":"名词（结构）","form":"structure"},{"label":"形容词（结构上的）","form":"structural"},{"label":"副词（从结构上）","form":"structurally"},{"label":"名词复数（结构）","form":"structures"}],"derivatives":[{"word":"socialize","pos":"v.","zh":"social + -ize（动词后缀）→ 由「社会的」转为「使社会化、与人交往」"},{"word":"societal","pos":"adj.","zh":"society + -al（形容词后缀）→ 由「社会」转为「社会层面的」，比 social 更书面"},{"word":"structural","pos":"adj.","zh":"structure + -al（拉丁形容词后缀）→ 由「结构」转为「结构上的」"},{"word":"structurally","pos":"adv.","zh":"structural + -ly（副词后缀）→ 由形容词转为副词，指从结构上看"},{"word":"structured","pos":"adj.","zh":"structure + -ed（分词形容词后缀）→ 由「结构」转为「有结构的、安排有序的」"}],"senses":[{"no":"01","title":"The overall arrangement of institutions and roles","titleCN":"制度与角色的总体安排","definition":"the way a society arranges its institutions, roles and positions taken together as one whole","definitionCN":"一个社会把制度、角色与位置合在一起加以安排的方式","example":"The social structure of the valley shows in its shared fields, shrines and market days.","exampleCN":"这道山谷的社会结构体现在共耕的田、祠堂与赶集日之中。","why":"structure is Latin structura, a building or arrangement, from struere 'to build up', so the phrase names the way a society is put together.","whyCN":"structure 是拉丁 structura，指建造或安排，出自 struere「堆叠建造」，因此这个短语指社会被搭起来的方式。"},{"no":"02","title":"The pattern of classes and ranks","titleCN":"阶级与等级的分层格局","definition":"the ranking of people into classes or strata that stand above and below one another","definitionCN":"把人排成一层层高于或低于彼此的阶级或阶层","example":"A mining town often keeps the social structure of the company that built it.","exampleCN":"矿业城镇常保留着当初建镇公司的社会分层格局。","why":"building up is also building over: the same image describes layers stacked in order, so ranks become the visible form of the structure.","whyCN":"往上建也是往上叠：同一意象用来描写按序堆叠的层，于是等级成了结构可见的形态。"},{"no":"03","title":"Lasting relations between groups","titleCN":"群体之间持久的关系","definition":"the durable pattern of links and exchanges that holds between families, professions or other groups","definitionCN":"家庭、行业或其他群体之间稳定的联系与往来格局","example":"Trade marriages knit a social structure that outlives any single household.","exampleCN":"联姻织成一种比任何单个家庭都活得久的社会结构。","why":"a structure holds its shape, so what the phrase singles out is the relation that persists rather than any one meeting.","whyCN":"结构会保持形状，因此这个短语挑出的是持续存在的关系，而不是某一次会面。"},{"no":"04","title":"A society's frame","titleCN":"某个社会的框架","definition":"the frame within which a particular society carries on its ordinary life","definitionCN":"某个具体社会在其中过日常生活的框架","example":"Each port town grew its own social structure around the harbour.","exampleCN":"每座港口城镇都在港湾周围长出自己的社会框架。","why":"the image of a frame says that the parts hold each other up, which is why one can speak of the structure of this society or that one.","whyCN":"框架的意象说明各部分互相支撑，因此可以说这个社会的结构，也可以说那个社会的结构。"},{"no":"05","title":"A pattern that constrains what people can do","titleCN":"社会学中约束行动的格局","definition":"in sociology, the recurring arrangement that limits and shapes what individuals are able to do","definitionCN":"社会学中指反复出现、限制并塑造个人能做之事的安排","example":"The social structure decides who may speak at the assembly before anyone rises.","exampleCN":"在任何人起身之前，社会结构就已经决定谁可以在会上发言。","why":"if the frame is built before the person arrives, it constrains the choices made inside it, which is the sociological reading of the word.","whyCN":"如果框架在个人到来之前就已搭好，它就会约束其中作出的选择，这就是这个词的社会学读法。"},{"no":"06","title":"The internal shape of a group","titleCN":"某个团体内部的结构","definition":"the internal shape of a single group, such as a workshop, a school or a regiment","definitionCN":"单个群体内部的结构，如作坊、学校或一团军队","example":"The workshop's social structure puts the oldest apprentice between the master and the rest.","exampleCN":"作坊的社会结构把最年长的学徒放在师傅与其余人之间。","why":"the word scales down as easily as up: a small body of people is arranged in a shape just as a whole society is.","whyCN":"这个词缩小与放大同样容易：一小群人和整个社会一样，也被安排成某种形状。"},{"no":"07","title":"A skeleton read apart from its filling","titleCN":"抽象义：抽掉内容后剩下的骨架","definition":"the abstract skeleton of an arrangement, considered apart from the people who fill it","definitionCN":"某种安排的抽象骨架，不考虑填在其中的具体人员","example":"The report describes the social structure of the firm and leaves out every name.","exampleCN":"这份报告描述公司的社会结构，却略去所有人名。","why":"the abstract sense keeps only the load-bearing lines, the same way an engineer studies a frame without the walls.","whyCN":"抽象义只保留承重的那几条线，正如工程师研究框架时不管墙面。"},{"no":"08","title":"Relations that hold independently of individuals","titleCN":"独立于具体个人而成立的关系","definition":"the relations between positions that keep their shape even when different people occupy them","definitionCN":"位置之间的关系，即使换人来占据也保持原形","example":"The social structure of the guild survived every change of master.","exampleCN":"行会的社会结构经受住了每一次师傅更替。","why":"once relations are detached from persons, the structure becomes a thing in its own right, and that is the most abstract reading.","whyCN":"一旦关系与人脱开，结构本身就成了一件独立之物，这是最抽象的读法。"}],"etymology":{"intro":{"en":"Social comes from Latin socius 'companion, ally' plus -al, through French social. Structure comes from Latin structura 'a building, arrangement', from struere 'to build, pile up', through Old French. The compound is modern.","cn":"social 来自拉丁 socius「同伴、盟友」加 -al，经法语 social 进入英语。structure 来自拉丁 structura「建筑、安排」，出自 struere「建造、堆叠」，经古法语传入。合成短语是近代产物。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'companion, ally, partner'. Its deeper origin is source uncertain, and the root sometimes proposed for it is a reconstruction rather than a recorded form.","cn":"socius 意为「同伴、盟友、合伙人」。其更深来源不确定，有人为它提出的词根属重构形式，并非有记录的形式。"},{"era":"LATIN SOCIALIS","en":"Socialis 'of allies, of a community' was built on socius with the adjective suffix -alis; it described partnership before it described society at large.","cn":"socialis「盟友的、共同体的」由 socius 加形容词后缀 -alis 构成；它先指伙伴关系，后指整个社会。"},{"era":"LATIN STRUERE","en":"Struere meant 'to build, pile up, arrange'. It is generally regarded as going back to a root meaning 'to spread out in layers', but the Indo-European form given for it is a reconstruction.","cn":"struere 意为「建造、堆叠、安排」。一般认为它可追溯到表示「分层铺开」的词根，但为其给出的印欧形式属重构形式。"},{"era":"LATIN STRUCTURA","en":"Structura, from struere plus -ura, named the act and the result of building, hence a building or an arrangement of parts.","cn":"structura 由 struere 加 -ura 构成，指建造的动作与结果，因此指建筑物或各部分的安排。"},{"era":"FRENCH AND ENGLISH","en":"French social and Old French structure carried both words into English, first as adjectives and nouns of building, later of people.","cn":"法语 social 与古法语 structure 把这两个词带入英语，起初是形容词与建筑名词，后来才用于人。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the compound social structure became a standard term only in modern sociology, no agreed first citation is recorded, and the pre-Latin shapes of socius and struere remain reconstructions.","cn":"来源不确定：social structure 直到近代社会学才成为标准术语，最早书证并无定说；socius 与 struere 在拉丁语之前的形式仍属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms that share one element of the phrase and are easily confused with it; group two holds neighbouring concepts whose scope is different.","cn":"第一组是共享短语某一成分、容易与之混淆的词；第二组是范围不同的邻近概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"first element, adjective","definition":"The adjective for life among others, as in social life or social rules; alone it describes, while the phrase names the arrangement itself.","definitionCN":"指与他人共同生活的形容词，如社交生活、社会规则；单独用时它在描写，短语则指安排本身。"},{"word":"sociable","ipa":"/ˈsəʊʃiəbl/","tag":"same root, personal trait","definition":"Built on socius with -able, it describes a person who enjoys company; it is a temperament, not an arrangement.","definitionCN":"由 socius 加 -able 构成，形容喜欢与人相处的人；它指性情，不指安排。"},{"word":"stricture","ipa":"/ˈstrɪktʃə/","tag":"look-alike, different root","definition":"From stringere 'to draw tight', it means a criticism or a narrowing, as in a stricture on trade; despite the similar shape it shares no root with structure.","definitionCN":"来自 stringere「拉紧」，意为批评或限制，如对贸易的限制；尽管形状相似，它与 structure 并不同源。"},{"word":"structure","ipa":"/ˈstrʌktʃə/","tag":"second element, noun","definition":"The arrangement of parts of anything, a building or a system; the full phrase restricts it to the arrangement of a society.","definitionCN":"指任何事物的部分安排、建筑物或体系；完整短语把它限定为社会的安排。"}]},{"heading":"NEAR MEANING","entries":[{"word":"social system","ipa":"/ˈsəʊʃəl ˈsɪstəm/","tag":"working whole","definition":"The parts of a society seen as a working whole that keeps itself going; social structure stresses the shape, not the running.","definitionCN":"把社会的各部分看作自行运转的整体；social structure 强调形状，而非运转。"},{"word":"social order","ipa":"/ˈsəʊʃəl ˈɔːdə/","tag":"stability and rule","definition":"The condition in which a society is peaceful and its rules are obeyed; structure can persist even through disorder.","definitionCN":"指社会安宁、规则被遵守的状态；结构即使在动乱中也可以持续存在。"},{"word":"social organization","ipa":"/ˈsəʊʃəl ˌɔːɡənaɪˈzeɪʃən/","tag":"grouping and running","definition":"How people are grouped and how that grouping is run; social structure is the wider frame within which such grouping happens.","definitionCN":"指人如何被编组以及编组如何被运作；social structure 是这种编组得以发生的更大框架。"},{"word":"institution","ipa":"/ɪnˈstɪtjuːʃən/","tag":"one established part","definition":"One established body or practice, such as a school or a court; the social structure is the arrangement of many such parts.","definitionCN":"指一个确立的机构或做法，如学校或法庭；social structure 是许多这类部分的总体安排。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"socius 'companion' plus -al: the adjective of living with others.","cn":"socius「同伴」加 -al：与人共同生活的形容词。"},{"en":"struere 'to build up' plus -ura: the noun of what has been built.","cn":"struere「堆叠建造」加 -ura：指建成的那个东西的名词。"},{"en":"The family runs social, societal, socialize, structure, structural, structured.","cn":"同族词包括 social、societal、socialize、structure、structural、structured。"},{"en":"Fixed phrases mark the angle: rigid social structure, change the social structure.","cn":"固定搭配标出角度：僵化的社会结构、改变社会结构。"},{"en":"Sociology contrasts it with social system: the shape versus the running.","cn":"社会学把它与 social system 对照：形状对运转。"}],"abstract":[{"en":"Picture a building frame standing after every wall has been taken away.","cn":"想象一面面墙被拆走之后仍然立着的建筑骨架。"},{"en":"Picture seats in a hall that stay in their rows no matter who sits down.","cn":"想象礼堂里的座位，无论谁来坐都保持原来的排法。"},{"en":"Picture a village map where the well and the shrine decide where houses may stand.","cn":"想象一张村落地图，水井与祠堂决定了房屋可以立在哪里。"}]},"examples":[{"en":"Industrialisation changed the social structure faster than any law could.","cn":"工业化改变社会结构的速度快过任何法律。"},{"en":"The novelist is more interested in the social structure of a kitchen than in its recipes.","cn":"这位小说家更关心厨房里的社会结构，而不是菜谱。"},{"en":"Fieldworkers map social structure by asking who borrows tools from whom.","cn":"田野工作者通过询问谁向谁借工具来绘制社会结构。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社交的）+ structure（构造）」——一群人的位置像房屋的梁柱一样被搭好 → 社会结构、分层格局","word":"social structure"},"root":"拉丁 socius「同伴、盟友」+ -al → social；拉丁 struere「建造、堆叠」→ structura「建筑、安排」→ structure。英语 social structure。","sensesIntro":{"en":"Eight senses follow one frame: institutions and roles are raised into a whole, layers appear, relations hold between groups, the frame belongs to one society, it constrains action, it shrinks to a group, it is read as bare skeleton, and finally as relations that outlast their occupants.","cn":"八个义项沿一副框架展开：制度与角色被搭成整体，层次显现，群体之间维持关系，框架归属于某个社会，它约束行动，它可以缩小到一个团体，再被读作光秃的骨架，最后被读作比占据者更长久的关系。"},"semanticMap":{"core":{"en":"CORE IMAGE: a standing frame that gives every part its place before anyone enters.","cn":"核心意象：一副立着的框架，在任何人进入之前就给每部分定好了位置。"},"chain":["BUILD THE FRAME","STACK THE LAYERS","HOLD THE LINKS","FIX A SOCIETY","LIMIT ACTION","STRIP TO SKELETON"],"branches":[{"senses":"01 · 04","en":"THE FRAME: institutions and roles, and the particular frame one society lives inside.","cn":"框架：制度与角色，以及某个社会所处的那副具体框架。"},{"senses":"02 · 06","en":"SHAPE AT TWO SCALES: ranks stacked in a society and the internal shape of a small group.","cn":"两种尺度的形状：社会中堆叠的等级，与小团体内部的形状。"},{"senses":"03 · 05","en":"HOLD AND LIMIT: durable links between groups are also the pattern that constrains action.","cn":"维系与约束：群体之间持久的联系，同时也是约束行动的格局。"},{"senses":"07","en":"BARE SKELETON: the arrangement read with every person left out.","cn":"光秃的骨架：抽掉所有人之后读出的安排。"},{"senses":"08","en":"DETACHED RELATIONS: positions keep their shape whoever fills them.","cn":"脱开的关系：无论谁来占据，位置都保持原形。"}]},"affixes":{"intro":{"en":"Both halves of the phrase are Latin nouns enlarged by suffixes, and each half also lives on in a large English family.","cn":"短语的两半都是经后缀扩大的拉丁名词，每一半也都在一个庞大的英语词族中延续。"},"latinIntro":{"en":"Latin socius yields socialis and then social; Latin struere yields structura, and the two families meet in the modern compound.","cn":"拉丁 socius 衍生 socialis，再衍生 social；拉丁 struere 衍生 structura；两个词族在近代合成短语中相遇。"},"items":[{"word":"socius","structure":"socius, socii (Latin noun, masculine, second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友","example":"The noun names a partner rather than a whole society.","exampleCN":"这个名词指一个伙伴，而不是整个社会。"},{"word":"socialis","structure":"socialis, sociale (Latin adjective, third declension)","meaning":"of companions, of a community","meaningCN":"同伴的；共同体的","example":"The adjective widened the partner word toward community life.","exampleCN":"这个形容词把「伙伴」的词扩展到共同体生活。"},{"word":"-al","structure":"-alis (Latin adjective suffix, through French -al)","meaning":"relating to","meaningCN":"与……有关的","example":"Socius plus -al gives the English adjective social.","exampleCN":"socius 加 -al 得出英语形容词 social。"},{"word":"societal","structure":"society + -al","meaning":"of society as a whole","meaningCN":"整个社会的","example":"Societal pressure differs from the pressure of a single companion.","exampleCN":"整个社会的压力不同于单个同伴的压力。"},{"word":"struere","structure":"struere, struxi, structum (Latin verb, third conjugation)","meaning":"to build, pile up","meaningCN":"建造；堆叠","example":"The verb names the act of laying one part on another.","exampleCN":"这个动词指把一部分叠在另一部分上的动作。"},{"word":"structura","structure":"structura, structurae (Latin noun, feminine, first declension)","meaning":"a building, an arrangement","meaningCN":"建筑；安排","example":"Structura names the result of the building act.","exampleCN":"structura 指建造动作的结果。"},{"word":"-ura","structure":"-ura (Latin result noun suffix)","meaning":"result of an action","meaningCN":"动作的结果","example":"Struere plus -ura yields structura.","exampleCN":"struere 加 -ura 得出 structura。"},{"word":"structure","structure":"structure (English noun, from Latin structura through French)","meaning":"the arrangement of parts","meaningCN":"各部分的安排","example":"The bridge's structure was checked before the storm.","exampleCN":"暴风雨前检查了这座桥的结构。"},{"word":"structural","structure":"structure + -al","meaning":"relating to structure","meaningCN":"与结构有关的","example":"Structural faults seldom show on the surface.","exampleCN":"结构性的缺陷很少显露在表面。"},{"word":"sociology","structure":"socius + -logy (study suffix, from Greek logos)","meaning":"the study of society","meaningCN":"研究社会的学问","example":"Sociology took social structure as one of its first objects.","exampleCN":"社会学把社会结构列为其最早的研究对象之一。"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"socialis","structure":"socialis, sociale (adjective, third declension)","meaning":"of companions, social","meaningCN":"同伴的；社会的"},{"word":"struere","structure":"struere, struxi, structum (verb, third conjugation)","meaning":"to build, pile up","meaningCN":"建造；堆叠"},{"word":"structura","structure":"structura, structurae (f., first declension)","meaning":"a building, arrangement","meaningCN":"建筑；安排"}]}},{"word":"social organization","ipa_uk":"/ˈsəʊʃəl ˌɔːɡənaɪˈzeɪʃən/","ipa_us":"/ˈsoʊʃəl ˌɔːrɡənəˈzeɪʃən/","definition_zh":"社会组织；人群编组方式；正式团体；结社过程；社区结构；对群体事务的经营管理","definition_en":"the way people are grouped into roles, bodies and networks, and the work of keeping that grouping running","core_image":"河滩上的人群按活儿分成几拨，抬石的、烧饭的、记账的各有人领头，每组都清楚自己与谁搭班。","scene":"河滩上的人群按活儿分成几拨，抬石的、烧饭的、记账的各有人领头，谁与谁搭班写得清楚。The social organization of the camp gives every family a task and a partner.","sceneCN":"这里 social organization 指「一群人被编组成不同班组的方式」（第 1 个义项：按活儿把人分拨并配上负责人的编组方式）；句意为营地的社会组织给每个家庭分配了一项任务和一个搭档。可辨识物件：河滩、石堆、灶火、账簿、分组用的木牌。","pos":[{"tag":"n.","zh":"社会组织；人群编组；正式团体（可数，指某个具体组织体）"}],"collocations":[{"phrase":"formal social organization","zh":"正式的社会组织"},{"phrase":"traditional social organization","zh":"传统社会组织"},{"phrase":"the social organization of work","zh":"劳动的社会组织"},{"phrase":"social organization and kinship","zh":"社会组织与亲属关系"},{"phrase":"a complex social organization","zh":"复杂的社会组织"},{"phrase":"build a social organization","zh":"建立一个社会组织"}],"forms":[{"label":"单数（短语整体）","form":"social organization"},{"label":"复数（短语整体）","form":"social organizations"},{"label":"英式拼写（短语整体）","form":"social organisation"},{"label":"动词（组织）","form":"organize"},{"label":"名词（组织；机构）","form":"organization"},{"label":"名词复数（组织；机构）","form":"organizations"},{"label":"形容词（组织的）","form":"organizational"}],"derivatives":[{"word":"organize","pos":"v.","zh":"organum「工具、器官」+ -ize（动词后缀）→ 由「器官」转为「使各部分成为整体、组织起来」"},{"word":"organization","pos":"n.","zh":"organize + -ation（动作与结果后缀）→ 由「组织」的动作转为「组织、机构」"},{"word":"organizational","pos":"adj.","zh":"organization + -al（形容词后缀）→ 由「组织」转为「组织层面的」"},{"word":"organizer","pos":"n.","zh":"organize + -er（施事后缀）→ 由动作转为「组织者、筹办人」"},{"word":"disorganized","pos":"adj.","zh":"dis-（否定前缀）加 organized → 由「有组织的」转为「杂乱无章的」"}],"senses":[{"no":"01","title":"How people are grouped","titleCN":"人群被编组的方式","definition":"the way a body of people is divided into groups, each with a task and a place","definitionCN":"一群人被分成若干小组、每组各有任务与位置的方式","example":"The social organization of the camp gives every family a task and a partner.","exampleCN":"营地的社会组织给每个家庭分配了一项任务和一个搭档。","why":"organization comes from organum, a tool or organ, and -ation, a making; grouping people is making them work as parts of one body.","whyCN":"organization 来自 organum「工具、器官」加 -ation「造成」，把人们编组就是使他们像一个身体的各部分那样运作。"},{"no":"02","title":"A network of roles and institutions","titleCN":"角色与制度的网络","definition":"the connected set of roles, offices and institutions through which a community carries on its business","definitionCN":"一个共同体借以办事的、相互连接的角色、职位与制度","example":"A fishing village keeps a social organization of skippers, net makers and fishmongers.","exampleCN":"渔村维持着一套由船主、织网人与鱼贩构成的社会组织。","why":"once the parts are organs, each has a function, and the functions must be linked before the whole can work.","whyCN":"一旦各部分被看作器官，每一部分就有功能，而功能必须先被连接起来，整体才能运作。"},{"no":"03","title":"A formal body with rules","titleCN":"有规章的正式团体","definition":"a formally established body, such as a club, a union or a charity, with membership and rules","definitionCN":"正式设立的团体，如俱乐部、工会或慈善会，有成员资格与规章","example":"The grain fund is a social organization with written rules and elected officers.","exampleCN":"粮食基金是一个有成文规章和选举产生负责人的社会组织。","why":"the result noun -ation also names the thing made, so the arranging can harden into an institution that exists in its own right.","whyCN":"-ation 这个结果名词也指被造成之物，因此编组的动作可以硬化为一个自行存在的机构。"},{"no":"04","title":"The process of getting organized","titleCN":"结社与筹备的过程","definition":"the process by which people come together, divide duties and set up a working arrangement","definitionCN":"人们聚合起来、分派职责并建立运作安排的过程","example":"Neighbours began the social organization of a fire watch after the first dry summer.","exampleCN":"第一个干旱的夏天之后，邻里开始了防火巡查的结社筹备。","why":"the same noun covers the act and the outcome, so it can name the work of organizing as well as the body organized.","whyCN":"同一个名词既指动作也指结果，因此它既能指组织的活儿，也能指被组织起来的团体。"},{"no":"05","title":"The structure of a community","titleCN":"社区的结构","definition":"the settled shape of a community, including its groups, their ranks and their usual dealings","definitionCN":"一个社区稳定的形状，包括它的各组人、各自等级与惯常往来","example":"The social organization of the island still centres on the church and the boat shed.","exampleCN":"这座岛的社会组织仍以教堂与船棚为中心。","why":"a community organized year after year settles into a shape, and that shape is what observers call its organization.","whyCN":"一个社区年复一年地被组织，就会稳定成一种形状，观察者把这个形状称作它的组织。"},{"no":"06","title":"Managing the affairs of a group","titleCN":"对群体事务的经营管理","definition":"the work of arranging and running the affairs of a group, from duties to records","definitionCN":"安排并运转一个群体的事务，从职责分派到记录保存","example":"She took over the social organization of the relief depot for the winter.","exampleCN":"她接手了救济站整个冬天的组织管理工作。","why":"the verb organize means to put parts in order; applied to people, it becomes the daily management of their affairs.","whyCN":"动词 organize 意为把各部分排好；用在人身上，它就成了对群体事务的日常管理。"},{"no":"07","title":"Coordinating people for one purpose","titleCN":"为某个目的协调人群","definition":"the coordination of people and resources toward a single stated aim","definitionCN":"为单一既定目标而协调人员与资源","example":"The rescue required a social organization that could form in an hour.","exampleCN":"这次救援需要一种能在一小时内成形的人群协调。","why":"the organic image supplies the point: many parts acting as one body for one end.","whyCN":"器官的意象提供了要点：许多部分为了一个目的而像一个身体那样行动。"},{"no":"08","title":"Abstractly, any arrangement of a group","titleCN":"抽象义：任何群体的具体安排","definition":"any concrete arrangement by which a particular group of people is put in order","definitionCN":"把某一群具体的人排定的任何安排","example":"The ants show a social organization that no one designed.","exampleCN":"蚂蚁呈现出一种无人设计的群体安排。","why":"strip away institutions and only an arrangement of parts remains, so the phrase can describe a hive as easily as a town.","whyCN":"抽掉制度之后只剩各部分的安排，因此这个短语既能描写蜂巢，也能描写城镇。"}],"etymology":{"intro":{"en":"Organization comes from Latin organum, from Greek organon 'tool, instrument, organ', plus the action suffix -ation; organize is the verb built on organ with -ize. Dates are approximate.","cn":"organization 来自拉丁 organum，出自希腊 organon「工具、器具、器官」，再加动作后缀 -ation；organize 是在 organ 上加 -ize 构成的动词。年代均为约数。"},"items":[{"era":"GREEK ORGANON","en":"Organon meant 'tool, instrument, and also organ of the body'. Its deeper origin is source uncertain, and forms offered for a pre-Greek root are reconstructions.","cn":"organon 意为「工具、器具，也指身体器官」。其更深来源不确定，为它给出的前希腊词根形式属重构形式。"},{"era":"LATIN ORGANUM","en":"Latin borrowed organon as organum, keeping both the tool sense and the body sense; the word also came to name a musical instrument.","cn":"拉丁把 organon 借作 organum，同时保留「工具」与「身体器官」两义；这个词后来也指乐器。"},{"era":"ENGLISH ORGAN","en":"English organ names a body part and, separately, a musical instrument; the older tool sense survives mainly inside derived words.","cn":"英语 organ 指身体器官，又另指乐器；较旧的「工具」义主要残存在派生词里。"},{"era":"VERB ORGANIZE","en":"Organize was formed on organ with -ize, 'to make into an organized whole'; the verb is modern and its earliest uses are not precisely dated.","cn":"organize 是在 organ 上加 -ize 构成，意为「使成为有组织的整体」；这个动词属近代产物，最早用法没有确切年代。"},{"era":"NOUN -ATION","en":"The suffix -ation marks an action or its result, from Latin -atio; added to organize it yields organization, the act of arranging and the thing arranged.","cn":"后缀 -ation 出自拉丁 -atio，标记动作或其结果；加在 organize 上得出 organization，既指安排的动作，也指被安排成的东西。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: no agreed first citation is recorded for organization, and the step from 'organ of the body' to 'arranged group of people' has no single documented date.","cn":"来源不确定：organization 的最早书证并无定说；由「身体器官」到「被安排的人群」这一步，也没有单一可考的年代。"}]},"similar":{"note":{"en":"Group one holds forms built on the organ stock that look close to the headword; group two holds terms for social arrangements that differ in scope.","cn":"第一组是同出 organ 词干、与词条形近的词；第二组是范围不同的社会安排术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"organize","ipa":"/ˈɔːɡənaɪz/","tag":"same root, verb","definition":"The verb for putting parts or people in order; the phrase is the result noun, so it names the arrangement rather than the act.","definitionCN":"指把部分或人排好序的动词；短语是结果名词，因此指安排而非动作。"},{"word":"organ","ipa":"/ˈɔːɡən/","tag":"same root, body part","definition":"A part of a living body, or a musical instrument; it is one part, while social organization is the arrangement of many parts.","definitionCN":"指活体的一个器官，或一件乐器；它是单个部分，而 social organization 是许多部分的安排。"},{"word":"organic","ipa":"/ɔːˈɡænɪk/","tag":"same root, adjective","definition":"Built on organ with -ic, it means of living organs, or grown without chemicals, and also describes parts that grow together; it never names a group of people.","definitionCN":"由 organ 加 -ic 构成，指活体器官的、无化学种植的，也形容各部分长在一起；它从不指一群人。"},{"word":"organism","ipa":"/ˈɔːɡənɪzəm/","tag":"same root, living body","definition":"From organ plus -ism, it names a single living body; the shared root makes it look technical kin, but it is a creature, not an arrangement of people.","definitionCN":"由 organ 加 -ism 构成，指单个活体；共同的词根使它看似同类术语，但它指生物，不指人的安排。"}]},{"heading":"NEAR MEANING","entries":[{"word":"social structure","ipa":"/ˈsəʊʃəl ˈstrʌktʃə/","tag":"the wider frame","definition":"The overall frame of institutions and ranks; social organization is the grouping and running that happens inside that frame.","definitionCN":"指制度与等级的总体框架；social organization 是发生在这个框架内部的编组与运作。"},{"word":"institution","ipa":"/ɪnˈstɪtjuːʃən/","tag":"one established body","definition":"A single established body or practice, such as a court or a school; social organization can cover many such bodies and the links between them.","definitionCN":"指单个确立的机构或做法，如法庭或学校；social organization 可涵盖许多这类机构及其间的联系。"},{"word":"association","ipa":"/əˌsəʊsiˈeɪʃən/","tag":"a joined body","definition":"A body of people who have joined for a purpose, usually a formal one; it is one kind of social organization, not the general notion.","definitionCN":"指为某目的而联合的一群人，通常是正式团体；它只是社会组织的一种，而非一般概念。"},{"word":"community","ipa":"/kəˈmjuːnəti/","tag":"the people themselves","definition":"The people who live together and share things; social organization describes how those people are arranged, not who they are.","definitionCN":"指共同生活并共享事物的人们；social organization 描写这些人如何被安排，而不是他们是谁。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"organon 'tool, organ' plus -ation: many parts made to work as one body.","cn":"organon「工具、器官」加 -ation：许多部分被使得像一个身体那样运作。"},{"en":"Organize is organ plus -ize: to put the parts in order.","cn":"organize 是 organ 加 -ize：把各部分排好。"},{"en":"The family runs organ, organize, organization, organizational, organizer.","cn":"同族词包括 organ、organize、organization、organizational、organizer。"},{"en":"Fixed phrases mark the angle: formal social organization, the social organization of work.","cn":"固定搭配标出角度：正式社会组织、劳动的社会组织。"},{"en":"Sociology contrasts it with social structure: the grouping versus the wider frame.","cn":"社会学把它与社会结构对照：编组对更宽的框架。"}],"abstract":[{"en":"Picture a hand with five fingers doing what one arm could never do alone.","cn":"想象一只手的五根手指做出单靠一条胳膊做不到的事。"},{"en":"Picture a kitchen where each cook owns one task and no one owns the meal.","cn":"想象一间厨房，每位厨子只管一道工序，没有人拥有整桌菜。"},{"en":"Picture an anthill that runs perfectly with no blueprint anywhere.","cn":"想象一座蚁丘，没有任何图纸却运转得井井有条。"}]},"examples":[{"en":"The social organization of the harvest shifts with each new irrigation canal.","cn":"每一条新水渠都会改变收获时节的社会组织。"},{"en":"A union is a social organization built to bargain rather than to farm.","cn":"工会是为谈判而不是为耕种建立的社会组织。"},{"en":"Researchers compared the social organization of two primate troops.","cn":"研究者比较了两个灵长类群体的社会组织。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社交的）+ organ（器官）+ ization（造成）」——把一群人接成像器官那样各司其职的整体 → 社会组织、编组方式","word":"social organization"},"root":"希腊 organon「工具、器官」→ 拉丁 organum → 英语 organ；organ + -ize → organize，organize + -ation → organization。英语 social organization。","sensesIntro":{"en":"Eight senses follow one making: people are divided into parts, the parts are linked by roles, the linking hardens into a body, the act and the body share one noun, the community settles into a shape, the shape is managed, it is aimed at one purpose, and finally any arrangement of a group is read under the same name.","cn":"八个义项沿一次「造成」展开：人被分成部分，部分由角色连接，连接硬化成一个团体，动作与团体共用同一个名词，社区稳定成一种形状，这个形状被经营管理，被指向一个目的，最后任何群体的安排都用同一个名称来读。"},"semanticMap":{"core":{"en":"CORE IMAGE: many hands fitted together until they work like one body.","cn":"核心意象：许多只手被装配到一起，直到它们像一个身体那样运作。"},"chain":["DIVIDE THE WORK","LINK THE ROLES","FORM A BODY","RUN THE AFFAIRS","SETTLE INTO SHAPE","ARRANGE ANY GROUP"],"branches":[{"senses":"01 · 03","en":"GROUPING AND BODY: dividing people into parts can end in a formal body with rules.","cn":"编组与团体：把人分成部分，最终可以形成一个有规章的正式团体。"},{"senses":"02 · 04","en":"NETWORK AND PROCESS: roles are linked into a net, and the linking is itself an activity.","cn":"网络与过程：角色被连成一张网，而连接本身就是一项活动。"},{"senses":"05 · 06","en":"SHAPE AND MANAGEMENT: a community settles into a shape, and that shape has to be run.","cn":"形状与管理：社区稳定成一种形状，而这个形状必须被运作。"},{"senses":"07","en":"ONE AIM: the organic image narrows to many parts acting for a single end.","cn":"一个目的：器官意象收窄为许多部分为一个目标行动。"},{"senses":"08","en":"ANY ARRANGEMENT: with institutions removed, a hive or a town fits the same word.","cn":"任何安排：去掉制度之后，蜂巢与城镇都适用同一个词。"}]},"affixes":{"intro":{"en":"Organization is a Greek noun carried into Latin, fitted with an English verb suffix and then a Latin action suffix; the family can be read morpheme by morpheme.","cn":"organization 是一个传入拉丁语的希腊名词，先加英语动词后缀，再加拉丁动作后缀；整个词族可以按语素逐个读出。"},"latinIntro":{"en":"Greek organon became Latin organum, English organ and the verb organize; -ation then turned the verb into organization.","cn":"希腊 organon 变成拉丁 organum，再变成英语 organ 与动词 organize；-ation 随后把这个动词变成 organization。"},"items":[{"word":"organon","structure":"organon (Greek noun, neuter)","meaning":"tool, instrument, organ","meaningCN":"工具；器具；器官","example":"The Greek noun covered both a craftsman's tool and a body part.","exampleCN":"这个希腊名词既指工匠的工具，也指身体的一部分。"},{"word":"organum","structure":"organum, organi (Latin noun, neuter, second declension)","meaning":"tool, instrument, organ","meaningCN":"工具；器具；器官","example":"Latin carried the Greek word into western scholarship.","exampleCN":"拉丁把这个希腊词带入西方学术。"},{"word":"organ","structure":"organ (English noun, from Latin organum)","meaning":"a body part; a musical instrument","meaningCN":"器官；乐器","example":"The heart is an organ in the plain bodily sense.","exampleCN":"心脏是「器官」最朴素意义上的一个器官。"},{"word":"-ize","structure":"-ize (verb suffix, from Greek -izein)","meaning":"to make or become","meaningCN":"使成为；使……化","example":"Organ plus -ize yields the verb organize.","exampleCN":"organ 加 -ize 得出动词 organize。"},{"word":"organize","structure":"organ + -ize","meaning":"to put parts into working order","meaningCN":"把各部分排成可运作的次序","example":"They organize the volunteers into three teams.","exampleCN":"他们把志愿者编成三个队。"},{"word":"-ation","structure":"-ation (Latin action and result suffix, from -atio)","meaning":"the act or result of doing","meaningCN":"动作或动作的结果","example":"Organize plus -ation yields organization.","exampleCN":"organize 加 -ation 得出 organization。"},{"word":"organization","structure":"organize + -ation","meaning":"the act of arranging, and the body arranged","meaningCN":"安排的动作，以及被安排成的团体","example":"The organization meets in the boat shed every spring.","exampleCN":"这个组织每年春天在船棚里开会。"},{"word":"organizational","structure":"organization + -al","meaning":"relating to an organization","meaningCN":"与组织有关的","example":"Organizational change rarely happens overnight.","exampleCN":"组织层面的改变很少一夜发生。"},{"word":"organizer","structure":"organize + -er","meaning":"one who arranges","meaningCN":"组织者；筹办人","example":"The organizer kept a list of every volunteer.","exampleCN":"组织者保存着每位志愿者的名单。"},{"word":"disorganized","structure":"dis- + organized","meaning":"not put in order","meaningCN":"未排好序的；杂乱的","example":"The disorganized depot lost half its stores.","exampleCN":"这个管理混乱的仓库丢了一半存粮。"}],"latinEntries":[{"word":"organum","structure":"organum, organi (n., second declension)","meaning":"tool, instrument, organ","meaningCN":"工具；器具；器官"},{"word":"organizare","structure":"organizare (Medieval Latin verb, first conjugation)","meaning":"to organize, arrange","meaningCN":"组织；安排"},{"word":"organizatio","structure":"organizatio, organizationis (f., third declension, Medieval Latin)","meaning":"an arranging, an organized body","meaningCN":"安排；被组织起来的团体"}]}},{"word":"hierarchical","ipa_uk":"/ˌhɪəˈrɑːkɪkəl/","ipa_us":"/ˌhɪrˈɑːrkɪkəl/","definition_zh":"按等级排列的；等级制的；层层控制的；（计算机）树状层级的；（语言学）层次结构的","definition_en":"arranged in ranked levels, so that each level stands above or below another and higher levels govern lower ones","core_image":"一座层层收窄的石塔，每层的门只通向下一层，越往上人越少、灯越亮。","scene":"清晨钟声响过，走廊两侧的座位由低处向高台依次排开。The abbey's hierarchical order places the abbot above every prior in the cloister.","sceneCN":"这里 hierarchical 指「按等级高低依次排列、由上层统辖下层」（第 1 个义项：等级排列的秩序）；句意为修道院的等级秩序把院长排在所有副院长之上。可辨识物件：石阶、长椅、铜钟、高台上的座位。","pos":[{"tag":"adj.","zh":"按等级排列的；等级制的；层级式的"}],"collocations":[{"phrase":"hierarchical structure","zh":"等级结构"},{"phrase":"hierarchical order","zh":"等级秩序"},{"phrase":"hierarchical society","zh":"等级社会"},{"phrase":"hierarchical control","zh":"层层控制"},{"phrase":"hierarchical model","zh":"层级模型"},{"phrase":"hierarchical organization","zh":"科层组织"}],"forms":[{"label":"原形（形容词）","form":"hierarchical"},{"label":"比较级","form":"more hierarchical"},{"label":"最高级","form":"most hierarchical"},{"label":"副词","form":"hierarchically"},{"label":"名词（等级体系）","form":"hierarchy"},{"label":"名词（高位者）","form":"hierarch"}],"derivatives":[{"word":"hierarchy","pos":"n.","zh":"hierarchēs + 希腊 -ia（抽象名词后缀）→ 由「大祭司的职分」偏移为「等级体系」"},{"word":"hierarch","pos":"n.","zh":"hierarchēs 直接进入英语 → 由「大祭司」偏移为「位居高位者、主教」"},{"word":"hierarchic","pos":"adj.","zh":"hierarchy + 拉丁 -icus ／ 英语 -ic（形容词后缀）→ 由名词「等级体系」转为「等级体系的」"},{"word":"hierarchically","pos":"adv.","zh":"hierarchical + -ly（副词后缀）→ 由「等级制的」转为「按等级地」"}],"senses":[{"no":"01","title":"Arranged in ranked levels","titleCN":"按等级高低依次排列","definition":"organized so that each element sits at a stated rank, one above or below another","definitionCN":"按既定等级组织，使每个元素都处在一个高于或低于他者的位次上","example":"The shelves were arranged in a hierarchical order, from general surveys at the bottom to specialist monographs at the top.","exampleCN":"书架按等级次序排列，底层是一般综述，顶层是专题专著。","why":"the word first names the shape itself: a set of ranks stacked into a ladder, before any question of who commands whom.","whyCN":"这个词首先命名形状本身：一组等级叠成梯子，尚未涉及谁指挥谁。"},{"no":"02","title":"Rule passing down level by level","titleCN":"层层控制，上级统辖下级","definition":"built so that each level holds authority over the level immediately below it","definitionCN":"结构上使每一层对紧邻的下一层拥有权力","example":"A hierarchical command chain keeps every order traceable to one office.","exampleCN":"层层控制的指挥链让每道命令都能追溯到某个具体机构。","why":"ranking is not only a picture; once ranks exist, authority naturally flows down them.","whyCN":"等级不只是画面；等级一旦存在，权力便自然沿其向下流动。"},{"no":"03","title":"Deference to rank","titleCN":"尊重位阶，按位阶行事","definition":"showing respect for rank in speech, seating or order of address","definitionCN":"在言辞、座次或称呼次序上表现出对位阶的尊重","example":"In such a hierarchical culture, juniors wait to be invited before they speak.","exampleCN":"在这种尊重位阶的文化里，晚辈要等被邀请才开口。","why":"the adjective can describe people as well as structures: a person who accepts the ladder is hierarchical in manner.","whyCN":"这个形容词也能形容人而非结构：接受梯子的人，举止上就是讲位阶的。"},{"no":"04","title":"Parent and child nodes in computing","titleCN":"计算机中的树状层级","definition":"stored as a tree in which each node has one parent and may have several children","definitionCN":"以树状结构存储，每个节点有一个父节点，并可拥有若干子节点","example":"The files sit in a hierarchical directory, so every folder knows its parent.","exampleCN":"文件存放在树状目录中，因此每个文件夹都知道自己的上级。","why":"computing borrowed the ladder and turned each rung into a node linked to the one above.","whyCN":"计算机借用了梯子，把每一级变成与上一级相连的节点。"},{"no":"05","title":"Layers in linguistic structure","titleCN":"语言学中的层级结构","definition":"described as layers, from sounds through words to phrases and sentences, each built on the one below","definitionCN":"按层次描述，从语音到词、短语、句子，每一层建立在下一层之上","example":"A hierarchical grammar treats a sentence as phrases containing smaller phrases.","exampleCN":"层级语法把句子看作由短语构成、短语又包含更小短语的结构。","why":"language nests units inside units, so the same image of stacked levels fits without change.","whyCN":"语言把单位套在单位里，同一幅层层相叠的图像无需改动便适用。"},{"no":"06","title":"Ranked by importance","titleCN":"按重要性排序","definition":"listed in order of weight or priority rather than alphabetically or by date","definitionCN":"按分量或优先次序排列，而非按字母或日期","example":"The report opens with a hierarchical list of risks, the gravest first.","exampleCN":"报告开头是一份按重要性排序的风险清单，最严重的排在最前。","why":"the noun hierarchy is often used for a priority list, and the adjective follows that use.","whyCN":"名词 hierarchy 常指优先级清单，形容词也随之这样使用。"},{"no":"07","title":"Rigid and unequal ranking","titleCN":"僵化的等级不平等","definition":"criticized as a system in which rank hardens into unfair advantage","definitionCN":"被批评为等级固化为不公平优势的体制","example":"Critics call the old firm too hierarchical for young scientists to challenge anyone.","exampleCN":"批评者说这家老机构等级太僵化，年轻科研人员不敢质疑任何人。","why":"the descriptive sense turns evaluative once the ladder is seen to block talent and speech.","whyCN":"一旦看出梯子阻挡人才与言论，描述义便带上了评价色彩。"},{"no":"08","title":"Nested levels in the abstract","titleCN":"抽象概念的嵌套层级","definition":"organized as levels inside levels, as in nested categories or ranked criteria","definitionCN":"按层中有层的方式组织，如嵌套类别或分级标准","example":"The taxonomy is hierarchical, with each broad class holding narrower ones inside it.","exampleCN":"这套分类是层级式的，每个大类里面都装着更窄的类。","why":"stripped of people and machines, the image survives as pure containment: a level holding smaller levels.","whyCN":"抽去人与机器，图像仍作为纯粹的包含关系存活：一层装着更小的层。"}],"etymology":{"intro":{"en":"Hierarchical goes back to Greek hieros 'sacred' and arkhein 'to rule', through hierarchēs 'high priest' and medieval Latin hierarchia; English added -ical. Dates are approximate.","cn":"hierarchical 可追溯至希腊 hieros「神圣」与 arkhein「统治」，经 hierarchēs「大祭司」与中世纪拉丁 hierarchia，英语再加 -ical。年代均为约数。"},"items":[{"era":"GREEK HIEROS","en":"hieros meant 'sacred, holy'. Its deeper origin is source uncertain; the links sometimes proposed to other Indo-European roots are reconstructions, not demonstrated derivations.","cn":"hieros 意为「神圣的、属于神的」。其更深来源不确定；有人把它与其他印欧词根联系起来，那些只是重构形式，并非已证实的派生。"},{"era":"GREEK ARKHEIN","en":"arkhein meant 'to rule, to begin'. Its origin before Greek is source uncertain, and any older root offered for it is a reconstruction.","cn":"arkhein 意为「统治、开始」。它在希腊语之前的来源不确定，凡为其给出的更早词根均属重构形式。"},{"era":"GREEK HIERARCHES","en":"hieros plus arkhein produced hierarchēs, 'one who rules sacred things', a title for a high priest.","cn":"hieros 加 arkhein 构成 hierarchēs「掌管神圣之事者」，是大祭司的称号。"},{"era":"MEDIEVAL LATIN HIERARCHIA","en":"hierarchia named an ordered set of ranks, first of angels and then of clergy; it is generally thought to be a late antique coinage from the Greek title.","cn":"hierarchia 指一套有序的等级，先用于天使，后用于教士；一般认为它是古典晚期据希腊称号造出的词。"},{"era":"ENGLISH HIERARCHY","en":"English took hierarchy from the Latin noun, and its sense widened from church ranks to any body arranged by rank.","cn":"英语从拉丁名词借入 hierarchy，其义从教会等级扩展到任何按等级排列的团体。"},{"era":"ENGLISH ICAL","en":"The suffix -ical produced the adjective hierarchical; from the nineteenth century it spread to biology, linguistics and computing.","cn":"后缀 -ical 造出形容词 hierarchical；从 19 世纪起，它扩散到生物学、语言学与计算机领域。"}]},"similar":{"note":{"en":"Group one holds look-alikes that share one Greek element but build a different word; group two holds near neighbours that also describe order or layers.","cn":"第一组是形近词：它们共享一个希腊成分，却构成不同的词；第二组是同样描述次序或层次的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hieroglyphic","ipa":"/ˌhaɪərəˈɡlɪfɪk/","tag":"sacred carving","definition":"hieros 'sacred' plus glyphein 'to carve': writing in sacred pictures. Only the first element matches hierarchical, and the second means carving, not ruling.","definitionCN":"hieros「神圣」加 glyphein「雕刻」：用神圣图像书写的文字。只有第一个成分与 hierarchical 相同，第二个成分意为雕刻，而非统治。"},{"word":"monarchic","ipa":"/məˈnɑːkɪk/","tag":"one ruler","definition":"monos 'one' plus arkhein 'to rule': rule by a single person. It shares the ruling element but not hieros, so it is not a relative of hierarchical.","definitionCN":"monos「单一」加 arkhein「统治」：由一人统治。它共享统治成分，却没有 hieros，因此并非 hierarchical 的同族词。"},{"word":"anarchic","ipa":"/əˈnɑːkɪk/","tag":"without rule","definition":"an- 'without' plus arkhein: lacking rule or order. The second element is the same, but the prefix reverses the meaning.","definitionCN":"an-「无」加 arkhein：缺少统治或秩序。第二个成分相同，前缀却把意思反转。"},{"word":"archaic","ipa":"/ɑːˈkeɪɪk/","tag":"old beginning","definition":"From Greek arkhe 'beginning', not arkhein 'to rule': it means old-fashioned, and the resemblance to hierarchical is misleading.","definitionCN":"来自希腊 arkhe「开端」，而非 arkhein「统治」：意为古旧的，与 hierarchical 的相似具有误导性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ranked","ipa":"/ˈrɑːŋkt/","tag":"put in order","definition":"placed in an explicit order, often by score; it does not say that the order is a lasting structure.","definitionCN":"按明确次序排好，常按得分；它不表示这个次序是一种持久结构。"},{"word":"tiered","ipa":"/ˈtɪəd/","tag":"levels side by side","definition":"arranged in tiers, as seats or a cake; tiers are layers, but they need not control one another.","definitionCN":"分层排列，如座位或蛋糕；层只是层，彼此不必存在控制关系。"},{"word":"pyramidal","ipa":"/pɪˈræmɪdəl/","tag":"few at the top","definition":"shaped like a pyramid, wide at the base and narrow at the peak; hierarchical adds authority, not just shape.","definitionCN":"形如金字塔，底部宽、顶端窄；hierarchical 还带有权力关系，不只是形状。"},{"word":"stratified","ipa":"/ˈstrætɪfaɪd/","tag":"layers of society","definition":"divided into social layers, a term from geology and sociology; it stresses separation more than command.","definitionCN":"划分为社会阶层，是地质学与社会学的用词；它更强调分隔，而非指挥。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"hieros 'sacred' plus arkhein 'rule' plus -ical: sacred rule turned into ranked order.","cn":"hieros「神圣」加 arkhein「统治」再加 -ical：神圣的统治转成等级秩序。"},{"en":"The family runs hierarchy, hierarch, hierarchic, hierarchical, hierarchically.","cn":"同族词包括 hierarchy、hierarch、hierarchic、hierarchical、hierarchically。"},{"en":"Fixed phrases mark the structure: hierarchical structure, hierarchical order, hierarchical control.","cn":"固定搭配标出结构：等级结构、等级秩序、层层控制。"},{"en":"Church ranks are the oldest model: angels above bishops, bishops above priests.","cn":"教会等级是最古老的模型：天使在主教之上，主教在神父之上。"},{"en":"Computing keeps the same picture and renames the rungs: root, parent node, child node.","cn":"计算机保留同一幅图，只给梯级改名：根、父节点、子节点。"}],"abstract":[{"en":"Picture a ladder whose rungs grow shorter the higher you climb.","cn":"想象一架梯子，越往上爬，横档越短。"},{"en":"Picture a family tree in which every branch knows exactly which trunk it belongs to.","cn":"想象一棵家谱树，每根枝条都清楚自己属于哪根主干。"},{"en":"Picture a cabinet whose drawers hold smaller drawers inside them.","cn":"想象一个柜子，抽屉里面还装着更小的抽屉。"}]},"examples":[{"en":"The museum's catalogue is hierarchical, from century down to single objects.","cn":"博物馆的目录是层级式的，从世纪一路细分到单件器物。"},{"en":"Flat teams decide faster than hierarchical ones when approval must climb six levels.","cn":"当批准要爬过六层时，扁平团队的决策比等级团队更快。"},{"en":"A hierarchical model of memory nests items inside larger categories.","cn":"层级式记忆模型把项目套在更大的类别之中。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「hier（神圣）+ archy（统治）」——神圣的统治排成一层层 → 等级制的、层层控制的","word":"hierarchical"},"root":"希腊 hieros「神圣」+ arkhein「统治」→ hierarchēs「大祭司」→ 中世纪拉丁 hierarchia → 英语 hierarchy，加 -ical 得 hierarchical；hieros 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one shape: ranks stacked into a ladder, then authority flowing down it, people bowing to it, machines and sentences nesting inside it, priorities sorted by it, inequality hardened by it, and finally pure containment of level within level.","cn":"八个义项沿同一个形状展开：等级叠成梯子，权力顺梯而下，人向梯子行礼，机器与句子在其中嵌套，优先级依它排序，不平等因它固化，最后只剩层中套层的纯粹包含关系。"},"semanticMap":{"core":{"en":"CORE IMAGE: a narrowing tower of levels, each door opening only onto the floor below.","cn":"核心意象：一座层层收窄的塔，每道门只通向下一层。"},"chain":["STACK THE RANKS","RULE FROM ABOVE","DEFER TO POSITION","NEST THE NODE","LAYER THE SENTENCE","NEST THE CATEGORY"],"branches":[{"senses":"01 · 02","en":"SHAPE AND POWER: the ladder is first a picture of ranks, then a channel for command.","cn":"形状与权力：梯子先是等级的画面，再成为命令的通道。"},{"senses":"03 · 04","en":"PEOPLE AND MACHINES: one reading is a person bowing to rank, the other a node knowing its parent.","cn":"人与机器：一种读法是人对位阶行礼，另一种读法是节点认得父节点。"},{"senses":"05 · 06","en":"LANGUAGE AND PRIORITY: units nest inside units, and risks are sorted by weight.","cn":"语言与优先级：单位套着单位，风险按分量排序。"},{"senses":"07","en":"HARDENED LADDER: the same ranks become an accusation when they block talent and speech.","cn":"固化的梯子：同一套等级一旦阻挡人才与言论，就成了被指控的对象。"},{"senses":"08","en":"PURE CONTAINMENT: with people and machines removed, a level simply holds smaller levels.","cn":"纯粹包含：抽去人与机器，一层就只是装着更小的层。"}]},"affixes":{"intro":{"en":"Hierarchical is built from two Greek elements plus an English adjective suffix, so its whole family can be read morpheme by morpheme.","cn":"hierarchical 由两个希腊成分加一个英语形容词后缀构成，因此整个词族可以按语素逐个读出。"},"latinIntro":{"en":"Greek hieros and arkhein produced hierarchēs; medieval Latin formed hierarchia from it, and English built hierarchy, hierarch and hierarchical around that noun.","cn":"希腊 hieros 与 arkhein 构成 hierarchēs；中世纪拉丁据此造出 hierarchia，英语再围绕这个名词构成 hierarchy、hierarch 与 hierarchical。"},"items":[{"word":"hieros","structure":"hieros (Greek adjective)","meaning":"sacred, holy, belonging to the gods","meaningCN":"神圣的；属于神的","example":"The first element names what belongs to the gods.","exampleCN":"第一个成分指属于神的东西。"},{"word":"arkhein","structure":"arkhein (Greek verb)","meaning":"to rule, to command; also to begin","meaningCN":"统治；指挥；也指开始","example":"The second element names the act of ruling.","exampleCN":"第二个成分指统治这一动作。"},{"word":"hierarchēs","structure":"hieros + arkhein (Greek noun)","meaning":"one who rules sacred things; a high priest","meaningCN":"掌管神圣之事者；大祭司","example":"The compound names an office before it names a ladder.","exampleCN":"这个复合词先指一个职位，之后才指一套层级。"},{"word":"hierarchia","structure":"hierarchēs + -ia (medieval Latin noun)","meaning":"ordered ranks of angels or clergy","meaningCN":"天使或教士的有序等级","example":"The Latin noun turned a single office into a system of ranks.","exampleCN":"这个拉丁名词把单个职位变成了一套等级体系。"},{"word":"-ical","structure":"-icalis (Latin-derived adjective suffix, through French)","meaning":"relating to, characterized by","meaningCN":"与……有关的；具有……特征的","example":"Hierarchy plus -ical yields the English adjective hierarchical.","exampleCN":"hierarchy 加 -ical 得出英语形容词 hierarchical。"},{"word":"hierarchy","structure":"hierarchia through Old French, shortened in English","meaning":"a system of ranks one above another","meaningCN":"层层相上的等级体系","example":"The hierarchy of the court had room for every petitioner.","exampleCN":"宫廷的等级体系为每位请愿者都留了位置。"},{"word":"hierarch","structure":"hierarchēs through Latin hierarcha","meaning":"a person high in a ranked system","meaningCN":"等级体系中的高位者","example":"The hierarch sat at the head of the assembly.","exampleCN":"这位高位者坐在集会之首。"},{"word":"hierarchic","structure":"hierarchy + -ic","meaning":"of or arranged as a hierarchy","meaningCN":"等级体系的；按等级排列的","example":"The diagram shows a strictly hierarchic layout.","exampleCN":"这张图显示了一个严格按等级排布的结构。"},{"word":"hierarchically","structure":"hierarchical + -ly","meaning":"in a ranked, level-by-level manner","meaningCN":"按等级地；逐层地","example":"The files are stored hierarchically, folder inside folder.","exampleCN":"文件按层级存放，文件夹套着文件夹。"}],"latinEntries":[{"word":"hierarchia","structure":"hierarchia, hierarchiae (f., first declension)","meaning":"sacred rule; ordered ranks of angels or clergy","meaningCN":"神圣统治；天使或教士的等级"},{"word":"hierarcha","structure":"hierarcha, hierarchae (m., first declension)","meaning":"high priest","meaningCN":"大祭司"},{"word":"hierarchicus","structure":"hierarchicus, hierarchica, hierarchicum (adjective)","meaning":"of a hierarchy, ranked","meaningCN":"等级体系的；按等级排列的"}]}},{"word":"social status","ipa_uk":"/ˌsəʊʃəl ˈsteɪtəs/","ipa_us":"/ˌsoʊʃəl ˈsteɪtəs/","definition_zh":"社会地位；（群体中的）位次与声望；由出身、职位或成就带来的相对位置","definition_en":"the position a person or group holds in a society, measured by the respect, influence and resources attached to it","core_image":"一间大厅里，座位从门口向讲台排成高低不同的台阶，每个人按名次落座。","scene":"村口的宴席上，长辈先动筷，年轻人依次往后坐。In the village feast, social status decides who reaches for the dish first.","sceneCN":"这里 social status 指「一个人在群体中按声望与影响力排出的位次」（第 1 个义项：群体中的相对位次）；句意为在村里的宴席上，社会地位决定谁先动筷。可辨识物件：长桌、碗筷、上座、靠墙的矮凳。","pos":[{"tag":"n.","zh":"社会地位；社会位次与声望"},{"tag":"adj.","zh":"作定语：社会地位方面的，如社会地位差异"}],"collocations":[{"phrase":"high social status","zh":"很高的社会地位"},{"phrase":"low social status","zh":"较低的社会地位"},{"phrase":"social status symbol","zh":"社会地位象征"},{"phrase":"achieve social status","zh":"获得社会地位"},{"phrase":"confer social status","zh":"赋予社会地位"},{"phrase":"social status differences","zh":"社会地位差异"}],"forms":[{"label":"原形（名词短语）","form":"social status"},{"label":"复数（少见，指多种地位）","form":"social statuses"},{"label":"定语形式（连字符复合词）","form":"social-status"},{"label":"口语省略形式","form":"status"},{"label":"相关复合名词","form":"status symbol"}],"derivatives":[{"word":"socially","pos":"adv.","zh":"social + -ly（副词后缀）→ 由「社会的」转为「在社会层面、在社交上」"},{"word":"socialize","pos":"v.","zh":"social + -ize（动词化后缀）→ 由「社会的」转为「使社会化、与人交往」"},{"word":"socialization","pos":"n.","zh":"socialize + -ation（名词后缀）→ 由动作「使社会化」转为「社会化过程」"},{"word":"societal","pos":"adj.","zh":"society + -al（形容词后缀）→ 由「社会团体」转为「整体社会层面的」"},{"word":"status-seeking","pos":"adj./n.","zh":"status + -seeking（复合后缀）→ 由「位次」转为「追求地位的」"}],"senses":[{"no":"01","title":"Relative standing in a group","titleCN":"群体中的相对位次","definition":"the rank a person holds among others in a group, as shown by attention, seating or speaking order","definitionCN":"一个人在群体中相对他人所处的位次，体现在受关注程度、座次或发言次序上","example":"In the village feast, social status decides who reaches for the dish first.","exampleCN":"在村里的宴席上，社会地位决定谁先动筷。","why":"the phrase joins a Latin word for companion to a Latin word for standing, so its core is where one stands among others.","whyCN":"这个短语把表示「同伴」的拉丁词与表示「站立位置」的拉丁词连在一起，核心就是一个人在他人之间站的位置。"},{"no":"02","title":"Prestige attached to an office","titleCN":"职位带来的声望","definition":"the respect a role carries, so that the post itself lends rank to whoever holds it","definitionCN":"某个角色所带的敬意，使职位本身把位次赋予任职者","example":"The old judge's social status came from the bench rather than from his income.","exampleCN":"这位老法官的社会地位来自法官席位，而不是他的收入。","why":"standing is not only claimed by persons; offices are ranked, and the rank rubs off on the person.","whyCN":"位次不只由个人主张；职位本身也被排序，位次会附着到任职者身上。"},{"no":"03","title":"Ascribed versus achieved position","titleCN":"先赋地位与获致地位","definition":"rank inherited at birth from family, caste or lineage, as opposed to rank earned through effort","definitionCN":"出生即由家庭、种姓或血统带来的位次，与靠努力获得的位次相对","example":"Sociologists separate social status inherited at birth from status achieved later.","exampleCN":"社会学家把出生即得的地位与后来获得的地位区分开来。","why":"sociology split the phrase in two: some standing is given before one acts, and some must be won.","whyCN":"社会学把这个短语一分为二：有些位次在人行动之前就已给定，有些则必须争取。"},{"no":"04","title":"Position in an occupational ladder","titleCN":"职业层级中的位置","definition":"the place an occupation occupies relative to others in pay, training and respect","definitionCN":"某种职业在薪酬、训练与受尊重程度上相对其他职业所处的位置","example":"Nursing carries a high social status in public surveys but a low salary.","exampleCN":"在公众调查中，护理职业的社会地位很高，薪水却偏低。","why":"once jobs are ranked, the phrase moves from persons to whole occupations.","whyCN":"职业一旦被排序，这个短语就从个人转到整个职业。"},{"no":"05","title":"Legal standing recognized by law","titleCN":"法律承认的身份状态","definition":"a formal category such as marital, residency or citizenship status that fixes some rights","definitionCN":"婚姻、居留或公民身份等正式类别，它固定了部分权利","example":"Marital status is recorded separately from social status in the census.","exampleCN":"在人口普查中，婚姻身份与社会地位分开登记。","why":"the standing sense narrows in law to the categories a state recognizes and records.","whyCN":"「站立位置」这一含义在法律中收窄为国家承认并登记的类别。"},{"no":"06","title":"High rank in ordinary speech","titleCN":"口语中的「高地位」","definition":"used without qualification to mean people of standing, wealth or influence","definitionCN":"不加限定地指有身份、有钱或有影响力的人","example":"She married into a family of considerable social status.","exampleCN":"她嫁入了一个社会地位相当高的家庭。","why":"everyday use drops the comparative: to have status usually means to have a lot of it.","whyCN":"日常用法省去了比较：说某人有地位，通常意味着地位很高。"},{"no":"07","title":"Relative position in any system","titleCN":"任何体系中的相对位置","definition":"the place an item holds relative to others in a network, ranking or hierarchy of any kind","definitionCN":"某一项在任一网络、排名或层级中相对其他项所处的位置","example":"In network analysis, a node's social status is its relative position among all other nodes.","exampleCN":"在网络分析中，一个节点的社会地位就是它在所有其他节点之间的相对位置。","why":"the word standing generalizes: anything that can be compared has a position in the comparison.","whyCN":"「位置」一词可以一般化：凡可比较之物，在比较中都有位置。"},{"no":"08","title":"Status displayed on a platform","titleCN":"社交平台上显示的地位","definition":"visible markers of rank on an online service, such as badges, follower counts or verification marks","definitionCN":"网络服务上可见的位次标记，如徽章、粉丝数或认证标识","example":"On the platform, social status is displayed as a badge beside the user name.","exampleCN":"在这个平台上，社会地位以用户名旁的徽章形式显示出来。","why":"digital services turned rank into a visible counter, and the old phrase followed it online.","whyCN":"数字服务把位次变成可见的计数，这个旧短语也随之进入网络。"}],"etymology":{"intro":{"en":"Social status joins two Latin words: social from socius 'companion, ally', and status 'standing, position', a noun from stare 'to stand'. Dates are approximate.","cn":"social status 由两个拉丁词合成：social 来自 socius「同伴、盟友」，status 来自 stare「站立」的名词形式，意为「站立状态、位置」。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"socius meant 'companion, ally, partner'. Its deeper origin is source uncertain; the link sometimes proposed to sequi 'to follow' is a hypothesis, not an established derivation.","cn":"socius 意为「同伴、盟友、合伙人」。其更深来源不确定；有人提出它与 sequi「跟随」有关，那只是假说，并非已证实的派生。"},{"era":"LATIN SOCIALIS","en":"socius plus -alis produced socialis, 'of companions or allies', the adjective behind English social.","cn":"socius 加 -alis 构成 socialis「同伴的、盟友的」，即英语 social 背后的形容词。"},{"era":"LATIN STATUS","en":"status was a noun of standing, position or condition, formed from the verb stare and used in law for a person's fixed legal place.","cn":"status 是表示站立状态、位置或状况的名词，由动词 stare 构成，在法律中指个人固定的法定位置。"},{"era":"LATIN STARE","en":"stare meant 'to stand'. Its origin before Latin is source uncertain, and any older root cited for it is a reconstruction.","cn":"stare 意为「站立」。它在拉丁语之前的来源不确定，凡为其引用的更早词根均属重构形式。"},{"era":"ENGLISH SOCIAL STATUS","en":"English took social through Old French and status directly from Latin; the two words were joined in nineteenth-century sociology.","cn":"英语经古法语借入 social，又直接从拉丁语借入 status；19 世纪社会学把两词连成了一个短语。"},{"era":"MODERN EXTENSIONS","en":"The phrase is generally thought to have spread from sociology into everyday speech, and later into network analysis and online platforms.","cn":"一般认为这个短语从社会学扩散到日常语言，后来又进入网络分析与线上平台。"}]},"similar":{"note":{"en":"Group one holds words whose forms echo status but whose Latin sources and meanings differ; group two holds near neighbours for rank and reputation.","cn":"第一组是词形让人想到 status、但拉丁来源与含义都不同的词；第二组是表示位次与声望的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"state","ipa":"/steɪt/","tag":"condition or polity","definition":"From Latin status through Old French estat: a condition, or a political community. It names a situation or a country, not a person's rank.","definitionCN":"经古法语 estat 来自拉丁 status：指状况，或指政治共同体。它命名的是情形或国家，不是个人位次。"},{"word":"statue","ipa":"/ˈstætʃuː/","tag":"carved figure","definition":"From Latin statua, 'something set up', also from stare: a carved or cast figure standing in place, with no idea of rank.","definitionCN":"来自拉丁 statua「被立起来之物」，同样出自 stare：指立在原处的雕刻或铸造人像，与位次无关。"},{"word":"statute","ipa":"/ˈstætʃuːt/","tag":"written law","definition":"From Latin statutum, 'a thing decided', from statuere 'to set up, determine': a enacted law, not a social position.","definitionCN":"来自拉丁 statutum「已定之事」，出自 statuere「设立、裁定」：指成文法律，不是社会位置。"},{"word":"statistics","ipa":"/stəˈtɪstɪks/","tag":"numerical data","definition":"Coined in German from Latin status 'state': the science of data about a state, later any numerical summary.","definitionCN":"在德语中据拉丁 status「国家」造出：原指关于国家状况的数据之学，后指任何数字汇总。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rank","ipa":"/ræŋk/","tag":"place in a formal order","definition":"A definite position inside an organization or scale, such as the rank of captain; narrower and more official than social status.","definitionCN":"组织或等级序列中的确定位置，如上尉军衔；比 social status 更窄、更正式。"},{"word":"standing","ipa":"/ˈstændɪŋ/","tag":"reputation among others","definition":"The estimation in which a person is held by others; close to social status but without implying a structured ladder.","definitionCN":"他人在心目中给予某人的评价；接近 social status，但不预设一套结构化的梯子。"},{"word":"prestige","ipa":"/prɪˈstiːdʒ/","tag":"admiration earned","definition":"Admiration attached to success, talent or office; it is one ingredient of social status, not the whole of it.","definitionCN":"因成功、才能或职位而获得的钦佩；它只是社会地位的一个成分，而非全部。"},{"word":"class","ipa":"/klɑːs/","tag":"broad social layer","definition":"A large economic or social grouping, such as the working class; it describes a layer, whereas social status describes a relative place.","definitionCN":"宽泛的经济或社会群体，如工人阶级；它描述的是一个层，而社会地位描述的是相对位置。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"socius 'companion' plus status 'standing': literally where you stand among your companions.","cn":"socius「同伴」加 status「站立位置」：字面就是你在同伴之间站的位置。"},{"en":"The family runs social, society, socially, socialize, societal, sociology.","cn":"同族词包括 social、society、socially、socialize、societal、sociology。"},{"en":"Fixed phrases mark the scale: high social status, low social status, social status symbol.","cn":"固定搭配标出高低：很高的社会地位、较低的社会地位、社会地位象征。"},{"en":"Sociology pairs ascribed status with achieved status, the given and the earned.","cn":"社会学把先赋地位与获致地位配对：一个是给定的，一个是挣来的。"},{"en":"A badge beside a user name is the newest form of an old idea.","cn":"用户名旁的徽章，是旧观念的最新形态。"}],"abstract":[{"en":"Picture a hall where the chairs are carved to different heights, and everyone finds the one that fits.","cn":"想象一间大厅，椅子被雕成不同高度，每个人找到适合自己的那张。"},{"en":"Picture a queue that reorders itself whenever someone is greeted by name.","cn":"想象一支队伍，每当有人被点名问候，队形就自动重排。"},{"en":"Picture a ladder whose rungs are made of other people's opinions.","cn":"想象一架梯子，横档由别人的看法做成。"}]},"examples":[{"en":"The badge raises the user's social status without changing the user's income.","cn":"徽章提高了用户的社会地位，却没有改变用户的收入。"},{"en":"Ascribed social status can outlast the economy that once supported it.","cn":"先赋的社会地位，可以比曾经支撑它的经济活得更久。"},{"en":"Nurses report high social status but low pay in repeated surveys.","cn":"在多次调查中，护士报告的社会地位高，薪酬却低。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社交的）+ status（状态）」——在人群里站到什么位置 → 社会地位、位次与声望","word":"social status"},"root":"拉丁 socius「同伴、盟友」→ socialis → 英语 social；拉丁 stare「站立」→ status「站立状态、位置」→ 英语 status；两词在 19 世纪社会学中合成 social status。","sensesIntro":{"en":"Eight senses follow one question, where a person stands: among companions in a group, behind an office, at birth or after effort, inside an occupation, before the law, in plain approval, in any comparable system, and finally as a badge on a screen.","cn":"八个义项沿同一个问题展开，即一个人站在哪里：在群体的同伴之间、在职位背后、在出生时或努力之后、在职业内部、在法律面前、在日常认可中、在任何可比较的体系里，最后是在屏幕上的徽章。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hall of chairs at different heights, each person seated by the rank others grant.","cn":"核心意象：一间摆着高低不同椅子的大厅，每个人按他人给予的位次落座。"},"chain":["FIND YOUR PLACE","BORROW THE OFFICE","INHERIT OR EARN","RANK THE TRADE","FIX IT IN LAW","COUNT IT ONLINE"],"branches":[{"senses":"01 · 02","en":"PLACE AND OFFICE: one rank comes from the group's attention, another from the post a person fills.","cn":"位置与职位：一种位次来自群体的关注，另一种来自个人所占据的职位。"},{"senses":"03 · 04","en":"GIVEN AND EARNED: birth hands out some rank, and whole occupations are ranked later.","cn":"先赋与获致：出生分派了一部分位次，整个职业则在后来的排序中得到位次。"},{"senses":"05 · 06","en":"LAW AND PRAISE: the state records a formal category, while everyday speech simply admires high standing.","cn":"法律与赞誉：国家登记正式类别，日常语言则径直赞许高位。"},{"senses":"07","en":"ANY SYSTEM: strip the society away and a node still has a position among other nodes.","cn":"任何体系：抽去社会，一个节点仍在其他节点之间拥有位置。"},{"senses":"08","en":"VISIBLE BADGE: a platform turns standing into a mark beside a name.","cn":"可见徽章：平台把位次变成名字旁边的标记。"}]},"affixes":{"intro":{"en":"Social status is a two-word phrase, and each half can be read morpheme by morpheme, from Latin socius on one side and Latin stare on the other.","cn":"social status 是一个两词短语，两半都可以按语素读出：一侧是拉丁 socius，另一侧是拉丁 stare。"},"latinIntro":{"en":"Latin socius gives socialis, societas and English social; Latin stare gives status and English state, while English adds -ly, -ize and -ation to build the modern family.","cn":"拉丁 socius 衍生 socialis、societas 与英语 social；拉丁 stare 衍生 status 与英语 state，英语再加 -ly、-ize 与 -ation 构成现代词族。"},"items":[{"word":"socius","structure":"socius, socii (Latin noun, second declension)","meaning":"companion, ally, partner","meaningCN":"同伴；盟友；合伙人","example":"The noun names a person who stands alongside another.","exampleCN":"这个名词指站在另一人身旁的人。"},{"word":"socialis","structure":"socialis, sociale (Latin adjective, third declension)","meaning":"of companions, allied","meaningCN":"同伴的；结盟的","example":"The adjective describes what belongs to a group of allies.","exampleCN":"这个形容词描述属于盟友群体的事物。"},{"word":"societas","structure":"socius + -tas (Latin noun, third declension)","meaning":"association, partnership, community","meaningCN":"结社；合伙；共同体","example":"The noun names the group formed by companions.","exampleCN":"这个名词指同伴结成的群体。"},{"word":"status","structure":"status, status (Latin noun, fourth declension)","meaning":"standing, position, condition","meaningCN":"站立状态；位置；状况","example":"The noun turns the act of standing into a fixed place.","exampleCN":"这个名词把站立的动作变成固定的位置。"},{"word":"stare","structure":"stare, steti, statum (Latin verb, first conjugation)","meaning":"to stand, to remain standing","meaningCN":"站立；保持站立","example":"The verb supplies the picture behind the noun.","exampleCN":"这个动词提供了名词背后的画面。"},{"word":"social","structure":"socialis through Old French social","meaning":"relating to society or companions","meaningCN":"与社会或同伴有关的","example":"Social history studies groups rather than single lives.","exampleCN":"社会史研究群体而非单个人的生活。"},{"word":"socially","structure":"social + -ly","meaning":"in a social manner; with respect to society","meaningCN":"在社交上；就社会而言","example":"The two groups are socially distant but economically linked.","exampleCN":"这两个群体在社会上相距很远，经济上却相连。"},{"word":"socialize","structure":"social + -ize","meaning":"to make social; to mix with others","meaningCN":"使社会化；与人交往","example":"Children socialize through play long before formal school.","exampleCN":"儿童在正式入学之前很久就通过游戏进行社交。"},{"word":"socialization","structure":"socialize + -ation","meaning":"the process of learning to live in a society","meaningCN":"学会在社会中生活的过程","example":"Socialization transmits the habits a group expects.","exampleCN":"社会化传递一个群体所期待的习性。"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"socialis","structure":"socialis, sociale (adjective, third declension)","meaning":"of companions, allied","meaningCN":"同伴的；结盟的"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, community","meaningCN":"结社；共同体"},{"word":"status","structure":"status, status (m., fourth declension)","meaning":"standing, position","meaningCN":"站立状态；位置"},{"word":"stare","structure":"stare, steti, statum (verb, first conjugation)","meaning":"to stand","meaningCN":"站立"}]}},{"word":"gender","ipa_uk":"/ˈdʒendə/","ipa_us":"/ˈdʒendər/","definition_zh":"性别；社会性别；（名词的）语法性；种类（古义）","definition_en":"the categories of male and female together with the social roles and identities linked to them; also a grammatical class of nouns","core_image":"同样的盒子贴着两色标签，颜色由贴标签的人决定，而不是由盒子本身决定。","scene":"图书馆的表格上，姓名之后留着一栏，填表的人可以自己决定写什么。The form leaves gender blank until the applicant chooses how to describe herself.","sceneCN":"这里 gender 指「个人在男性、女性或其他类别中的自我归属」（第 1 个义项：性别归属）；句意为表格把性别一栏留空，等申请人自己选择如何描述。可辨识物件：表格、空格、铅笔、姓名栏。","pos":[{"tag":"n.","zh":"性别；社会性别；语法性；种类（古义）"},{"tag":"adj.","zh":"作定语：性别方面的，如性别角色"}],"collocations":[{"phrase":"gender equality","zh":"性别平等"},{"phrase":"gender roles","zh":"性别角色"},{"phrase":"gender gap","zh":"性别差距"},{"phrase":"gender identity","zh":"性别认同"},{"phrase":"gender stereotypes","zh":"性别刻板印象"},{"phrase":"gender-neutral","zh":"不分性别的；中性措辞的"}],"forms":[{"label":"原形（名词）","form":"gender"},{"label":"复数","form":"genders"},{"label":"形容词（有性别色彩的）","form":"gendered"},{"label":"复合定语","form":"gender-based"},{"label":"相关名词短语","form":"gender identity"}],"derivatives":[{"word":"gendered","pos":"adj.","zh":"gender + -ed（形容词后缀）→ 由「性别」转为「被赋予性别色彩的」"},{"word":"gendering","pos":"n./v.","zh":"gender + -ing（动名词后缀）→ 由「性别」转为「赋予性别、按性别划分的过程」"},{"word":"genderless","pos":"adj.","zh":"gender + -less（否定后缀）→ 由「性别」转为「无性别标记的」"},{"word":"misgender","pos":"v.","zh":"gender + mis-（错误前缀）→ 由「性别」转为「错误地称呼或指认他人的性别」"},{"word":"gender-neutral","pos":"adj.","zh":"gender + neutral（复合词）→ 由「性别」转为「不区分性别的」"}],"senses":[{"no":"01","title":"Noun class in grammar","titleCN":"名词的语法性别","definition":"one of the classes into which a language sorts nouns, often marked masculine, feminine or neuter","definitionCN":"语言为名词划分的类别之一，常标为阳性、阴性或中性","example":"In French, gender decides whether the article is le or la.","exampleCN":"在法语中，语法性别决定冠词用 le 还是 la。","why":"the word began as a grammar term: nouns were grouped by kind, and the groups were called genders.","whyCN":"这个词最初是语法术语：名词按类别分组，这些组就叫语法性别。"},{"no":"02","title":"Socially constructed role expectations","titleCN":"社会建构的角色期待","definition":"the behaviour, duties and expectations a society attaches to being a man or a woman","definitionCN":"社会加诸身为男性或女性的行为、职责与期待","example":"The study asks how gender shapes who is expected to cook at home.","exampleCN":"这项研究追问性别如何塑造「谁该在家做饭」的期待。","why":"twentieth-century scholarship separated this social layer from the older grammar term and made it the dominant sense.","whyCN":"二十世纪学术把这一社会层面与旧的语法术语分开，并使它成为主导义。"},{"no":"03","title":"Biological classification","titleCN":"生理性别的分类","definition":"the grouping of organisms as male or female by reproductive anatomy and function","definitionCN":"按生殖解剖结构与功能把生物分为雄性、雌性","example":"Some fish change gender as they mature.","exampleCN":"有些鱼在成熟过程中会改变生理性别。","why":"biology borrowed the word for the reproductive categories themselves, apart from social roles.","whyCN":"生物学借用这个词来指生殖类别本身，与社会角色无关。"},{"no":"04","title":"A person's felt identity","titleCN":"个人的性别认同","definition":"the sense a person has of being male, female or another category, whether or not it matches birth records","definitionCN":"个人对自身属于男性、女性或其他类别的感受，无论是否与出生记录一致","example":"The clinic lets patients describe their gender in their own words.","exampleCN":"诊所让就诊者用自己的话描述性别认同。","why":"if gender is a role, then who one is as gendered cannot be read off the body alone.","whyCN":"如果性别是一种角色，那么一个人作为性别主体的身份就不能只从身体读出。"},{"no":"05","title":"Analytical category in social science","titleCN":"社会科学中的分析范畴","definition":"a category used to compare how resources, labour and power are distributed between men and women","definitionCN":"用于比较资源、劳动与权力在男女之间如何分配的范畴","example":"Gender is a standard variable in studies of wages and care work.","exampleCN":"在研究工资与照护劳动时，性别是一个标准变量。","why":"once separated from grammar, the word became a tool for measuring unequal arrangements.","whyCN":"一旦与语法分开，这个词就成了衡量不平等安排的工具。"},{"no":"06","title":"Gender forms inside language","titleCN":"语言中的性别形式","definition":"the distinctions a language makes in pronouns, agreement and titles to mark male or female reference","definitionCN":"语言在代词、一致关系与称谓上为标示男性或女性所指而作出的区分","example":"English marks gender in pronouns but barely in nouns.","exampleCN":"英语在代词上标出性别，在名词上却几乎没有。","why":"this sense returns to grammar but focuses on forms rather than on noun classes.","whyCN":"这一义项回到语法，却聚焦于形式而非名词类别。"},{"no":"07","title":"Kind or sort, the old sense","titleCN":"古义：种类、类别","definition":"a kind or sort of thing, the sense the word carried when it first entered English","definitionCN":"事物的种类或类别，这是该词初入英语时携带的含义","example":"The archaic phrase all genders of goods meant every kind of merchandise.","exampleCN":"古语短语「商品的所有种类」意为各类商品。","why":"the oldest English sense is simply kind, which is what Latin genus meant.","whyCN":"英语中最早的义项就是种类，也就是拉丁 genus 的意思。"},{"no":"08","title":"A dimension in policy","titleCN":"政策中的性别维度","definition":"a formal axis used to check whether rules, budgets or services affect men and women differently","definitionCN":"用来检查规则、预算或服务是否对男女产生不同影响的正式维度","example":"Every budget line is reviewed for its gender impact.","exampleCN":"每条预算项目都要审查其性别影响。","why":"governments turned the analytical category into an administrative checkpoint.","whyCN":"政府把这一分析范畴变成了行政审查环节。"}],"etymology":{"intro":{"en":"Gender comes from Old French gendre, from Latin genus, generis 'kind, race, stock'. It entered English first as a grammar term, and the biological and social senses are twentieth-century developments. Dates are approximate.","cn":"gender 来自古法语 gendre，源于拉丁 genus、generis「种类、族类」。它初入英语时是语法术语，生理与社会义都是二十世纪的演变。年代均为约数。"},"items":[{"era":"LATIN GENUS","en":"genus meant 'kind, race, stock, family'. Its deeper origin is source uncertain; the older root sometimes cited for it is a reconstruction.","cn":"genus 意为「种类、族类、血统、家族」。其更深来源不确定；有人为它引用的更早词根属于重构形式。"},{"era":"LATIN GENERIS","en":"generis is the genitive singular of genus; the stem gener- is the form that passed through French into English.","cn":"generis 是 genus 的单数属格；进入法语再进入英语的正是 gener- 这个词干。"},{"era":"OLD FRENCH GENDRE","en":"Old French gendre meant 'kind' and also named the grammatical classes of nouns; Middle English borrowed it as gendre.","cn":"古法语 gendre 意为「种类」，也指名词的语法类别；中古英语把它借入为 gendre。"},{"era":"GRAMMAR SENSE","en":"From the fourteenth century the word was used for the masculine, feminine and neuter classes of nouns, and this remained its main sense for centuries.","cn":"从十四世纪起，这个词用于名词的阳性、阴性与中性类别，此后数百年间这都是它的主要义项。"},{"era":"KIND SENSE","en":"The plain sense 'kind or sort' stayed in use alongside the grammar sense and is now archaic in everyday speech.","cn":"「种类、类别」这一朴素义与语法义长期并存，如今在日常语言中已属古旧。"},{"era":"MODERN SENSE","en":"The biological sense is a twentieth-century extension, and the social sense is generally thought to have spread through mid-twentieth-century psychology and sociology.","cn":"生理义是二十世纪的扩展；一般认为社会义经二十世纪中期心理学与社会学传播开来。"}]},"similar":{"note":{"en":"Group one holds words that look close to gender but come from a different Greek or Latin branch; group two holds terms for sex and desire that are often confused with it.","cn":"第一组是与 gender 形近、却出自不同希腊或拉丁分支的词；第二组是常与它混淆的性、欲望相关词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gene","ipa":"/dʒiːn/","tag":"unit of heredity","definition":"Coined in the early twentieth century from Greek genos 'birth, race', not from Latin genus: a unit of heredity, with no grammatical or social meaning.","definitionCN":"二十世纪初据希腊 genos「出生、族类」造出，而非来自拉丁 genus：指遗传单位，没有语法或社会含义。"},{"word":"genus","ipa":"/ˈdʒiːnəs/","tag":"the Latin source","definition":"The Latin noun itself, used in biology for a rank above species; it is the direct source of gender, but it names a taxonomic class rather than a person's identity.","definitionCN":"就是那个拉丁名词，生物学中用作高于物种的等级；它是 gender 的直接来源，却指分类层级，而非个人身份。"},{"word":"genre","ipa":"/ˈʒɑːnrə/","tag":"artistic category","definition":"A French branch of the same Latin genus: a category of art or writing. It is a cousin of gender, not a synonym, and carries no idea of sex.","definitionCN":"同一拉丁 genus 的法语分支：指艺术或写作的类别。它是 gender 的表亲而非同义词，不含性别之意。"},{"word":"generic","ipa":"/dʒəˈnerɪk/","tag":"of a whole kind","definition":"Latin gener- plus -ic: belonging to a whole class rather than a specific member, as in a generic drug or a generic label.","definitionCN":"拉丁 gener- 加 -ic：属于整个类别而非特定成员，如通用药物或通用标签。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sex","ipa":"/seks/","tag":"biological category","definition":"The biological categories of male and female, or sexual activity; gender is the social and identity layer that may or may not match it.","definitionCN":"指雄雌的生理类别，或性行为；gender 是可能与之相符也可能不符的社会与认同层面。"},{"word":"sexuality","ipa":"/sekʃuˈæləti/","tag":"patterns of attraction","definition":"A person's sexual orientation and capacity for attraction; it concerns desire, not the rank or role that gender names.","definitionCN":"指个人的性取向与产生吸引的能力；它关乎欲望，而非 gender 所指的位次或角色。"},{"word":"orientation","ipa":"/ˌɔːriənˈteɪʃən/","tag":"direction of attraction","definition":"The direction of sexual or romantic attraction; a narrower term than gender and not a category of identity in the same sense.","definitionCN":"指性方面或情感方面受吸引的方向；比 gender 窄，也不是同一意义上的身份类别。"},{"word":"sexism","ipa":"/ˈseksɪzəm/","tag":"discrimination by sex","definition":"Prejudice or discrimination based on sex; it names a practice, while gender names the category that the practice polices.","definitionCN":"基于生理性别的偏见或歧视；它命名一种做法，而 gender 命名这种做法所规训的类别。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin genus 'kind' became French gendre: a class, first of nouns, later of people.","cn":"拉丁 genus「种类」变成法语 gendre：先是名词的类别，后来是人的类别。"},{"en":"The family runs gendered, gendering, genderless, misgender, gender-neutral.","cn":"同族词包括 gendered、gendering、genderless、misgender、gender-neutral。"},{"en":"Fixed phrases mark public debate: gender equality, gender roles, gender gap.","cn":"固定搭配标出公共议题：性别平等、性别角色、性别差距。"},{"en":"Grammar is the oldest layer: French nouns take le or la by gender.","cn":"语法是最早的层面：法语名词按语法性别取 le 或 la。"},{"en":"The social sense is recent, roughly mid-twentieth century, not medieval.","cn":"社会义出现得晚，大约在二十世纪中期，并非中世纪产物。"}],"abstract":[{"en":"Picture two identical boxes given different coloured labels by the person holding the pen.","cn":"想象两个一模一样的盒子，标签颜色由拿笔的人决定。"},{"en":"Picture a noun waiting at a counter to be told which line it belongs to.","cn":"想象一个名词在柜台前等着被告知属于哪一队。"},{"en":"Picture a form with one blank that each person fills in their own hand.","cn":"想象一张表格，只有一个空格，每个人用自己的笔迹填写。"}]},"examples":[{"en":"The report measures the gender gap in promotions rather than in hiring.","cn":"这份报告衡量的是晋升中的性别差距，而非招聘中的差距。"},{"en":"Latin has three genders, and some languages have none.","cn":"拉丁语有三个语法性别，有些语言则一个也没有。"},{"en":"The policy treats gender as a budget dimension, not a private matter.","cn":"该政策把性别当作预算维度，而非私事。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「gen（种类）+ der」——先给名词分种类，再给人分种类 → 语法性别、社会性别","word":"gender"},"root":"古法语 gendre < 拉丁 genus、generis「种类、族类」；原为语法术语，指名词的语法性别；生理与社会义为 20 世纪演变；genus 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one move, sorting into kinds: nouns are sorted by grammar, people by social expectation, bodies by biology, selves by identity, data by analysis, language by forms, old texts by the plain sense of kind, and budgets by policy.","cn":"八个义项沿同一个动作展开，即分门别类：名词按语法分，人按社会期待分，身体按生理分，自我按认同分，数据按分析分，语言按形式分，古文本按「种类」的朴素义分，预算按政策分。"},"semanticMap":{"core":{"en":"CORE IMAGE: labels stuck onto boxes of the same shape, the colour chosen by the hand holding the label.","cn":"核心意象：标签贴在形状相同的盒子上，颜色由拿标签的那只手选定。"},"chain":["SORT THE NOUN","ASSIGN THE ROLE","READ THE BODY","NAME THE SELF","MEASURE THE GAP","AUDIT THE RULE"],"branches":[{"senses":"01 · 06","en":"GRAMMAR TWICE: first the class of a noun, later the forms pronouns and titles use to mark it.","cn":"两次回到语法：先指名词的类别，后指代词与称谓用来标示它的一整套形式。"},{"senses":"02 · 03","en":"ROLE AND BODY: one reading is what society expects, the other what anatomy records.","cn":"角色与身体：一种读法是社会的期待，另一种读法是解剖的记录。"},{"senses":"04 · 05","en":"SELF AND DATA: identity is felt from inside, while the analytical category is counted from outside.","cn":"自我与数据：认同从内部感受，分析范畴则从外部计数。"},{"senses":"07","en":"OLD KIND: strip away sex and grammar, and the word still means a sort of thing.","cn":"古老的种类义：抽去性与语法，这个词仍然只指一类事物。"},{"senses":"08","en":"POLICY AXIS: the category becomes a checkpoint applied to every budget line.","cn":"政策轴线：这个范畴变成适用于每条预算项目的审查关卡。"}]},"affixes":{"intro":{"en":"Gender is a Latin noun that came through French with almost no suffix of its own, so its family is built by adding English endings to the bare stem.","cn":"gender 是经法语传来的拉丁名词，本身几乎没有后缀，因此它的词族靠在裸词干上加英语词尾来构成。"},"latinIntro":{"en":"Latin genus, generis gives the stem gener-, seen in generare and generatio; English gender, gendered, gendering, genderless and misgender all grow from that stem.","cn":"拉丁 genus、generis 提供 gener- 词干，见于 generare 与 generatio；英语 gender、gendered、gendering、genderless 与 misgender 都从这个词干长出。"},"items":[{"word":"genus","structure":"genus, generis (Latin noun, third declension)","meaning":"kind, race, stock, family","meaningCN":"种类；族类；血统；家族","example":"The noun names a class of things sharing a origin.","exampleCN":"这个名词指共享同一来源的一类事物。"},{"word":"generis","structure":"genitive singular of genus","meaning":"of a kind, of a race","meaningCN":"种类的；族类的","example":"The genitive form supplies the stem gener- for the whole family.","exampleCN":"这个属格形式为整个词族提供了 gener- 词干。"},{"word":"generare","structure":"generare, generavi, generatum (Latin verb, first conjugation)","meaning":"to beget, produce, generate","meaningCN":"生育；产生；生成","example":"The verb names the act of bringing a kind into being.","exampleCN":"这个动词指使一类事物产生出来的动作。"},{"word":"generatio","structure":"generare + -tio (Latin noun, third declension)","meaning":"a begetting, a generation","meaningCN":"生育；一代人","example":"The noun names the result of the begetting.","exampleCN":"这个名词指生育所产生的结果。"},{"word":"gender","structure":"genus through Old French gendre","meaning":"kind; grammatical class; social category of sex","meaningCN":"种类；语法类别；社会性别","example":"The English word kept the old sense of kind beside the grammar sense.","exampleCN":"这个英语词在语法义之外保留了古老的种类义。"},{"word":"gendered","structure":"gender + -ed","meaning":"marked by or divided by gender","meaningCN":"带有性别标记的；按性别划分的","example":"The division of labour in the household is strongly gendered.","exampleCN":"家庭中的分工带有强烈的性别色彩。"},{"word":"gendering","structure":"gender + -ing","meaning":"the act of assigning gender","meaningCN":"赋予性别；按性别归类的过程","example":"Gendering begins early in the toys children are offered.","exampleCN":"性别归类很早就始于给孩子的玩具。"},{"word":"genderless","structure":"gender + -less","meaning":"without gender marking","meaningCN":"无性别标记的","example":"The label uses a genderless job title.","exampleCN":"这个标签使用无性别指向的职位名称。"},{"word":"misgender","structure":"mis- + gender","meaning":"to refer to someone with the wrong gender","meaningCN":"错误地称呼或指认他人的性别","example":"A careless form can misgender a respondent.","exampleCN":"一张粗心的表格可能错误指认填表人的性别。"}],"latinEntries":[{"word":"genus","structure":"genus, generis (n., third declension)","meaning":"kind, race, stock","meaningCN":"种类；族类；血统"},{"word":"generare","structure":"generare, generavi, generatum (verb, first conjugation)","meaning":"to beget, produce","meaningCN":"生育；产生"},{"word":"generatio","structure":"generatio, generationis (f., third declension)","meaning":"begetting, generation","meaningCN":"生育；世代"}]}}]);
